@app.post("/admin/tools/communities/{community_id}/mark-reviewed")
async def admin_communities_mark_reviewed(request: Request, community_id: int):
    """Clears community_profiles.needs_review — pre-existing action, now
    also logged to narrative_review_log (Phase G PR 2, field_type=
    'community_profile') so "Reviewed by X on Y" can render wherever this
    flag is shown, same as Agent taxonomy/Description/Differentiation's
    "Mark verified". detail snapshots verdict_summary (the profile's
    one-line "Best for X, not for Y" takeaway) as of this click — the most
    representative single field to keep, mirroring how the other verify
    routes snapshot their field's own text."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    lib = _lib()
    try:
        community = lib.get_community(community_id)
        # Called from the admin list row (no redirect_to — stay on the
        # list, its original behavior), the community edit page (Phase G PR 2),
        # and now the public profile VIEW page too (2026-08 consolidation—
        # the same "Review status" component's action button) — validated
        # against an allowlist since it echoes into a redirect, same
        # convention as admin_tools_delete.
        redirect_to = form.get("redirect_to") or "/admin/tools/communities"
        _allowed = {"/admin/tools/communities"}
        if community:
            # The public profile view, and the merged edit page (PR 2a: the
            # profile lives there now, so its verification buttons return to it).
            _allowed.add(f"/tools/communities/{community['slug']}")
            _allowed.add(f"/tools/communities/{community['slug']}/edit")
        if redirect_to not in _allowed:
            redirect_to = "/admin/tools/communities"
        profile = lib.get_community_profile(community_id)
        lib.mark_community_profile_reviewed(community_id)
        lib.record_narrative_review(
            _current_user_id(lib, request), "community", "community_profile", community_id,
            detail=(profile or {}).get("verdict_summary") or "",
        )
    finally:
        lib.close()
    return RedirectResponse(redirect_to, status_code=303)


@app.post("/admin/tools/communities/{community_id}/flag-for-review")
async def admin_communities_flag_for_review(request: Request, community_id: int):
    """One-click "Flag for review" (2026-08 quick-toggle follow-up) — the
    mirror of admin_communities_mark_reviewed above: lets an admin flag a
    profile as needing review straight from the admin list, without opening
    the profile edit form. Deliberately does NOT touch narrative_review_log
    (flagging isn't a confirmation — that table only ever records the
    OPPOSITE action, an explicit "I reviewed this"), and does NOT clear any
    existing "Reviewed by X on Y" stamp — same as checking the needs_review
    checkbox on the edit form itself already does (or rather, doesn't)."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    form = await request.form()
    lib = _lib()
    try:
        community = lib.get_community(community_id)
        redirect_to = form.get("redirect_to") or "/admin/tools/communities"
        _allowed = {"/admin/tools/communities"}
        if community:
            # The public profile view, and the merged edit page (PR 2a: the
            # profile lives there now, so its verification buttons return to it).
            _allowed.add(f"/tools/communities/{community['slug']}")
            _allowed.add(f"/tools/communities/{community['slug']}/edit")
        if redirect_to not in _allowed:
            redirect_to = "/admin/tools/communities"
        lib.flag_community_profile_needs_review(community_id)
    finally:
        lib.close()
    return RedirectResponse(redirect_to, status_code=303)


