@app.post("/admin/tools/software/{tool_id}/research/refresh")
def admin_tools_research_refresh(request: Request, tool_id: int):
    """On-demand re-run of _run_tool_research — same drafting logic as the
    automatic on-add trigger, run synchronously here (a manual, occasional
    admin action) so the redirect banner can report success/failure."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    tool = lib.get_tool(tool_id)
    lib.close()
    if not tool:
        raise HTTPException(status_code=404, detail="Tool not found")
    ok, reason, url = _run_tool_research(tool_id)
    if ok:
        msg = "research_refreshed=1"
    elif reason.startswith(_UNCITED_PREFIX):
        # UncitedDraft (issue #642): nothing was saved, the old note and its
        # Sources are kept.
        msg = f"research_refreshed=uncited&research_reason={reason[len(_UNCITED_PREFIX):]}"
    elif reason:
        # GroundingUnavailable (2026-09 JS-render grounding fix) — an honest,
        # specific reason+URL instead of the generic "couldn't complete the
        # research pass" every other failure still falls back to.
        from urllib.parse import quote
        msg = f"research_refreshed=grounding&research_reason={quote(reason)}&research_url={quote(url)}"
    else:
        msg = "research_refreshed=0"
    return RedirectResponse(f"/tools/software/{tool['slug']}/edit?{msg}", status_code=303)


