@app.post("/admin/tools/software/{tool_id}/quick-edit")
async def admin_tools_quick_edit(request: Request, tool_id: int):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Invalid request"}, status_code=400)
    description = (body.get("description") or "").strip()
    summary = (body.get("summary") or "").strip()
    warm_intro_enabled = 1 if body.get("warm_intro_enabled") else 0
    vendor_name = (body.get("vendor_name") or "").strip()
    vendor_email = (body.get("vendor_email") or "").strip()
    if not (description and summary):
        return JSONResponse({"ok": False, "error": "Description and summary are required"}, status_code=400)
    lib = _lib()
    try:
        if not lib.get_tool(tool_id):
            return JSONResponse({"ok": False, "error": "Tool not found"}, status_code=404)
        lib.quick_update_tool(tool_id, description, warm_intro_enabled, vendor_name, vendor_email, summary=summary,
                              source="admin-edit")
    except ValueError as e:
        return JSONResponse({"ok": False, "error": str(e)}, status_code=400)
    finally:
        lib.close()
    return JSONResponse({"ok": True, "tool": {
        "description": description,
        "summary": summary,
        "warm_intro_enabled": bool(warm_intro_enabled),
        "vendor_name": vendor_name,
        "vendor_email": vendor_email,
        "has_warm_intro": bool(warm_intro_enabled and vendor_email),
    }})


@app.post("/admin/tools/software/generate-description")
async def admin_tools_generate_description(request: Request):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Invalid request"}, status_code=400)
    name = (body.get("name") or "").strip()
    url = (body.get("url") or "").strip()
    if not (name and url):
        return JSONResponse({"ok": False, "error": "Name and URL are required."}, status_code=400)

    from linklib.voice_settings import VoicePromptMissing, require_voice_setting
    lib = _lib()
    try:
        model = lib.get_enrich_model()
        exa_enabled = lib.get_exa_enabled()
        try:
            voice_core = require_voice_setting(lib, "voice_core")
        except VoicePromptMissing as e:
            return JSONResponse({"ok": False, "error": str(e)}, status_code=503)
    finally:
        lib.close()
    from linklib import enrich as enrich_mod
    try:
        draft = enrich_mod.generate_tool_description(name, url, model=model, voice_core=voice_core,
                                                      exa_enabled=exa_enabled)
    except enrich_mod.GroundingUnavailable as e:
        return JSONResponse({"ok": False, "error": _grounding_unavailable_error(e)}, status_code=503)
    except enrich_mod.UncitedDraft as e:
        _record_uncited_draft_cost(e)
        return JSONResponse({"ok": False, "error": _uncited_draft_error(e)}, status_code=503)
    if draft is None:
        return JSONResponse({"ok": False, "error": "Description generation is unavailable right now "
                                                     "(missing ANTHROPIC_API_KEY, or the request failed). "
                                                     "Write the description by hand."}, status_code=503)

    lib = _lib()
    try:
        lib.record_enrichment_cost(None, draft.model, draft.input_tokens, draft.output_tokens, draft.cost_usd)
        if draft.exa_cost_usd:
            lib.record_enrichment_cost(None, "exa-fetch", 0, 0, draft.exa_cost_usd)
    finally:
        lib.close()

    return JSONResponse({"ok": True, "description": draft.description, "summary": draft.summary,
                         "low_confidence": draft.low_confidence, "confident": draft.confident,
                         "citations": draft.citations, "model": draft.model})


@app.post("/admin/tools/software/{tool_id}/generate-differentiation")
def admin_tools_generate_differentiation(request: Request, tool_id: int):
    """Drafts the "Bottom line" callout into the edit form — never
    auto-saved, standing AI-first-pass-then-human-review principle. Grounded
    in the tool's own description + curated competitors, so it needs the
    tool_id (unlike generate-description, which is stateless)."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    from linklib.voice_settings import VoicePromptMissing, require_voice_setting
    lib = _lib()
    try:
        tool = lib.get_tool(tool_id)
        if not tool:
            raise HTTPException(status_code=404, detail="Tool not found")
        competitor_names = [c["name"] for c in lib.list_tool_competitors(tool_id)]
        model = lib.get_enrich_model()
        try:
            voice_core = require_voice_setting(lib, "voice_core")
        except VoicePromptMissing as e:
            raise HTTPException(status_code=503, detail=str(e))
    finally:
        lib.close()

    from linklib.enrich import generate_tool_differentiation
    draft = generate_tool_differentiation(tool["name"], tool["url"], tool.get("description", ""), competitor_names,
                                           model=model, voice_core=voice_core)
    if draft is None:
        return JSONResponse({"ok": False, "error": "Generation is unavailable right now "
                                                     "(missing ANTHROPIC_API_KEY, or the request failed). "
                                                     "Write it by hand."}, status_code=503)

    lib = _lib()
    try:
        lib.record_enrichment_cost(None, draft.model, draft.input_tokens, draft.output_tokens, draft.cost_usd)
    finally:
        lib.close()

    return JSONResponse({"ok": True, "competitive_differentiation": draft.competitive_differentiation,
                         "low_confidence": draft.low_confidence, "confident": draft.confident})


@app.post("/admin/tools/software/{tool_id}/competitors/generate-matches")
def admin_tools_generate_competitor_matches(request: Request, tool_id: int):
    """AI first pass over the tag-overlap suggestion shortlist (see
    suggest_tool_competitors) — judges which candidates are genuine
    competitors. Never writes to tool_competitors; the admin UI pre-checks
    the returned ids and a human still clicks Add selected, same
    generate-then-review contract as every other field."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        tool = lib.get_tool(tool_id)
        if not tool:
            raise HTTPException(status_code=404, detail="Tool not found")
        candidates = lib.suggest_tool_competitors(tool_id, limit=8)
        model = lib.get_enrich_model()
    finally:
        lib.close()

    from linklib.enrich import generate_competitor_matches
    result = generate_competitor_matches(
        tool["name"], tool.get("description", ""),
        [{"id": c["id"], "name": c["name"], "description": c.get("description", "")} for c in candidates],
        model=model,
    )
    if result is None:
        return JSONResponse({"ok": False, "error": "Generation is unavailable right now "
                                                     "(missing ANTHROPIC_API_KEY, no candidates, or the request failed). "
                                                     "Pick competitors by hand."}, status_code=503)

    lib = _lib()
    try:
        lib.record_enrichment_cost(None, result.model, result.input_tokens, result.output_tokens, result.cost_usd)
    finally:
        lib.close()

    return JSONResponse({"ok": True, "competitor_ids": result.competitor_ids})


@app.post("/admin/tools/software/{tool_id}/competitors/add-selected")
async def admin_tools_competitors_add_selected(request: Request, tool_id: int):
    """Batch-add version of /competitors/add — accepts multiple competitor_id
    values from the suggestions checkbox list in one submit, so the AI-drafted
    matches from generate-matches above can be reviewed as a group and saved
    together rather than one instant-add click per candidate."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        tool = lib.get_tool(tool_id)
        if not tool:
            raise HTTPException(status_code=404, detail="Tool not found")
        form = await request.form()
        ids = []
        for raw in form.getlist("competitor_id"):
            try:
                ids.append(int(raw))
            except ValueError:
                continue
        for cid in ids:
            if lib.get_tool(cid):
                try:
                    lib.add_tool_competitor(tool_id, cid)
                except ValueError:
                    pass
        _record_ai_drafted_reviews(lib, request, "tool", tool_id, form)
    finally:
        lib.close()
    return RedirectResponse(f"/tools/software/{tool['slug']}/edit", status_code=303)


@app.post("/tools/{tool_id}/interest")
async def tools_interest(tool_id: int, request: Request):
    _require_member(request)
    try:
        body = await request.json()
    except Exception:
        return JSONResponse({"ok": False, "error": "Invalid request"}, status_code=400)
    name = (body.get("name") or "").strip()
    email = (body.get("email") or "").strip()
    company = (body.get("company") or "").strip()
    company_size = (body.get("company_size") or "").strip()
    if not (name and email and company and company_size):
        return JSONResponse({"ok": False, "error": "All fields are required"}, status_code=400)
    lib = _lib()
    try:
        tools = lib.list_tools(approved_only=True)
        tool = next((t for t in tools if t["id"] == tool_id), None)
        if not tool:
            return JSONResponse({"ok": False, "error": "Tool not found"}, status_code=404)
        # Same eligibility check the UI uses to decide whether to show the
        # button at all — enforced here too, not just client-side, since
        # nothing stops a direct POST to this endpoint.
        vendor_email = tool.get("vendor_email") or ""
        if not (tool.get("warm_intro_enabled") and vendor_email):
            return JSONResponse({"ok": False, "error": "Warm intro isn't available for this tool"}, status_code=400)
        tool_name = tool["name"]
        vendor_name = tool.get("vendor_name") or ""
        lib.save_tool_lead(tool_id, tool_name, name, email, company, company_size)
        from linklib.email_utils import send_warm_intro_email
        _send_email_safely(
            lib, "warm_intro", send_warm_intro_email,
            to=vendor_email,
            vendor_contact_name=vendor_name,
            cc=email,
            tool_name=tool_name,
            requester_name=name,
            requester_email=email,
            requester_company=company,
            requester_company_size=company_size,
            subject_template=lib.get_setting("warm_intro_subject_template") or None,
            body_template=lib.get_setting("warm_intro_body_template") or None,
            signoff=lib.get_setting("warm_intro_signoff") or None,
        )
    finally:
        lib.close()
    return JSONResponse({"ok": True})


