OPML_PATH = os.environ.get("LINKLIB_SITES_OPML", os.path.join(_APP_DIR, "preferred_sites.opml"))


def _resolve_reader_content(id: int = 0, url: str = "", user_id: int | None = None) -> dict | None:
    """Resolve an id-or-url to reader content: DB lookup by id first (using
    cached content when it's substantial), falling back to a live fetch by
    url. Shared by GET /read/{article_id} (a standalone HTML page) and
    GET /api/read-article (the JSON endpoint the merged /read page's reader
    pane calls) — exactly one implementation of "resolve id-or-url to article
    content," not two. Returns None when neither an id nor a url resolves to
    anything.

    `user_id` (2026-08 Reader cleanliness pass) additionally checks the
    signed-in user's Read Later list for a cached copy of this url, used only
    as a fallback BELOW an Archive article's own cache — an Archive save's
    backfilled content_html is always the strict upgrade, so this never
    competes with it, only fills in when there's no `articles` row at all (or
    the row itself has nothing cached yet). Optional and defaults to None
    (skips the Read Later lookup entirely) so `reader_single`'s by-id call,
    which can never resolve to a Read Later row anyway, doesn't need to
    thread a user_id through for no benefit."""
    from linklib.extract import fetch_page, extract_reader_html
    import html as html_mod

    article = None
    matched_by_url = False
    if id:
        lib = _lib()
        try:
            row = lib.conn.execute("SELECT * FROM articles WHERE id=?", (id,)).fetchone()
            if row:
                article = dict(row)
                article["tags"] = json.loads(article.get("tags_json") or "[]")
        finally:
            lib.close()
        if article:
            url = article["url"]

    if not url:
        return None

    if article is None:
        # A Feed or Read Later row carries only a url. If that url is already in
        # the library (url is the natural key), resolve it to the real row so the
        # reader knows the article is saved — that's what gates the inline tag
        # editor, and it's what "any Feed item that's been saved" needs to work.
        lib = _lib()
        try:
            row = lib.conn.execute("SELECT * FROM articles WHERE url=?", (url,)).fetchone()
            if row:
                article = dict(row)
                article["tags"] = json.loads(article.get("tags_json") or "[]")
                matched_by_url = True
        finally:
            lib.close()

    rl_row = None
    if user_id is not None:
        lib = _lib()
        try:
            rl_row = lib.get_read_later_by_url(user_id, url)
        finally:
            lib.close()
    is_read_later = rl_row is not None

    # Only the plain-text `content` cache is skipped for a url-matched row:
    # using it there would silently downgrade a Feed item that currently reads
    # with images and links intact, whereas an explicit by-id open (an Archive-view
    # click) accepts it. Phase 5b's `content_html` is deliberately NOT skipped—
    # it's real structured HTML, so it's a strict upgrade over both the
    # plain-text cache and a live re-fetch, however the row was reached.
    cached_content = "" if matched_by_url else (article or {}).get("content", "")
    cached_content_html = (article or {}).get("content_html", "")
    cached_title = (article or {}).get("title", "")
    is_structured = False   # True whenever `content` is real HTML — either the
                             # Phase 5b backfill's stored content_html, or a live
                             # fetch's own extract_reader_html() output. A cached
                             # article's plain-text `content` (pre-backfill) can't
                             # carry images/links either way.
    content_via = "cache"   # 'cache' | 'direct' | 'wayback' | 'medium-fetch' |
                             # 'medium-search' — surfaced to the reader pane so
                             # a Wayback-archived read is visibly distinguishable
                             # from the live page, the same reasoning
                             # content_refetch_log's `source` column exists for
                             # the backfill tool's durable log (see
                             # linklib.wayback's module docstring). The reader
                             # pane's JS only special-cases 'wayback' today (a
                             # visible banner) — a medium-fetch/medium-search
                             # read shows no banner, same as an ordinary
                             # 'direct' read; only the Wayback case needed one,
                             # since an archived snapshot can be stale in a way
                             # a live-recovered fetch isn't. Not persisted
                             # anywhere — this is a live read, not a stored one.

    if cached_content_html:
        # Phase 5b backfill: this article was reprocessed and has real
        # structured HTML on file — always prefer it over the plain-text
        # `content` cache, since it's a strict upgrade (never re-fetched live
        # just because content_html happens to exist).
        title = cached_title or url
        content = cached_content_html
        is_structured = True
    elif cached_content and len(cached_content) > 200:
        title = cached_title or url
        content = cached_content
    elif rl_row and rl_row.get("content_html"):
        # Read Later's own cache (2026-08 Reader cleanliness pass) — only
        # reachable when there's no Archive article content above to prefer
        # already, so this never competes with a real Archive save's cache,
        # only fills in for a url that's ONLY ever been queued to Read Later.
        title = cached_title or rl_row.get("title") or url
        content = rl_row["content_html"]
        is_structured = True
    elif rl_row and rl_row.get("content") and len(rl_row["content"]) > 200:
        title = cached_title or rl_row.get("title") or url
        content = rl_row["content"]
    else:
        try:
            page = fetch_page(url)
            title = page.title or cached_title or url
            structured = extract_reader_html(page.raw_html, url) if page.raw_html else ""
            if structured:
                content = structured
                is_structured = True
                content_via = "direct"
            else:
                content = page.content or ""
                if content:
                    content_via = "direct"
        except Exception:
            title = cached_title or url
            content = ""

        if not content:
            # Bookmarklet title-extraction follow-up (2026-08): a direct
            # fetch of a recognized Cloudflare-blocked host (medium.com and
            # friends — see linklib.medium_platform.is_recognized_blocked_
            # host) never gets real HTML at all, so it never had a real
            # title or content to work from either way — confirmed live via
            # scripts/trace_medium_tier.py. Tried before the Wayback
            # fallback below, same ordering linklib.pipeline.
            # _finish_backfill_after_direct_failure uses and for the same
            # reason (this tier's hit rate is strong; Wayback is currently
            # unreliable — archive.org rate-limiting, see linklib.wayback's
            # module docstring). Reuses linklib.pipeline.medium_recovery
            # (itself a thin wrapper around the SAME _try_medium_platform
            # the offline content backfill uses) — no new fetch mechanism.
            # Best-effort and ephemeral, same as the Wayback fallback below:
            # never persisted here, this is a live read, not a stored one.
            from linklib import medium_platform as _medium_platform
            if _medium_platform.is_recognized_blocked_host(url):
                from linklib.pipeline import medium_recovery
                mp_lib = _lib()
                try:
                    recovered, _recovered_exa_cost = medium_recovery(
                        mp_lib, url, cached_title or title, (article or {}).get("author", ""))
                finally:
                    mp_lib.close()
                if recovered:
                    content = recovered["content_html"]
                    is_structured = True
                    content_via = recovered["source"]
                    if recovered["title"] and (not title or title == url):
                        title = recovered["title"]

        if not content:
            # Direct fetch failed outright (bot-block, dead link, timeout—
            # any reason) — last-resort Wayback fallback, same mechanism the
            # backfill tool uses (linklib.wayback). Best-effort: any Wayback
            # failure (including the 429 rate-limiting the Phase 5b follow-up
            # investigation found archive.org returns unpredictably — see
            # linklib.wayback's module docstring) just falls through to the
            # normal "Content could not be extracted" empty state below,
            # exactly as if this fallback didn't exist. Kept on
            # linklib.wayback's short timeout deliberately: this sits on an
            # interactive request, not a background job, and added latency
            # here is unverified pending archive.org's own rate limiting
            # clearing (see CLAUDE.md's Phase 5b follow-up note) — stays
            # conservative rather than generous until that's confirmed.
            from linklib import wayback as _wayback
            from linklib.extract import _page_data_from_html
            snap_url = _wayback.find_snapshot(url)
            if snap_url:
                snap_html = _wayback.fetch_snapshot(snap_url)
                if snap_html:
                    snap_page = _page_data_from_html(snap_html)
                    structured = extract_reader_html(snap_html, snap_url)
                    if structured:
                        content = structured
                        is_structured = True
                        content_via = "wayback"
                    elif snap_page.content:
                        content = snap_page.content
                        content_via = "wayback"
                    if content and (not title or title == url):
                        title = snap_page.title or title

    if content:
        if is_structured:
            body_html = content
            word_count = len(re.sub(r"<[^>]+>", " ", content).split())
        else:
            paragraphs = [p.strip() for p in content.split("\n\n") if p.strip()]
            body_html = "".join(f"<p>{html_mod.escape(p)}</p>" for p in paragraphs) if paragraphs else ""
            word_count = sum(len(p.split()) for p in paragraphs)
    else:
        body_html = ""
        word_count = 0

    tags = (article or {}).get("tags", [])
    category = tags[0] if tags else (article or {}).get("source", "") or "Article"

    return {
        "id": article["id"] if article else None,
        "url": url,
        "title": title,
        "source": (article or {}).get("source", "") or (rl_row or {}).get("source", "") or "",
        "author": (article or {}).get("author", "") or "",
        "published_at": (article or {}).get("published_at", "") or "",
        "tags": tags,
        "category": category,
        "reading_minutes": max(1, round(word_count / 225)) if word_count else 0,
        "body_html": body_html,
        "has_content": bool(content),
        "content_via": content_via,
        # Gates the reader toolbar's "Refresh" button (2026-08 Reader
        # cleanliness pass) — only meaningful (and only ever True) when there's
        # no Archive `article` id, since an Archive save's own content isn't
        # what a Read Later refresh would change.
        "is_read_later": is_read_later and not article,
    }


@app.get("/api/read-article")
def api_read_article(request: Request, id: int = 0, url: str = ""):
    """Internal JSON endpoint the merged /read page's reader pane fetches
    into without a full page navigation. Admin-gated, same as /read itself."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    if not id and not url:
        raise HTTPException(status_code=400, detail="id or url required")
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
    finally:
        lib.close()
    data = _resolve_reader_content(id=id, url=url, user_id=user_id)
    if data is None:
        raise HTTPException(status_code=404, detail="not found")
    return JSONResponse(data)


_READER_CSS = """
/* 2026-09: Source Serif 4 removed sitewide, this page's last holdout—
   Brian's standing rule is Outfit or DM Sans only, ever, for content/
   reading typography (Caveat/Permanent Marker's decorative sticker/wordmark
   use is a separate, out-of-scope layer). Body now DM Sans, matching the
   merged Feed/Archive/Read Later reader's own settled typography (see
   CLAUDE.md's "Reader expand-mode icon + typography polish" bullet for the
   full back-and-forth that landed on DM Sans there first). .reader-meta h1
   already used Outfit — unchanged. */
@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@600;700&family=DM+Sans:opsz,wght@9..40,400;9..40,500&display=swap');
:root{--ink:#1a1a1a;--muted:#6F6A60;--line:#E4E0D6;--bg:#F5F4EF;--surface:#FFFFFF;--accent:#002975;
  --seafoam-deep:#1F7A66;--coral:#E8704F;--coral-wash:#FBEAE3;}
*{box-sizing:border-box;margin:0;padding:0;}
body{background:var(--bg);color:var(--ink);font:16px/1.65 'DM Sans',system-ui,-apple-system,'Segoe UI',sans-serif;}
a{color:var(--accent);text-decoration:underline;text-underline-offset:3px;}
a:hover{opacity:.8;}

.reader-bar{position:sticky;top:0;z-index:10;background:var(--surface);border-bottom:1px solid var(--line);
  padding:0 24px;height:48px;display:flex;align-items:center;justify-content:space-between;
  font-family:'DM Sans',sans-serif;font-size:13px;color:var(--muted);}
.reader-bar .back{color:var(--accent);text-decoration:none;font-weight:500;display:flex;align-items:center;gap:6px;}
.reader-bar .back:hover{opacity:.8;}
.reader-controls{display:flex;align-items:center;gap:16px;}
.reader-controls button{background:none;border:none;cursor:pointer;font:inherit;color:var(--muted);
  padding:4px 8px;border-radius:6px;font-size:13px;}
.reader-controls button:hover{background:var(--line);}

/* Standard tier (BRAND.md §5) — main column keeps a readable measure, the
   "On this page" TOC sits at the true right edge of the wide canvas.
   Tracks .page-standard's own max-width (PR 13, 2026-09: 1440px → 1300px,
   following the .page-full → .page-standard merge) even though this page is
   built from its own standalone _READER_TMPL/_READER_CSS and never uses the
   .page/.page-standard classes directly — see the _PAGE_INDEX_CUSTOM_EXCEPTIONS
   comment above naming this route page-standard. Deliberately never moved
   onto the Content tier PR 13 briefly introduced and PR 14 later removed
   (900px, 2026-09): .reader-main (760px) + .reader-toc (220px) + the 40px
   gap between them need ~1020px just for the two-column layout itself,
   before any side padding — squeezing the outer shell to 900px would
   force .reader-main (which has min-width:0, so it CAN shrink) below its own
   760px reading-column floor, which is exactly the measure this page exists
   to protect. Standard's 1300px keeps the same generous margin around that
   1020px content this route always had at wider values. */
.reader-layout{display:flex;justify-content:space-between;gap:40px;max-width:1300px;margin:0 auto;padding:56px 24px 100px;}
.reader-main{max-width:760px;min-width:0;}
.reader-toc{width:220px;flex-shrink:0;position:sticky;top:64px;align-self:flex-start;}
.reader-toc-title{font:600 11.5px 'DM Sans',sans-serif;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:12px;}
.reader-toc a{display:block;font:14px 'DM Sans',sans-serif;color:#3F5C9A;line-height:2.2;text-decoration:none;}
.reader-toc a:hover{text-decoration:underline;}
@media(max-width:1100px){
  .reader-toc{display:none;}
  .reader-layout{justify-content:center;}
  .reader-main{margin:0 auto;}
}
/* Layout fix batch 3 (PR 30): an article with no <h2>s hides the TOC via
   JS at ANY viewport width, not just the narrow breakpoint above — with
   .reader-toc removed from the flex layout entirely, .reader-main became
   the sole flex item and justify-content:space-between just left-anchored
   it, leaving real dead space where the TOC would have sat (measured
   ~496px at 1280px, same absolute gap at 1920px). The TOC-visibility JS
   below adds .no-toc to .reader-layout in that case; this mirrors the
   narrow-viewport rule above so a headingless article centers the same
   way a narrow viewport already does. */
.reader-layout.no-toc{justify-content:center;}
.reader-layout.no-toc .reader-main{margin:0 auto;}

.reader-meta{margin-bottom:40px;padding-bottom:32px;border-bottom:1px solid var(--line);}
.reader-meta h1{font-family:'Outfit',sans-serif;font-size:clamp(22px,4vw,32px);font-weight:600;line-height:1.25;letter-spacing:-.02em;
  margin-bottom:16px;}
.reader-meta .byline{font-family:'DM Sans',sans-serif;font-size:14px;color:var(--muted);line-height:1.5;}
.reader-meta .source-link{color:var(--accent);}

.reader-body{font-size:var(--fs,18px);line-height:1.78;}
.reader-body p{margin-bottom:1.4em;}
.reader-body h1,.reader-body h2,.reader-body h3,.reader-body h4{
  font-weight:600;line-height:1.3;letter-spacing:-.01em;margin:2em 0 .6em;}
.reader-body h1{font-size:1.5em;}
.reader-body h2{font-size:1.25em;}
.reader-body h3{font-size:1.1em;}
.reader-body ul,.reader-body ol{padding-left:1.5em;margin-bottom:1.4em;}
.reader-body li{margin-bottom:.4em;}
.reader-body blockquote{background:var(--coral-wash);border-left:4px solid var(--coral);border-radius:0 10px 10px 0;
  padding:18px 22px;color:var(--accent);font-style:italic;margin:1.5em 0;}
.reader-body img{max-width:100%;height:auto;border-radius:8px;margin:1.5em 0;}
.reader-body figure{margin:1.5em 0;}
.reader-body figcaption{font-size:.85em;color:var(--muted);font-family:'DM Sans',sans-serif;margin-top:.4em;}
.reader-body table{width:100%;border-collapse:collapse;font-size:.9em;margin:1.5em 0;}
.reader-body th,.reader-body td{padding:8px 12px;border:1px solid var(--line);text-align:left;}
.reader-body th{background:#f4f0e8;font-family:'DM Sans',sans-serif;}
.reader-body pre,.reader-body code{font-family:ui-monospace,monospace;font-size:.85em;
  background:#f0ece4;border-radius:4px;padding:2px 5px;}
.reader-body pre{padding:16px;overflow-x:auto;border-radius:8px;margin:1.5em 0;}
.reader-body pre code{background:none;padding:0;}
.reader-body hr{border:none;border-top:1px solid var(--line);margin:2.5em 0;}

.reader-empty{text-align:center;padding:60px 20px;color:var(--muted);font-family:'DM Sans',sans-serif;}
.reader-empty h2{font-size:18px;margin-bottom:12px;color:var(--ink);}
"""

_READER_TMPL = """<!doctype html><html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title}</title>
<link rel="icon" type="image/svg+xml" href="/static/favicon.svg">
<link rel="icon" type="image/png" sizes="32x32" href="/static/favicon-32.png">
<link rel="apple-touch-icon" href="/static/apple-touch-icon.png">
<style>{css}</style>
</head><body>
<div class="reader-bar">
  <a class="back" href="{back_url}">&#8592; {back_label}</a>
  <div class="reader-controls">
    <button onclick="adj(-2)">A&minus;</button>
    <button onclick="adj(2)">A+</button>
    {article_controls}
    <a href="{orig_url}" target="_blank" rel="noopener" style="color:var(--accent);text-decoration:none;font-size:13px;">Original &rarr;</a>
  </div>
</div>
<div class="reader-layout">
  <div class="reader-main">
    <div class="reader-meta">
      <h1>{heading}</h1>
      <div class="byline">{byline}</div>
      {tags_block}
    </div>
    <div class="reader-body">{body}</div>
  </div>
  <div class="reader-toc" id="reader-toc">
    <div class="reader-toc-title">On this page</div>
    <div id="reader-toc-list"></div>
  </div>
</div>
{article_script}
<script>
var fs = parseInt(localStorage.getItem('reader-fs') || '18');
document.documentElement.style.setProperty('--fs', fs + 'px');
function adj(d) {{
  fs = Math.max(14, Math.min(28, fs + d));
  document.documentElement.style.setProperty('--fs', fs + 'px');
  localStorage.setItem('reader-fs', fs);
}}
(function() {{
  var toc = document.getElementById('reader-toc');
  var headings = Array.prototype.filter.call(document.querySelectorAll('.reader-body h2'), function(h) {{
    return !h.closest('.reader-empty');
  }});
  if (!toc || !headings.length) {{
    if (toc) toc.style.display = 'none';
    var layout = document.querySelector('.reader-layout');
    if (layout) layout.classList.add('no-toc');
    return;
  }}
  var list = document.getElementById('reader-toc-list');
  var used = {{}};
  headings.forEach(function(h, i) {{
    var slug = (h.textContent || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') || ('section-' + i);
    while (used[slug]) {{ slug = slug + '-' + i; }}
    used[slug] = true;
    h.id = slug;
    var a = document.createElement('a');
    a.href = '#' + slug;
    a.textContent = h.textContent;
    list.appendChild(a);
  }});
}})();
</script>
</body></html>"""


@app.get("/read/{article_id}", response_class=HTMLResponse)
def reader_single(request: Request, article_id: int):
    """Standalone single-article view for a saved DB row — what the old
    GET /read?id=... did, now a path param. Admin-only (resale-safe): full
    article text isn't served to members. No inline tag-edit/delete controls
    (Phase 5 — those stay exclusively in /admin/library's dedicated tools);
    the only actions here are Read Later (personal bookmark) and font size."""
    if not _is_authed(request):
        return _login_redirect(request)
    data = _resolve_reader_content(id=article_id)
    if data is None:
        raise HTTPException(status_code=404, detail="not found")

    byline_parts = []
    if data["author"]:
        byline_parts.append(_esc(data["author"]))
    if data["source"]:
        byline_parts.append(_esc(data["source"]))
    if data["published_at"]:
        byline_parts.append(data["published_at"][:10])
    url = data["url"]
    byline_parts.append(f'<a class="source-link" href="{_esc(url)}" target="_blank" rel="noopener">{_esc(url[:60])}{"…" if len(url) > 60 else ""}</a>')
    byline = " &middot; ".join(byline_parts)

    if data["has_content"]:
        body_html = data["body_html"]
    else:
        body_html = f"""<div class="reader-empty">
          <h2>Content could not be extracted</h2>
          <p>Some sites block automated access. Try reading the original.</p>
          <p style="margin-top:16px;"><a href="{_esc(url)}" target="_blank" rel="noopener">Open original article &rarr;</a></p>
        </div>"""

    tags_block = ""
    if data["tags"]:
        tags_block = '<div style="margin-top:12px;display:flex;flex-wrap:wrap;gap:4px;">' + "".join(
            f'<span style="font-size:12px;font-weight:600;color:var(--navy);background:var(--seafoam);'
            f'border-radius:6px;padding:2px 8px;margin-right:4px;">{_esc(t)}</span>' for t in data["tags"]
        ) + "</div>"

    article_controls = """<button onclick="toggleReadLaterSingle()" id="rl-single-btn"
      style="font-size:13px;color:var(--accent);background:none;border:1px solid var(--line);
      border-radius:6px;padding:4px 10px;cursor:pointer;">&#128204; Read later</button>"""
    article_script = f"""<script>
var _rlUrl = {json.dumps(url)};
var _rlTitle = {json.dumps(data["title"])};
var _rlSource = {json.dumps(data["source"])};
var _rlPub = {json.dumps(data["published_at"])};
var _rlSaved = false;
async function toggleReadLaterSingle() {{
  var btn = document.getElementById('rl-single-btn');
  var params = new URLSearchParams({{
    url: _rlUrl, action: _rlSaved ? 'remove' : 'add',
    title: _rlTitle || '', source: _rlSource || '', published_at: _rlPub || ''
  }});
  btn.disabled = true;
  try {{
    var r = await fetch('/feed/read-later', {{method: 'POST',
      headers: {{'Content-Type': 'application/x-www-form-urlencoded'}}, body: params}});
    if (r.ok) {{
      _rlSaved = !_rlSaved;
      btn.innerHTML = _rlSaved ? '&#10003; Read later' : '&#128204; Read later';
    }}
  }} finally {{ btn.disabled = false; }}
}}
</script>"""

    return HTMLResponse(_READER_TMPL.format(
        title=_esc(data["title"]), heading=_esc(data["title"]), css=_READER_CSS,
        back_url="/read", back_label="Reader",
        orig_url=_esc(url), byline=byline,
        body=body_html,
        article_controls=article_controls,
        tags_block=tags_block,
        article_script=article_script,
    ))


# ---------------------------------------------------------------------------
# /read — the merged Reader shell (Phase 5): a three-pane admin tool that
# replaces both /library/archive and /library/feed. Left rail (quick views +
# feed sources), middle list pane (whichever view is active), right reader
# pane (article content, loaded via AJAX against /api/read-article — no full
# page navigation when you click an item). No compatibility redirects for the
# two retired routes, and no per-item Edit tags/Delete/Archive controls here
# — those stay exclusively in /admin/library's dedicated tools.
# ---------------------------------------------------------------------------

_READER_SHELL_CSS = """
<style>
.rr-shell{display:flex;height:calc(100vh - 180px);min-height:520px;width:100%;background:var(--bg);
  border:1px solid var(--line);border-radius:14px;overflow:hidden;font-family:var(--font-body);}
.rr-rail{flex:0 1 232px;min-width:150px;max-width:360px;background:var(--surface-2);
  border-right:1px solid var(--line);display:flex;flex-direction:column;padding:20px 14px;overflow-y:auto;}
.rr-rail-back{font-size:13px;color:var(--muted);text-decoration:none;margin-bottom:18px;display:inline-block;}
.rr-rail-back:hover{color:var(--ink);text-decoration:none;}
.rr-rail-title{font-family:var(--font-head);font-weight:700;font-size:20px;color:var(--navy);margin-bottom:16px;}
.rr-qv{display:flex;justify-content:space-between;align-items:center;padding:8px 10px;border-radius:8px;
  text-decoration:none;font-size:14px;color:var(--ink-soft);margin-bottom:2px;}
.rr-qv:hover{background:var(--navy-wash);text-decoration:none;}
.rr-qv-on{background:var(--navy-wash);color:var(--navy);font-weight:600;}
.rr-qv-count{font-size:12px;color:var(--muted);}
.rr-rope{height:6px;border-radius:3px;margin:18px 2px;
  background:repeating-linear-gradient(45deg,var(--navy-light) 0 4px,var(--seafoam) 4px 8px);opacity:.4;}
.rr-rail-label{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);
  margin:14px 6px 8px;}
.rr-cat{display:flex;justify-content:space-between;align-items:center;padding:8px 10px;border-radius:8px;
  cursor:pointer;font-size:14px;color:var(--ink-soft);}
.rr-cat:hover{background:var(--navy-wash);}
.rr-cat-on{background:var(--navy-wash);color:var(--navy);font-weight:600;}
.rr-cat-count{font-size:12px;color:var(--muted);}
.rr-cat-chev{display:inline-block;width:0;height:0;border-style:solid;border-width:4px 0 4px 6px;
  border-color:transparent transparent transparent var(--muted);margin-right:6px;transition:transform .15s;}
.rr-cat-chev.rr-open{transform:rotate(90deg);}
.rr-src-list{display:none;flex-direction:column;gap:2px;margin:2px 0 4px 22px;}
.rr-src-list.rr-open{display:flex;}
.rr-src{display:flex;justify-content:space-between;align-items:center;padding:5px 10px;border-radius:6px;
  cursor:pointer;font-size:13px;color:var(--ink-soft);}
.rr-src:hover{background:var(--seafoam-wash);}
.rr-src-on{background:var(--seafoam-wash);color:var(--seafoam-deep);font-weight:600;}
.rr-tagbar a{display:inline-block;font-size:12px;background:var(--surface);border:1px solid var(--line);
  border-radius:14px;padding:3px 9px;margin:0 4px 6px 0;color:var(--ink-soft);text-decoration:none;}
.rr-tagbar a:hover{background:var(--navy-wash);color:var(--navy);}
.rr-list-pane{flex:0 1 480px;min-width:300px;max-width:760px;background:var(--surface);
  border-right:1px solid var(--line);display:flex;flex-direction:column;min-height:0;}
.rr-list-header{padding:20px 22px 14px;border-bottom:1px solid var(--line);flex-shrink:0;}
.rr-list-title{font-family:var(--font-head);font-weight:600;font-size:19px;color:var(--navy);}
.rr-list-count{font-size:13px;color:var(--muted);margin-top:4px;}
.rr-alert{margin:14px 22px 0;padding:11px 13px;border-radius:10px;background:var(--coral-wash);
  border:1px solid var(--coral-light);display:flex;gap:10px;align-items:flex-start;font-size:13px;
  line-height:1.5;color:var(--coral-deep);}
/* Search, in the list pane's header directly above the rows it filters. This
   replaces .rr-search-form, which had been sitting in the left rail while
   carrying the list pane's own 22px gutter — the fingerprint that gave the
   misplacement away. No horizontal padding of its own now: .rr-list-header
   already supplies it, so the field lines up with the title above it. */
.rr-list-search{margin:12px 0 0;display:block;}
.rr-list-search input{width:100%;padding:8px 12px;border:1px solid var(--line);border-radius:9px;
  font-size:14px;background:var(--surface);font-family:inherit;}
.rr-list-rows{flex:1;overflow-y:auto;}
/* Distraction-free reading (corrected 2026-08 — see the Reader cleanliness
   investigation): the reference is Instapaper's own expand view, where BOTH
   the left nav rail and the article list disappear completely, leaving just
   the reading pane, centered, full width, with the top action bar still
   visible and a collapse-back affordance in its top-left corner. The
   original build only ever shrank .rr-list-pane to a 220px "sliver" while
   leaving .rr-rail fully visible — confirmed live as the actual bug, not the
   intended design. Both panes are now hidden outright (their own resize
   handles too), and .rr-reader-pane's flex:1 (declared above) fills the
   freed width on its own with no extra rule needed here. The existing
   #rr-reader-expand button in .rr-reader-header (sticky, so it's still
   visible with the rail/list gone) doubles as the collapse-back affordance—
   it already swaps between an expand and a collapse icon on toggle, so no
   separate button was needed to reach the reference's top-left arrow. */
.rr-shell.rr-focus-mode .rr-rail,
.rr-shell.rr-focus-mode .rr-list-pane,
.rr-shell.rr-focus-mode #rr-resize-rail,
.rr-shell.rr-focus-mode #rr-resize-list{display:none;}
/* flex-wrap lets the save-time tag form (.rr-row-tagform, flex:0 0 100%) drop
   onto its own line below the row instead of becoming a third column that
   squeezes .rr-row-main. It can't change the collapsed layout: .rr-row-main is
   min-width:0 so it shrinks rather than wrapping, and the form is display:none
   until opened, which removes it as a flex item entirely. */
.rr-row{display:flex;flex-wrap:wrap;gap:14px;padding:15px 22px;border-bottom:1px solid var(--line);}
.rr-row:hover{background:var(--surface-2);}
.rr-row-selected{background:var(--navy-wash);border-left:3px solid var(--navy);padding-left:19px;}
.rr-row-main{flex:1;min-width:0;cursor:pointer;}
.rr-row-meta{display:flex;align-items:baseline;gap:6px;margin-bottom:4px;font-size:12px;}
.rr-row-source{font-weight:600;letter-spacing:.02em;color:var(--navy-light);}
.rr-row-date{color:var(--muted);}
.rr-row-title{font-family:var(--font-head);font-weight:600;font-size:16px;color:var(--ink);line-height:1.3;margin-bottom:4px;}
.rr-row-excerpt{font-size:13.5px;color:var(--muted);line-height:1.55;display:-webkit-box;
  -webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;}
.rr-row-tags{display:flex;gap:6px;margin-top:8px;flex-wrap:wrap;}
.rr-row-tags span{background:var(--seafoam);color:var(--navy);font-size:11px;font-weight:600;
  padding:2px 8px;border-radius:6px;}
.rr-row-actions{display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0;}
.rr-row-btn{background:none;border:1px solid var(--line);border-radius:7px;font-size:12px;padding:4px 9px;
  cursor:pointer;color:var(--navy-light);white-space:nowrap;font-family:inherit;}
.rr-row-btn:hover{background:var(--navy-wash);}
.rr-row-btn.rr-row-btn-on{background:var(--seafoam-wash);border-color:var(--seafoam-deep);color:var(--seafoam-deep);}
.rr-paywall-badge{font-size:10.5px;background:#fef3c7;color:#92400e;padding:1px 6px;border-radius:9px;
  font-weight:600;margin-left:4px;}
.rr-reader-pane{flex:1 1 320px;min-width:240px;background:var(--surface);overflow-y:auto;position:relative;}
.rr-reader-header{position:sticky;top:0;background:var(--surface);display:flex;align-items:center;
  justify-content:space-between;flex-wrap:wrap;row-gap:8px;padding:13px 20px;border-bottom:1px solid var(--line);z-index:5;}
.rr-reader-header-left{display:flex;align-items:center;gap:6px;}
.rr-reader-close{cursor:pointer;font-size:20px;color:var(--muted);line-height:1;background:none;border:none;}
.rr-reader-expand{cursor:pointer;background:none;border:none;color:var(--muted);display:flex;
  align-items:center;padding:4px;border-radius:6px;}
.rr-reader-expand:hover{background:var(--surface-2);color:var(--navy);}
.rr-reader-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px;}
.rr-reader-actions button{cursor:pointer;font-size:12px;font-weight:600;background:none;border:1px solid var(--line);
  border-radius:6px;padding:4px 9px;color:var(--navy-light);font-family:inherit;}
.rr-reader-actions button.rr-row-btn-on{background:var(--seafoam-wash);border-color:var(--seafoam-deep);color:var(--seafoam-deep);}
/* Wider + labeled vs. the plain icon buttons around it (Tag, Expand) — see
   the markup comment in rrRenderArticle for why: icon-only in a row of
   icon-only buttons read as easy to miss during live testing. */
.rr-find-toggle{display:flex;align-items:center;gap:6px;padding:4px 12px;}
/* Same labeled-not-icon-only treatment as .rr-find-toggle, plus destructive
   coloring — matches the coral/#b91c1c convention every other permanent-
   delete button on this site already uses (see the admin delete buttons
   throughout webapp/app.py), not a new color invented for this one. */
.rr-delete-toggle{display:flex;align-items:center;gap:6px;padding:4px 12px;color:#b91c1c;border-color:#fca5a5;}
.rr-delete-toggle:hover{background:#fee2e2;}
.rr-find-bar{display:none;align-items:center;gap:6px;padding:8px 20px;border-bottom:1px solid var(--line);
  background:var(--surface-2);position:sticky;top:53px;z-index:4;}
.rr-find-bar.rr-find-open{display:flex;}
.rr-find-bar input{flex:1;min-width:0;padding:6px 10px;border:1px solid var(--line);border-radius:7px;
  font-size:13px;font-family:inherit;background:var(--surface);}
.rr-find-bar button{cursor:pointer;background:none;border:1px solid var(--line);border-radius:6px;
  padding:4px 9px;color:var(--navy-light);font-family:inherit;font-size:12px;flex-shrink:0;}
.rr-find-bar button:hover{background:var(--navy-wash);}
.rr-find-count{font-size:12px;color:var(--muted);white-space:nowrap;min-width:34px;text-align:center;flex-shrink:0;}
mark.rr-find-hit{background:var(--seafoam);color:var(--ink);border-radius:2px;padding:0 1px;}
mark.rr-find-hit.rr-find-current{background:var(--coral);color:#fff;}

/* Inline tag editor (Phase 5c). Collapsed by default — the reading view only
   ever shows the toolbar tag button until someone actually engages with it.
   Same sticky-under-the-header treatment as .rr-find-bar so the two behave
   identically when both are open. */
.rr-tag-panel{display:none;align-items:center;flex-wrap:wrap;gap:7px;padding:9px 20px;
  border-bottom:1px solid var(--line);background:var(--surface-2);position:sticky;top:53px;z-index:3;}
.rr-tag-panel.rr-tag-open{display:flex;}
.rr-tag-chip{display:inline-flex;align-items:center;gap:5px;background:var(--seafoam);color:var(--navy);
  font-size:11.5px;font-weight:600;padding:3px 5px 3px 9px;border-radius:11px;}
.rr-tag-chip button{cursor:pointer;background:none;border:none;color:var(--navy);opacity:.55;
  font-size:14px;line-height:1;padding:0 2px;font-family:inherit;}
.rr-tag-chip button:hover{opacity:1;}
/* The input needs a real typing width, not whatever's left over. A floor of
   220px (rather than the original 110px, which chips could squeeze it down to)
   means that once the chips on a line leave less than that, flex-wrap drops the
   input onto its own line instead — where flex-grow then gives it the panel's
   full width. min() keeps the floor from overflowing a container narrower than
   220px, which min-width alone would. Deliberately kept in the reader pane
   rather than moved to the list pane: that pane collapses to a sliver in
   distraction-free mode (which mobile portrait auto-enters), so a tag editor
   living there would be unreachable exactly while reading. */
.rr-tag-input{flex:1 1 220px;min-width:min(220px,100%);padding:5px 9px;border:1px solid var(--line);border-radius:7px;
  font-size:12.5px;font-family:inherit;background:var(--surface);}
.rr-tag-status{font-size:11.5px;color:var(--muted);white-space:nowrap;}
.rr-tag-empty{font-size:12px;color:var(--muted);}
/* Count badge on the toolbar tag button — the collapsed-state summary, so the
   number of tags is legible without opening the panel. */
.rr-tag-count{display:inline-block;background:var(--seafoam-deep);color:#fff;font-size:10px;
  font-weight:700;border-radius:8px;padding:0 5px;margin-left:5px;line-height:15px;}
/* Save-time tag entry on a Feed row — expands in place under the row's own
   actions, replacing the old window.prompt() dialog. */
.rr-row-tagform{display:none;flex:0 0 100%;gap:6px;align-items:center;flex-wrap:wrap;margin-top:-4px;}
.rr-row-tagform.rr-tag-open{display:flex;}
.rr-row-tagform input{flex:1 1 140px;min-width:120px;padding:5px 9px;border:1px solid var(--line);
  border-radius:7px;font-size:12.5px;font-family:inherit;background:var(--surface);}
.rr-row-tagform button{cursor:pointer;font-size:11.5px;font-weight:600;background:none;
  border:1px solid var(--line);border-radius:6px;padding:4px 10px;color:var(--navy-light);font-family:inherit;}
.rr-row-tagform button.rr-tag-go{background:var(--seafoam-wash);border-color:var(--seafoam-deep);color:var(--seafoam-deep);}
.rr-tag-panel button.rr-tag-go{cursor:pointer;font-size:11.5px;font-weight:600;background:var(--seafoam-wash);
  border:1px solid var(--seafoam-deep);border-radius:6px;padding:4px 10px;color:var(--seafoam-deep);font-family:inherit;}
.rr-tag-panel button.rr-tag-go[hidden],.rr-reader-actions button[hidden]{display:none;}
/* Scales with the reader pane's own available width instead of staying
   pinned to a fixed pixel value regardless of container size (the prior
   flat 700px left large fixed empty margins once the pane itself grew
   wider than that — e.g. distraction-free mode, or a wide viewport with
   the list pane at its own max-width). 92% keeps a reader-chosen breathing
   margin at any pane width; 880px is still an upper cap so an extreme-width
   pane (a very wide monitor, or the list pane collapsed to its sliver)
   doesn't stretch line length past a readable measure — not a return to a
   fixed number, just a ceiling on top of the relative one. */
.rr-reader-body{max-width:min(92%,880px);margin:0 auto;padding:44px 32px 100px;}
.rr-reader-category{font-size:12px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;
  color:var(--seafoam-deep);margin-bottom:12px;}
/* Title uses Outfit, matching BRAND.md's "Page title (H1)" row (30px/600/
   -0.02em) and the standalone /read/{id} reader's own .reader-meta h1—
   this used to fall through to 'Source Serif 4',Georgia,serif with no
   letter-spacing, a leftover that never got updated when the two readers'
   heading treatments were established. */
.rr-reader-title{font-family:var(--font-head);font-weight:600;font-size:30px;line-height:1.18;
  letter-spacing:-.02em;color:var(--ink);margin-bottom:16px;}
.rr-reader-byline{font-size:13px;color:var(--muted);padding-bottom:22px;border-bottom:1px solid var(--line);
  margin-bottom:26px;font-family:var(--font-body);}
/* Body font, corrected 2026-09, twice: this rendered in 'Source Serif 4'
   first — a BRAND.md-documented exception at the time ("Reader body |
   Source Serif 4") — confirmed wrong by direct live-site review. A first
   fix moved it to var(--font-head) (Outfit) alongside the title; checked
   against the site's actual published long-form content (an Original
   Content article's .oc-body p, the same template NetSuite MCP/Growth
   Engine Ratio/Sail Don't Row render through) and found that body copy is
   DM Sans there, Outfit only for the H1 — so Outfit-for-body would have
   made this reader the one place on the whole site with body copy in a
   headings font, not a return to an existing pattern. Settled on
   var(--font-body) (DM Sans) instead — this now matches ordinary sitewide
   typography exactly (Outfit heading, DM Sans body), no reader-specific
   exception left to document at all. The standalone /read/{id}
   single-article view (a different template, _READER_CSS/.reader-body) was
   a separate, deliberately out-of-scope holdout for this fix — it moved to
   DM Sans too in a follow-up pass once Brian confirmed the standing rule is
   Outfit/DM Sans only, ever, for content typography (never a third font,
   Caveat/Permanent Marker's decorative sticker/wordmark use aside). */
.rr-reader-body-text{font-family:var(--font-body);font-size:var(--rr-fs,17px);line-height:1.75;color:var(--ink-soft);}
.rr-reader-body-text p{margin-bottom:1.3em;}
.rr-reader-empty{display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;
  color:var(--muted);font-size:14px;padding:40px;text-align:center;}
.rr-resize{width:6px;flex-shrink:0;margin:0 -3px;cursor:col-resize;background:transparent;z-index:6;}
.rr-resize:hover{background:var(--seafoam);}
/* Stacked mobile layout: portrait at typical phone/tablet widths, OR any
   orientation once genuinely too narrow for 3 real panes even at their own
   CSS min-widths (150+300+240=690px floor). A pure width cutoff can't tell
   phone-portrait (truly cramped) from phone-landscape (has real horizontal
   room, just short) at the same width — the mirror image of the homepage's
   own 1024px note (webapp/app.py's home-grid breakpoint), which pushes
   *its* threshold up so landscape phones stay on the mobile order; here we
   want the opposite outcome (landscape phones get the real desktop layout),
   so this stays orientation-aware instead of reusing that number. Common
   landscape-phone widths run ~667-932px; only the smallest (iPhone
   SE-class, ~667px) falls under the 700px floor and stays stacked in
   landscape too — correct, since 667 < 690 means it can't fit 3 panes at
   their minimums regardless of rotation. */
@media (max-width:900px) and (orientation:portrait), (max-width:699px){
  .rr-shell{display:block;height:auto;}
  .rr-rail,.rr-list-pane{max-width:none;flex:none;border-right:none;border-bottom:1px solid var(--line);}
  .rr-resize{display:none;}
  /* Distraction-free reading is forced here, not just offered — see
     rrMobileNoRoom()/rrRenderArticle. The base .rr-shell.rr-focus-mode rule
     above already hides both .rr-rail and .rr-list-pane on every viewport
     now, so nothing mobile-specific is needed here any more. */
}
</style>
"""


def _reader_fmt_date(iso: str) -> str:
    if not iso:
        return ""
    try:
        dt = datetime.fromisoformat(iso.replace("Z", "+00:00"))
        return dt.strftime("%-d %b %Y")
    except Exception:
        return iso[:10]


@app.get("/read", response_class=HTMLResponse)
def reader_shell(request: Request, view: str = "feed", q: str = ""):
    if not _is_authed(request):
        return _login_redirect(request)
    if view not in ("feed", "saved", "readlater"):
        view = "feed"

    from linklib import authcheck
    from linklib.feed import get_feed_items, PAYWALLED_DOMAINS

    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        saved_total = lib.count()
        rl_urls = lib.read_later_urls(user_id) if user_id is not None else set()

        auth_status = authcheck.get_auth_status(lib)
        stale = authcheck.stale_domains(auth_status)

        try:
            feed_items, _feed_cats_unused = get_feed_items(OPML_PATH, category="", max_total=120)
        except Exception:
            feed_items = []

        # One all_tags() read serves both the Archive view's filter bar and the
        # <datalist> behind every tag input on the page (save-time and the
        # reader's inline editor). The vocabulary is needed in every view, not
        # just Archive — a Feed item can be tagged at save time — so this is read
        # unconditionally rather than inside the `view == "saved"` branch.
        all_tags_ranked = lib.all_tags()
        tag_vocab = [t for t, _ in all_tags_ranked]
        saved_rows, saved_tags = [], []
        rl_rows = []
        if view == "saved":
            saved_rows = lib.search(q, limit=200)
            saved_tags = all_tags_ranked[:25]
        elif view == "readlater":
            rl_rows = lib.list_read_later(user_id) if user_id is not None else []
    finally:
        lib.close()

    # Categories/sources tree, built off the same feed_items payload used for
    # the Feed view's count and rows — client-side filtering (JS) over this
    # one fetch, same approach as the old Feed page's source checkboxes.
    cat_sources: dict[str, dict[str, int]] = {}
    cat_order: list[str] = []
    for item in feed_items:
        c = item.get("category") or "Other"
        if c not in cat_sources:
            cat_sources[c] = {}
            cat_order.append(c)
        s = item.get("source") or ""
        cat_sources[c][s] = cat_sources[c].get(s, 0) + 1

    # -- left rail ----------------------------------------------------------
    def _qv(v, label, count):
        cls = "rr-qv rr-qv-on" if view == v else "rr-qv"
        return f'<a href="/read?view={v}" class="{cls}"><span>{_esc(label)}</span><span class="rr-qv-count">{count:,}</span></a>'

    quick_views_html = (
        _qv("feed", "Feed", len(feed_items))
        + _qv("saved", "Archive", saved_total)
        + _qv("readlater", "Read Later", len(rl_urls))
    )

    # Search lives in the list pane's header, directly above the rows it
    # filters — not in the left rail. See _list_search_html below; the rail
    # keeps only navigation (quick views) and per-view filter vocabularies
    # (Feed's Sources tree, the Archive view's tag bar).
    sources_html = ""
    if view == "feed":
        cat_rows = ""
        for c in cat_order:
            srcs = cat_sources[c]
            total_c = sum(srcs.values())
            src_rows = "".join(
                f'<div class="rr-src" data-cat="{_esc(c)}" data-src="{_esc(s)}" onclick="rrSelectSource(this)">'
                f'<span>{_esc(s)}</span><span class="rr-cat-count">{n}</span></div>'
                for s, n in sorted(srcs.items())
            )
            cat_rows += (
                f'<div>'
                f'<div class="rr-cat" data-cat="{_esc(c)}">'
                f'<div style="display:flex;align-items:center;flex:1;min-width:0;" onclick="rrSelectCategory(this)">'
                f'<span class="rr-cat-chev" onclick="event.stopPropagation();rrToggleCat(this)"></span>'
                f'<span>{_esc(c)}</span></div>'
                f'<span class="rr-cat-count">{total_c}</span></div>'
                f'<div class="rr-src-list">{src_rows}</div>'
                f'</div>'
            )
        if cat_rows:
            cat_rows = f'<div class="rr-rail-label">Sources</div>{cat_rows}'
        sources_html = cat_rows
    elif view == "saved":
        # The tag bar stays in the rail: it's a filter vocabulary, the Archive
        # view's counterpart to Feed's Sources tree, so it's labelled to match
        # rather than keeping the old "Search" heading the moved form left behind.
        tagbar = "".join(f'<a href="/read?view=saved&q={_esc(t)}">{_esc(t)} ({c})</a>' for t, c in saved_tags)
        if tagbar:
            sources_html = f'<div class="rr-rail-label">Tags</div><div class="rr-tagbar">{tagbar}</div>'

    rail_html = f"""<div class="rr-rail" id="rr-rail">
  <a class="rr-rail-back" href="/tools">&larr; Toolbox</a>
  <div class="rr-rail-title">Reader</div>
  <div>{quick_views_html}</div>
  <div class="rr-rope"></div>
  {sources_html}
</div>"""

    # -- list pane ------------------------------------------------------------
    def _feed_row(item):
        paywalled = any(dom in item.get("url", "") for dom in PAYWALLED_DOMAINS)
        url = item.get("url", "")
        source = item.get("source", "")
        category = item.get("category") or "Other"
        date = _reader_fmt_date(item.get("published_at") or "")
        is_rl = url in rl_urls
        # Paywalled items still open in the in-app reader pane, same as any other
        # row — the pane's own "Original ->" toolbar link (rrRenderArticle) is the
        # one intended way to jump to source. They used to be wrapped in a real
        # <a target="_blank"> instead, which hijacked the click into an external
        # tab before the reader pane (and its "Original ->" link) ever got a
        # chance to render — a genuine bug, not a deliberate "no in-app reader for
        # paywalled sources" design (extraction still runs and gracefully falls
        # back to "Content could not be extracted, Open original ->" when a
        # paywall blocks it, same as any other fetch failure).
        badge = '<span class="rr-paywall-badge">&#128274; Paywalled</span>' if paywalled else ""
        main_cls = "rr-row-main"
        main_onclick = ' onclick="rrOpen(this)"'
        main_open = ""
        main_close = ""
        actions = ""
        if not paywalled:
            save_btn = '<button class="rr-row-btn" onclick="rrSaveItem(this)">+ Save</button>'
            rl_lbl = "&#10003; Read later" if is_rl else "&#128204; Read later"
            rl_cls = "rr-row-btn rr-row-btn-on" if is_rl else "rr-row-btn"
            rl_btn = f'<button class="{rl_cls}" onclick="rrToggleReadLater(this)">{rl_lbl}</button>'
            # Save-time tags (Phase 5c): collapsed until "+ Save" is clicked, then
            # expands in place. Tags stay optional — the Save button commits with an
            # empty input exactly as the old one-click save did.
            tagform = (
                '<div class="rr-row-tagform">'
                '<input type="text" list="rr-tag-vocab" placeholder="Tags (comma-separated, optional)" '
                'onkeydown="rrRowTagKeydown(event,this)">'
                '<button class="rr-tag-go" onclick="rrRowSaveGo(this)">Save</button>'
                '<button onclick="rrRowSaveCancel(this)">Cancel</button>'
                '<span class="rr-tag-status"></span>'
                "</div>"
            )
            actions = f'<div class="rr-row-actions">{save_btn}{rl_btn}</div>{tagform}'
        return (
            f'<div class="rr-row" data-category="{_esc(category)}" data-source="{_esc(source)}" data-rl="{1 if is_rl else 0}">'
            f'<div class="{main_cls}"{main_onclick} data-url="{_esc(url)}" data-title="{_esc(item.get("title", ""))}" '
            f'data-source-name="{_esc(source)}" data-pub="{_esc(item.get("published_at") or "")}" '
            f'data-summary="{_esc((item.get("summary") or "")[:400])}">'
            f'{main_open}'
            f'<div class="rr-row-meta"><span class="rr-row-source">{_esc(source)}</span>'
            f'<span style="color:var(--line-strong);">&middot;</span><span class="rr-row-date">{date}</span>{badge}</div>'
            f'<div class="rr-row-title">{_esc(item.get("title", ""))}</div>'
            f'<div class="rr-row-excerpt">{_esc(item.get("summary") or "")}</div>'
            f'{main_close}</div>{actions}</div>'
        )

    def _saved_row(r):
        tag_spans = "".join(f'<span>{_esc(t)}</span>' for t in r.get("tags", []))
        date = _esc((r.get("saved_at") or "")[:10])
        return (
            f'<div class="rr-row" data-id="{r["id"]}">'
            f'<div class="rr-row-main" onclick="rrOpen(this)" data-id="{r["id"]}" data-url="{_esc(r["url"])}">'
            f'<div class="rr-row-meta"><span class="rr-row-source">{_esc(r.get("source", ""))}</span>'
            f'<span style="color:var(--line-strong);">&middot;</span><span class="rr-row-date">{date}</span></div>'
            f'<div class="rr-row-title">{_esc(r["title"])}</div>'
            f'<div class="rr-row-excerpt">{_esc(r.get("summary", ""))}</div>'
            f'<div class="rr-row-tags">{tag_spans}</div>'
            f'</div></div>'
        )

    def _rl_row(r):
        url = r["url"]
        date = _reader_fmt_date(r.get("published_at") or "")
        return (
            f'<div class="rr-row" data-url="{_esc(url)}">'
            f'<div class="rr-row-main" onclick="rrOpen(this)" data-url="{_esc(url)}" '
            f'data-title="{_esc(r.get("title", ""))}" data-source-name="{_esc(r.get("source", ""))}" '
            f'data-pub="{_esc(r.get("published_at") or "")}" data-summary="{_esc((r.get("summary") or "")[:400])}">'
            f'<div class="rr-row-meta"><span class="rr-row-source">{_esc(r.get("source", ""))}</span>'
            f'<span style="color:var(--line-strong);">&middot;</span><span class="rr-row-date">{date}</span></div>'
            f'<div class="rr-row-title">{_esc(r.get("title") or "(no title)")}</div>'
            f'<div class="rr-row-excerpt">{_esc(r.get("summary") or "")}</div>'
            f'</div>'
            f'<div class="rr-row-actions">'
            f'<button class="rr-row-btn" onclick="rrRemoveReadLater(this)" data-url="{_esc(url)}">Remove</button>'
            f'</div></div>'
        )

    if view == "saved":
        rows_html = "".join(_saved_row(r) for r in saved_rows) or '<p style="padding:24px;color:var(--muted);">No matches.</p>'
        list_title = "Archive"
        list_count_label = f"{len(saved_rows):,} of {saved_total:,} shown" if q else f"{saved_total:,} archived"
    elif view == "readlater":
        rows_html = "".join(_rl_row(r) for r in rl_rows) or '<p style="padding:24px;color:var(--muted);">No items saved to Read Later yet.</p>'
        list_title = "Read Later"
        list_count_label = f"{len(rl_rows):,} items"
    else:
        rows_html = "".join(_feed_row(i) for i in feed_items) or '<p style="padding:24px;color:var(--muted);">No items loaded—feeds may be warming up. Try refreshing in a moment.</p>'
        list_title = "Feed"
        list_count_label = f"{len(feed_items):,} items"

    alert_html = ""
    if stale:
        dom = stale[0]
        extra = f" and {len(stale) - 1} more" if len(stale) > 1 else ""
        alert_html = (
            '<div class="rr-alert">'
            '<span style="flex-shrink:0;width:18px;height:18px;border-radius:50%;background:var(--coral);'
            'color:#fff;font-size:12px;font-weight:600;display:flex;align-items:center;justify-content:center;">!</span>'
            f'<span style="flex:1;">Subscriber access looks stale for <strong>{_esc(dom)}</strong>{extra}&mdash;'
            f'the cookie may have expired. Grab a fresh cookie from {_esc(dom)} and update it in Railway, then '
            f'<a href="#" onclick="rrRecheckAuth(event)">re-check subscriber access</a>.</span>'
            '</div>'
        )

    # Search sits in the list pane's own header, directly above the rows it
    # filters. Each view keeps its existing mechanism — Feed filters client-side
    # through rrApplyFilter (composing with the active category/source), Archive
    # does a plain GET reload — only the placement is shared. Read Later has no
    # search today and renders none, same as before.
    if view == "feed":
        list_search_html = (
            '<div class="rr-list-search">'
            '<input type="search" id="rr-feed-search" placeholder="Search this feed&hellip;" '
            'oninput="rrApplyFilter()" autocomplete="off">'
            "</div>"
        )
    elif view == "saved":
        list_search_html = (
            '<form class="rr-list-search" method="get" action="/read">'
            '<input type="hidden" name="view" value="saved">'
            f'<input type="search" name="q" value="{_esc(q)}" '
            'placeholder="Search titles, summaries, tags&hellip;">'
            "</form>"
        )
    else:
        list_search_html = ""

    list_pane_html = f"""<div class="rr-list-pane" id="rr-list-pane">
  <div class="rr-list-header">
    <div class="rr-list-title" id="rr-list-title">{_esc(list_title)}</div>
    <div class="rr-list-count" id="rr-list-count">{_esc(list_count_label)}</div>
    {list_search_html}
  </div>
  <div id="rr-alert-wrap">{alert_html}</div>
  <div class="rr-list-rows" id="rr-list-rows">{rows_html}</div>
</div>"""

    reader_pane_html = """<div class="rr-reader-pane" id="rr-reader">
  <div class="rr-reader-empty">
    <div style="font-size:14px;">Select an article to start reading</div>
  </div>
</div>"""

    # Shared autocomplete vocabulary for every tag input on the page (save-time
    # row form and the reader's inline editor). Native <datalist>, same pattern
    # the overhead-category admin inputs already use — no JS autocomplete
    # widget, and it degrades to a plain text input where unsupported. This is
    # the same vocabulary /admin/reader/tag-management curates, read live from all_tags().
    tag_vocab_html = (
        '<datalist id="rr-tag-vocab">'
        + "".join(f'<option value="{_esc(t)}"></option>' for t in tag_vocab)
        + "</datalist>"
    )

    body = (
        _READER_SHELL_CSS
        # No dedicated Source Serif 4 <link> here any more (2026-09) — this
        # merged reader's title/body moved to Outfit/DM Sans respectively
        # (ordinary sitewide typography), both already loaded via _page()'s
        # own font <link>; nothing on this page references the serif any
        # more, so importing it would just be a wasted request.
        + tag_vocab_html
        + f"""<div class="rr-shell">
  {rail_html}
  <div class="rr-resize" id="rr-resize-rail"></div>
  {list_pane_html}
  <div class="rr-resize" id="rr-resize-list"></div>
  {reader_pane_html}
</div>
<script>
function rrToggleCat(el) {{
  el.classList.toggle('rr-open');
  el.closest('.rr-cat').nextElementSibling.classList.toggle('rr-open');
}}
// Category/source selection are sticky filter state, not one-shot args—
// rrApplyFilter() re-reads them (plus the search box) on every call, so a
// search-input keystroke can re-run the same combination without needing
// to know which category/source is currently active.
var rrFeedCat = null, rrFeedSrc = null;
function rrSelectCategory(el) {{
  var cat = el.closest('.rr-cat').dataset.cat;
  document.querySelectorAll('.rr-cat').forEach(function(c) {{ c.classList.remove('rr-cat-on'); }});
  document.querySelectorAll('.rr-src').forEach(function(s) {{ s.classList.remove('rr-src-on'); }});
  el.closest('.rr-cat').classList.add('rr-cat-on');
  rrFeedCat = cat; rrFeedSrc = null;
  rrApplyFilter();
}}
function rrSelectSource(el) {{
  var cat = el.dataset.cat, src = el.dataset.src;
  document.querySelectorAll('.rr-cat').forEach(function(c) {{ c.classList.remove('rr-cat-on'); }});
  document.querySelectorAll('.rr-src').forEach(function(s) {{ s.classList.remove('rr-src-on'); }});
  el.classList.add('rr-src-on');
  rrFeedCat = cat; rrFeedSrc = src;
  rrApplyFilter();
}}
function rrApplyFilter() {{
  var cat = rrFeedCat, src = rrFeedSrc;
  var searchEl = document.getElementById('rr-feed-search');
  var q = searchEl ? searchEl.value.trim().toLowerCase() : '';
  var rows = document.querySelectorAll('#rr-list-rows > .rr-row');
  var shown = 0;
  rows.forEach(function(r) {{
    var okFilter = (!cat || r.dataset.category === cat) && (!src || r.dataset.source === src);
    var okSearch = !q || r.textContent.toLowerCase().indexOf(q) !== -1;
    var ok = okFilter && okSearch;
    r.style.display = ok ? '' : 'none';
    if (ok) shown++;
  }});
  document.getElementById('rr-list-title').textContent = src ? (cat + ' \\u00b7 ' + src) : (cat || 'Feed');
  document.getElementById('rr-list-count').textContent = shown + ' items';
}}
function rrOpen(el) {{
  document.querySelectorAll('.rr-row').forEach(function(r) {{ r.classList.remove('rr-row-selected'); }});
  el.closest('.rr-row').classList.add('rr-row-selected');
  var id = el.dataset.id, url = el.dataset.url;
  rrLoadArticle(id, url, {{
    title: el.dataset.title, source: el.dataset.sourceName,
    pub: el.dataset.pub, summary: el.dataset.summary
  }});
}}
var rrCurrent = null;
var rrFsStep = 0;
var rrFsSizes = [17, 15, 20];
// Distraction-free reading (matches Instapaper's own expand/collapse toggle).
// State lives here, not per-article, so it survives a scroll-driven "time
// left" update without re-deriving anything from `view`/`d` — the whole
// point is it behaves identically whether the open article came from Feed
// or Archive.
var rrFocusMode = false;
// RR_ICON_EXPAND's arrows point OUTWARD, toward the top-left/bottom-right
// (NW/SE) corners; RR_ICON_COLLAPSE's point INWARD, tails anchored at the
// same two corners. (Fixed 2026-09: these originally sat on the NE/SW
// diagonal — Feather's stock "maximize-2"/"minimize-2" — which pointed the
// wrong way live; mirrored horizontally onto NW/SE per direct confirmation,
// keeping each icon's outward/inward direction otherwise unchanged.)
// RR_ICON_EXPAND shows by default (not yet in focus mode) — clicking it
// expands; RR_ICON_COLLAPSE shows once in focus mode — clicking it restores
// the rail/list. See rrRenderArticle/rrSetFocusMode below for that mapping.
var RR_ICON_EXPAND = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 3 3 3 3 9"></polyline><polyline points="15 21 21 21 21 15"></polyline><line x1="3" y1="3" x2="10" y2="10"></line><line x1="21" y1="21" x2="14" y2="14"></line></svg>';
var RR_ICON_COLLAPSE = '<svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 14 14 14 14 20"></polyline><polyline points="4 10 10 10 10 4"></polyline><line x1="10" y1="10" x2="3" y2="3"></line><line x1="21" y1="21" x2="14" y2="14"></line></svg>';
var RR_ICON_SEARCH = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>';
// Tag glyph for the reader toolbar — the collapsed state of the inline tag
// editor, matching Instapaper's own toolbar tag affordance.
var RR_ICON_TAG = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.6 13.4L12 22l-9-9V3h10l7.6 7.6a2 2 0 0 1 0 2.8z"></path><circle cx="7.5" cy="7.5" r="1.3"></circle></svg>';
// Trash glyph for "Remove from library" — one-off cleanup of a single saved
// article straight from the reader pane's own toolbar, admin-only same as
// the rest of the Reader (see reader_shell's _is_authed gate — there's no
// separate admin check on this button since anyone in the Reader already is
// an admin).
var RR_ICON_TRASH = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"></path><path d="M10 11v6"></path><path d="M14 11v6"></path><path d="M9 6V4a1 1 0 0 1 1-1h4a1 1 0 0 1 1 1v2"></path></svg>';
// Refresh glyph for the Read Later per-item "Refresh" action (2026-08 Reader
// cleanliness pass) — a manual re-fetch, not automatic staleness detection.
// Read-Later-only for now: an Archive article's own content is managed by
// the admin's dedicated backfill/refetch tools, not this button (see
// rrRenderArticle's is_read_later gate).
var RR_ICON_REFRESH = '<svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"></polyline><polyline points="1 20 1 14 7 14"></polyline><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"></path></svg>';
// In-article find (a separate, article-scoped search — not the list search).
var rrFindMatches = [];
var rrFindIndex = -1;
var rrFindBodyHtml = '';
async function rrLoadArticle(id, url, fallback) {{
  var pane = document.getElementById('rr-reader');
  pane.innerHTML = '<div class="rr-reader-empty"><div>Loading&hellip;</div></div>';
  try {{
    var qs = id ? ('id=' + encodeURIComponent(id)) : ('url=' + encodeURIComponent(url));
    var r = await fetch('/api/read-article?' + qs);
    if (!r.ok) throw new Error('fetch failed');
    var d = await r.json();
    rrCurrent = d;
    rrRenderArticle(d);
  }} catch (e) {{
    pane.innerHTML = '<div class="rr-reader-empty"><div>Could not load this article.</div></div>';
  }}
}}
function rrEsc(s) {{
  return (s || '').toString().replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}}
function rrRenderArticle(d) {{
  var pane = document.getElementById('rr-reader');
  var isSaved = !!d.id;
  var isRl = document.querySelector('.rr-row-selected .rr-row-btn-on') !== null;
  var byline = [d.source, (d.published_at || '').slice(0, 10)].filter(Boolean).join(' &middot; ');
  if (d.reading_minutes) byline += (byline ? ' &middot; ' : '') + d.reading_minutes + ' min read';
  if (!Array.isArray(d.tags)) d.tags = [];
  // Both buttons are always rendered and toggled with `hidden`, so saving from
  // inside the reader can swap them without a full re-render (which would reset
  // find state and scroll a part-read article back to the top).
  var saveBtn = '<button id="rr-reader-save" onclick="rrSaveCurrent()"' + (isSaved ? ' hidden' : '') + '>+ Save</button>';
  var tagBtn = '<button id="rr-tag-btn" onclick="rrToggleTagPanel()" title="Tags"' +
    (isSaved ? '' : ' hidden') + '>' + RR_ICON_TAG +
    (d.tags.length ? '<span class="rr-tag-count">' + d.tags.length + '</span>' : '') + '</button>';
  var rlBtn = '<button id="rr-reader-rl" class="' + (isRl ? 'rr-row-btn-on' : '') + '" onclick="rrToggleReadLaterCurrent()">' +
    (isRl ? '&#10003; Read later' : '&#128204; Read later') + '</button>';
  var body = d.has_content ? d.body_html :
    '<p style="color:var(--muted);">Content could not be extracted. <a href="' + rrEsc(d.url) + '" target="_blank" rel="noopener">Open original &rarr;</a></p>';
  // The live page couldn't be fetched directly, so this came from a Wayback
  // Machine snapshot instead — surfaced visibly (not just logged) since an
  // archived copy can be stale or differ from what the live page shows
  // today. See linklib.wayback's module docstring for the fallback itself.
  var waybackNote = (d.has_content && d.content_via === 'wayback')
    ? '<div style="background:var(--coral-wash);border:1px solid var(--coral);border-radius:8px;' +
      'padding:8px 12px;margin-bottom:16px;font-size:12.5px;color:var(--navy);">' +
      'The live page couldn&rsquo;t be reached, so this is a Wayback Machine archived copy&mdash;it may be stale or differ from the current page.</div>'
    : '';
  rrFindMatches = []; rrFindIndex = -1; rrFindBodyHtml = '';
  pane.innerHTML =
    '<div class="rr-reader-header">' +
      '<div class="rr-reader-header-left">' +
        '<button class="rr-reader-close" onclick="rrCloseReader()">&times;</button>' +
        '<button class="rr-reader-expand" id="rr-reader-expand" onclick="rrToggleFocusMode()" title="' +
          (rrFocusMode ? 'Exit distraction-free reading' : 'Distraction-free reading') + '">' +
          (rrFocusMode ? RR_ICON_COLLAPSE : RR_ICON_EXPAND) +
        '</button>' +
      '</div>' +
      '<div class="rr-reader-actions">' + saveBtn + tagBtn + rlBtn +
        '<button onclick="rrCycleFontSize()">Aa</button>' +
        // Icon-only among a row of icon-only buttons (Tag, Expand) reads as
        // easy to miss — a real design gap flagged from live testing, not a
        // bug. A visible "Find" label makes it read as its own affordance
        // rather than blending into the row, same treatment the "Aa" and
        // "+ Save" buttons already get (text, not just a glyph).
        '<button onclick="rrToggleFind()" title="Find in article" class="rr-find-toggle">' +
          RR_ICON_SEARCH + '<span>Find</span></button>' +
        // Read Later's per-item "Refresh" action (2026-08 Reader cleanliness
        // pass) — only shown for a Read Later item (never an Archive
        // article's own content, per d.is_read_later's own gate — see
        // _resolve_reader_content). Same toolbar area as Find/Remove/Original,
        // per the build brief.
        (d.is_read_later ? '<button id="rr-refresh-btn" onclick="rrRefreshReadLater()" ' +
          'title="Re-fetch this article" class="rr-find-toggle">' + RR_ICON_REFRESH +
          '<span>Refresh</span></button>' : '') +
        // Only for a saved article — there's nothing to remove from the
        // library for a Feed/Read Later item that was never saved.
        (isSaved ? '<button id="rr-delete-btn" onclick="rrDeleteCurrent()" title="Remove from library" ' +
          'class="rr-delete-toggle">' + RR_ICON_TRASH + '<span>Remove</span></button>' : '') +
        '<a href="' + rrEsc(d.url) + '" target="_blank" rel="noopener" style="font-size:12px;">Original &rarr;</a>' +
      '</div>' +
    '</div>' +
    // Collapsed by default — nothing but the toolbar icon shows until opened.
    '<div class="rr-tag-panel" id="rr-tag-panel">' +
      '<span id="rr-tag-chips"></span>' +
      '<input class="rr-tag-input" id="rr-tag-input" list="rr-tag-vocab" ' +
        'placeholder="' + (isSaved ? 'Add a tag&hellip;' : 'Tags (comma-separated, optional)') + '" ' +
        'onkeydown="rrTagKeydown(event)">' +
      '<button class="rr-tag-go" id="rr-tag-savebtn" onclick="rrSaveCurrentGo()"' +
        (isSaved ? ' hidden' : '') + '>Save article</button>' +
      '<span class="rr-tag-status" id="rr-tag-status"></span>' +
    '</div>' +
    '<div class="rr-find-bar" id="rr-find-bar">' +
      '<input type="text" id="rr-find-input" placeholder="Find in article&hellip;" ' +
        'oninput="rrFindRun()" onkeydown="rrFindKeydown(event)">' +
      '<span class="rr-find-count" id="rr-find-count"></span>' +
      '<button onclick="rrFindPrev()" title="Previous match">&uarr;</button>' +
      '<button onclick="rrFindNext()" title="Next match">&darr;</button>' +
      '<button onclick="rrToggleFind()" title="Close">&times;</button>' +
    '</div>' +
    '<div class="rr-reader-body">' +
      '<div class="rr-reader-category">' + rrEsc(d.category) + '</div>' +
      '<div class="rr-reader-title">' + rrEsc(d.title) + '</div>' +
      '<div class="rr-reader-byline">' + byline + '</div>' +
      waybackNote +
      '<div class="rr-reader-body-text" id="rr-reader-body-text" style="--rr-fs:' + rrFsSizes[rrFsStep] + 'px;">' + body + '</div>' +
    '</div>';
  // Mobile fix: opening an article used to leave #rr-reader wherever it
  // already sat in the stacked mobile layout — often 600px+ below the
  // fold, well past the tapped row, with nothing scrolling the page to it.
  // The click/tap itself was never broken (rrOpen always fired correctly);
  // the update just happened off-screen, which reads as "does nothing."
  // On a real "no room for 3 panes" viewport, default straight into
  // distraction-free reading (hides the rail + list entirely, see the
  // .rr-focus-mode CSS) rather than just scrolling past a still-full
  // mobile-stacked list; on any other viewport this scrollIntoView is a
  // no-op in practice since .rr-shell is already height-constrained to
  // the viewport with its own internal scroll.
  if (rrMobileNoRoom() && !rrFocusMode) {{
    rrSetFocusMode(true);
  }}
  pane.scrollIntoView({{behavior: 'instant', block: 'start'}});
}}
function rrMobileNoRoom() {{
  return window.matchMedia('(max-width:900px) and (orientation:portrait), (max-width:699px)').matches;
}}
function rrCloseReader() {{
  document.querySelectorAll('.rr-row').forEach(function(r) {{ r.classList.remove('rr-row-selected'); }});
  document.getElementById('rr-reader').innerHTML =
    '<div class="rr-reader-empty"><div style="font-size:14px;">Select an article to start reading</div></div>';
  rrCurrent = null;
  rrFindMatches = []; rrFindIndex = -1; rrFindBodyHtml = '';
  if (rrFocusMode) rrSetFocusMode(false);
}}
function rrCycleFontSize() {{
  rrFsStep = (rrFsStep + 1) % rrFsSizes.length;
  var el = document.getElementById('rr-reader-body-text');
  if (el) el.style.setProperty('--rr-fs', rrFsSizes[rrFsStep] + 'px');
}}
function rrSetFocusMode(on) {{
  rrFocusMode = on;
  var shell = document.querySelector('.rr-shell');
  if (shell) shell.classList.toggle('rr-focus-mode', rrFocusMode);
  var btn = document.getElementById('rr-reader-expand');
  if (btn) {{
    // This same button is the reference's top-left collapse-back arrow once
    // expanded — the rail/list are display:none in focus mode, so this
    // sticky-header button is the only way back (see rr-focus-mode CSS).
    btn.innerHTML = rrFocusMode ? RR_ICON_COLLAPSE : RR_ICON_EXPAND;
    btn.title = rrFocusMode ? 'Exit distraction-free reading' : 'Distraction-free reading';
  }}
}}
function rrToggleFocusMode() {{ rrSetFocusMode(!rrFocusMode); }}
function rrToggleFind() {{
  var bar = document.getElementById('rr-find-bar');
  if (!bar) return;
  var opening = !bar.classList.contains('rr-find-open');
  bar.classList.toggle('rr-find-open', opening);
  if (opening) {{
    var input = document.getElementById('rr-find-input');
    if (input) input.focus();
  }} else {{
    rrFindReset();
  }}
}}
function rrFindReset() {{
  var body = document.getElementById('rr-reader-body-text');
  if (body && rrFindBodyHtml) body.innerHTML = rrFindBodyHtml;
  rrFindMatches = []; rrFindIndex = -1;
  var input = document.getElementById('rr-find-input');
  if (input) input.value = '';
  var count = document.getElementById('rr-find-count');
  if (count) count.textContent = '';
}}
function rrFindRun() {{
  var body = document.getElementById('rr-reader-body-text');
  var input = document.getElementById('rr-find-input');
  var count = document.getElementById('rr-find-count');
  if (!body || !input) return;
  if (!rrFindBodyHtml) rrFindBodyHtml = body.innerHTML;
  body.innerHTML = rrFindBodyHtml;
  rrFindMatches = []; rrFindIndex = -1;
  var q = input.value.trim();
  if (!q) {{ if (count) count.textContent = ''; return; }}
  var re = new RegExp(q.replace(/[.*+?^${{}}()|[\\]\\\\]/g, '\\\\$&'), 'gi');
  var walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT, null);
  var textNodes = [];
  var n;
  while ((n = walker.nextNode())) textNodes.push(n);
  textNodes.forEach(function(node) {{
    var text = node.nodeValue;
    re.lastIndex = 0;
    if (!re.test(text)) return;
    re.lastIndex = 0;
    var frag = document.createDocumentFragment();
    var last = 0;
    var m;
    while ((m = re.exec(text))) {{
      if (m.index > last) frag.appendChild(document.createTextNode(text.slice(last, m.index)));
      var mark = document.createElement('mark');
      mark.className = 'rr-find-hit';
      mark.textContent = m[0];
      frag.appendChild(mark);
      rrFindMatches.push(mark);
      last = m.index + m[0].length;
      if (m[0].length === 0) re.lastIndex++;
    }}
    if (last < text.length) frag.appendChild(document.createTextNode(text.slice(last)));
    node.parentNode.replaceChild(frag, node);
  }});
  if (rrFindMatches.length) rrFindGoTo(0);
  if (count) count.textContent = rrFindMatches.length ? ((rrFindIndex + 1) + '/' + rrFindMatches.length) : '0/0';
}}
function rrFindGoTo(i) {{
  if (!rrFindMatches.length) return;
  if (rrFindIndex >= 0 && rrFindMatches[rrFindIndex]) rrFindMatches[rrFindIndex].classList.remove('rr-find-current');
  rrFindIndex = ((i % rrFindMatches.length) + rrFindMatches.length) % rrFindMatches.length;
  var el = rrFindMatches[rrFindIndex];
  el.classList.add('rr-find-current');
  el.scrollIntoView({{block: 'center', behavior: 'smooth'}});
  var count = document.getElementById('rr-find-count');
  if (count) count.textContent = (rrFindIndex + 1) + '/' + rrFindMatches.length;
}}
function rrFindNext() {{ if (rrFindMatches.length) rrFindGoTo(rrFindIndex + 1); }}
function rrFindPrev() {{ if (rrFindMatches.length) rrFindGoTo(rrFindIndex - 1); }}
function rrFindKeydown(e) {{
  if (e.key === 'Enter') {{ e.preventDefault(); if (e.shiftKey) rrFindPrev(); else rrFindNext(); }}
  else if (e.key === 'Escape') {{ rrToggleFind(); }}
}}
// -- Save-time tagging on a Feed row -----------------------------------------
// "+ Save" opens the row's own inline tag input instead of a window.prompt().
// Tags stay optional: committing with an empty input saves exactly as before.
function rrSaveItem(btn) {{
  var form = btn.closest('.rr-row').querySelector('.rr-row-tagform');
  if (!form) return;
  var opening = !form.classList.contains('rr-tag-open');
  form.classList.toggle('rr-tag-open', opening);
  if (opening) {{
    var input = form.querySelector('input');
    if (input) input.focus();
  }}
}}
function rrRowTagKeydown(e, input) {{
  if (e.key === 'Enter') {{ e.preventDefault(); rrRowSaveGo(input); }}
  else if (e.key === 'Escape') {{ e.preventDefault(); rrRowSaveCancel(input); }}
}}
function rrRowSaveCancel(el) {{
  var form = el.closest('.rr-row-tagform');
  if (!form) return;
  form.classList.remove('rr-tag-open');
  var input = form.querySelector('input');
  if (input) input.value = '';
  var status = form.querySelector('.rr-tag-status');
  if (status) status.textContent = '';
}}
async function rrRowSaveGo(el) {{
  var form = el.closest('.rr-row-tagform');
  var row = el.closest('.rr-row');
  var main = row.querySelector('.rr-row-main');
  var input = form.querySelector('input');
  var goBtn = form.querySelector('.rr-tag-go');
  var status = form.querySelector('.rr-tag-status');
  var saveBtn = row.querySelector('.rr-row-actions button');
  // The server splits on commas itself, so the raw input goes across as-is.
  var tags = input ? input.value : '';
  goBtn.disabled = true;
  goBtn.textContent = 'Saving\\u2026';
  if (status) status.textContent = '';
  try {{
    var r = await fetch('/feed/save', {{method: 'POST',
      headers: {{'Content-Type': 'application/x-www-form-urlencoded'}},
      body: 'url=' + encodeURIComponent(main.dataset.url) + '&tags=' + encodeURIComponent(tags)}});
    if (!r.ok) throw new Error('save failed');
    form.classList.remove('rr-tag-open');
    if (input) input.value = '';
    goBtn.disabled = false;
    goBtn.textContent = 'Save';
    if (saveBtn) {{ saveBtn.textContent = '\\u2713 Saved'; saveBtn.disabled = true; }}
  }} catch (e) {{
    goBtn.disabled = false;
    goBtn.textContent = 'Save';
    if (status) status.textContent = 'Could not save.';
  }}
}}
// -- Inline tag editor in the reader pane -------------------------------------
function rrToggleTagPanel(force) {{
  var panel = document.getElementById('rr-tag-panel');
  if (!panel) return;
  var opening = (force === undefined) ? !panel.classList.contains('rr-tag-open') : force;
  panel.classList.toggle('rr-tag-open', opening);
  if (opening) {{
    rrRenderTagChips('');
    var input = document.getElementById('rr-tag-input');
    // Focusing an input makes the browser scroll it into view on its own. On a
    // mobile-portrait viewport that scrolled the document far enough to clip
    // the panel's first chip row (and the toolbar above it) off the top of the
    // screen — the panel opened somewhere the user couldn't fully see it, the
    // same shape as the Phase 5 "tapping an article does nothing" bug.
    // preventScroll suppresses that; the explicit scroll below then anchors the
    // pane's top to the viewport the same way opening an article does. It only
    // moves the document, never the pane's own scrollTop, so a part-read
    // article keeps its reading position.
    if (input) {{
      try {{ input.focus({{preventScroll: true}}); }} catch (err) {{ input.focus(); }}
    }}
    var pane = document.getElementById('rr-reader');
    if (pane) pane.scrollIntoView({{behavior: 'instant', block: 'start'}});
  }}
}}
function rrRenderTagChips(status) {{
  var wrap = document.getElementById('rr-tag-chips');
  if (!wrap) return;
  var tags = (rrCurrent && rrCurrent.tags) || [];
  // Removal is by index, not by tag text — an index can't break out of the
  // inline handler the way an apostrophe in a tag name could.
  wrap.innerHTML = tags.length
    ? tags.map(function(t, i) {{
        return '<span class="rr-tag-chip">' + rrEsc(t) +
          '<button onclick="rrTagRemove(' + i + ')" title="Remove tag" aria-label="Remove tag">&times;</button></span>';
      }}).join('')
    : '<span class="rr-tag-empty">No tags yet.</span>';
  var st = document.getElementById('rr-tag-status');
  if (st) st.textContent = status || '';
  rrUpdateTagCount();
}}
function rrUpdateTagCount() {{
  var btn = document.getElementById('rr-tag-btn');
  if (!btn) return;
  var n = ((rrCurrent && rrCurrent.tags) || []).length;
  btn.innerHTML = RR_ICON_TAG + (n ? '<span class="rr-tag-count">' + n + '</span>' : '');
}}
function rrTagKeydown(e) {{
  if (e.key === 'Enter') {{
    e.preventDefault();
    if (rrCurrent && rrCurrent.id) rrTagAdd(); else rrSaveCurrentGo();
  }} else if (e.key === 'Escape') {{
    e.preventDefault();
    rrToggleTagPanel(false);
  }}
}}
function rrTagAdd() {{
  var input = document.getElementById('rr-tag-input');
  if (!input || !rrCurrent) return;
  var added = false;
  input.value.split(',').forEach(function(t) {{
    t = t.trim();
    if (t && rrCurrent.tags.indexOf(t) === -1) {{ rrCurrent.tags.push(t); added = true; }}
  }});
  input.value = '';
  if (added) rrTagsPersist();
}}
function rrTagRemove(i) {{
  if (!rrCurrent || !rrCurrent.tags) return;
  rrCurrent.tags.splice(i, 1);
  rrTagsPersist();
}}
// Every add/remove writes through immediately — no separate submit step. The
// input element itself is never re-rendered, so focus survives a save and tags
// can be typed one after another.
async function rrTagsPersist() {{
  if (!rrCurrent || !rrCurrent.id) return;
  rrRenderTagChips('Saving\\u2026');
  try {{
    var r = await fetch('/library/' + rrCurrent.id + '/tags', {{method: 'POST',
      headers: {{'Content-Type': 'application/json'}},
      body: JSON.stringify({{tags: rrCurrent.tags}})}});
    if (!r.ok) throw new Error('save failed');
    var d = await r.json();
    rrCurrent.tags = d.tags || [];
    rrRenderTagChips('Saved');
    rrSyncRowTags(rrCurrent.id, rrCurrent.tags);
  }} catch (e) {{
    rrRenderTagChips('Could not save.');
  }}
}}
// Keep the Archive-view list row's own chips in step with an edit made in the
// reader, so the two panes never disagree without a reload.
function rrSyncRowTags(id, tags) {{
  var el = document.querySelector('.rr-row[data-id="' + id + '"] .rr-row-tags');
  if (!el) return;
  el.innerHTML = tags.map(function(t) {{ return '<span>' + rrEsc(t) + '</span>'; }}).join('');
}}
function rrSaveCurrent() {{
  if (!rrCurrent) return;
  rrToggleTagPanel(true);
}}
async function rrSaveCurrentGo() {{
  if (!rrCurrent || rrCurrent.id) return;
  var input = document.getElementById('rr-tag-input');
  var tags = input ? input.value : '';
  rrRenderTagChips('Saving\\u2026');
  try {{
    var r = await fetch('/feed/save', {{method: 'POST',
      headers: {{'Content-Type': 'application/x-www-form-urlencoded'}},
      body: 'url=' + encodeURIComponent(rrCurrent.url) + '&tags=' + encodeURIComponent(tags)}});
    if (!r.ok) throw new Error('save failed');
    var d = await r.json();
    rrCurrent.id = d.id || null;
    rrCurrent.tags = d.tags || [];
    if (input) input.value = '';
    // Swap the toolbar into saved state in place rather than re-rendering the
    // article, so a part-read page keeps its scroll position and find state.
    rrRefreshSaveState();
    rrRenderTagChips('Saved');
    var selected = document.querySelector('.rr-row-selected .rr-row-actions button');
    if (selected) {{ selected.textContent = '\\u2713 Saved'; selected.disabled = true; }}
  }} catch (e) {{
    rrRenderTagChips('Could not save.');
  }}
}}
function rrRefreshSaveState() {{
  var isSaved = !!(rrCurrent && rrCurrent.id);
  var save = document.getElementById('rr-reader-save');
  if (save) save.hidden = isSaved;
  var tag = document.getElementById('rr-tag-btn');
  if (tag) tag.hidden = !isSaved;
  var go = document.getElementById('rr-tag-savebtn');
  if (go) go.hidden = isSaved;
  var input = document.getElementById('rr-tag-input');
  if (input) input.placeholder = isSaved ? 'Add a tag\\u2026' : 'Tags (comma-separated, optional)';
  rrUpdateTagCount();
}}
async function rrToggleReadLater(btn) {{
  var row = btn.closest('.rr-row');
  var main = row.querySelector('.rr-row-main');
  var isRl = row.dataset.rl === '1';
  var params = new URLSearchParams({{
    url: main.dataset.url, action: isRl ? 'remove' : 'add',
    title: main.dataset.title || '', source: main.dataset.sourceName || '',
    summary: main.dataset.summary || '', published_at: main.dataset.pub || ''
  }});
  btn.disabled = true;
  try {{
    var r = await fetch('/feed/read-later', {{method: 'POST',
      headers: {{'Content-Type': 'application/x-www-form-urlencoded'}}, body: params}});
    if (r.ok) {{
      var next = isRl ? '0' : '1';
      row.dataset.rl = next;
      btn.innerHTML = next === '1' ? '&#10003; Read later' : '&#128204; Read later';
      btn.classList.toggle('rr-row-btn-on', next === '1');
    }}
  }} finally {{ btn.disabled = false; }}
}}
async function rrToggleReadLaterCurrent() {{
  if (!rrCurrent) return;
  var btn = document.getElementById('rr-reader-rl');
  var isOn = btn.classList.contains('rr-row-btn-on');
  var params = new URLSearchParams({{
    url: rrCurrent.url, action: isOn ? 'remove' : 'add',
    title: rrCurrent.title || '', source: rrCurrent.source || ''
  }});
  btn.disabled = true;
  try {{
    var r = await fetch('/feed/read-later', {{method: 'POST',
      headers: {{'Content-Type': 'application/x-www-form-urlencoded'}}, body: params}});
    if (r.ok) {{
      btn.classList.toggle('rr-row-btn-on', !isOn);
      btn.innerHTML = !isOn ? '&#10003; Read later' : '&#128204; Read later';
    }}
  }} finally {{ btn.disabled = false; }}
}}
// Manual per-item "Refresh" for a Read Later article (2026-08 Reader
// cleanliness pass) — re-fetches the URL server-side and replaces the
// cached copy, then reloads the pane via the same rrLoadArticle path a
// fresh open would use, so the freshly-scrubbed content renders in place
// without a full page reload or losing find/scroll state longer than the
// refresh itself takes. No automatic staleness detection — this only ever
// runs on a click.
async function rrRefreshReadLater() {{
  if (!rrCurrent || !rrCurrent.url) return;
  var btn = document.getElementById('rr-refresh-btn');
  if (btn) {{ btn.disabled = true; btn.querySelector('span').textContent = 'Refreshing\\u2026'; }}
  try {{
    var r = await fetch('/read-later/refresh', {{method: 'POST',
      headers: {{'Content-Type': 'application/json'}},
      body: JSON.stringify({{url: rrCurrent.url}})}});
    var result = r.ok ? await r.json() : {{ok: false}};
    if (result.ok) {{
      await rrLoadArticle(rrCurrent.id, rrCurrent.url, {{
        title: rrCurrent.title, source: rrCurrent.source,
        pub: rrCurrent.published_at, summary: ''
      }});
    }} else if (btn) {{
      btn.querySelector('span').textContent = 'Couldn\\u2019t refresh';
      setTimeout(function() {{ if (btn) btn.querySelector('span').textContent = 'Refresh'; }}, 2500);
    }}
  }} catch (e) {{
    if (btn) btn.querySelector('span').textContent = 'Couldn\\u2019t refresh';
  }} finally {{
    if (btn) btn.disabled = false;
  }}
}}
// Permanently removes the currently open article from the library. The
// route (POST /library/{{id}}/delete) redirects on success rather than
// returning JSON — fetch follows that redirect transparently, so r.ok is
// still the right success check; no route change needed for this to work
// from an AJAX context. Reuses the same delete mechanism (Library.
// purge_article, via delete_article's full cascade — FTS, embeddings,
// content_refetch_log, url_correction_log) the CSV bulk-delete tool at
// /admin/reader/bulk-delete uses, just reached one article at a time.
async function rrDeleteCurrent() {{
  if (!rrCurrent || !rrCurrent.id) return;
  var title = rrCurrent.title || 'this article';
  if (!confirm('Permanently remove \\u201c' + title + '\\u201d from the library? This can\\u2019t be undone.')) return;
  var btn = document.getElementById('rr-delete-btn');
  if (btn) btn.disabled = true;
  var deletedId = rrCurrent.id;
  try {{
    var r = await fetch('/library/' + deletedId + '/delete', {{method: 'POST'}});
    if (!r.ok) throw new Error('delete failed');
    var row = document.querySelector('.rr-row[data-id="' + deletedId + '"]');
    if (row) row.remove();
    rrCurrent = null;
    var pane = document.getElementById('rr-reader');
    if (pane) pane.innerHTML = '<div class="rr-reader-empty"><div>Removed from the library.</div></div>';
  }} catch (e) {{
    alert('Could not remove this article. Please try again.');
    if (btn) btn.disabled = false;
  }}
}}
async function rrRemoveReadLater(btn) {{
  var url = btn.dataset.url;
  btn.disabled = true;
  try {{
    var r = await fetch('/feed/read-later', {{method: 'POST',
      headers: {{'Content-Type': 'application/x-www-form-urlencoded'}},
      body: new URLSearchParams({{url: url, action: 'remove'}})}});
    if (r.ok) {{
      var row = btn.closest('.rr-row');
      row.style.transition = 'opacity .25s';
      row.style.opacity = '0';
      setTimeout(function() {{ row.remove(); }}, 260);
    }}
  }} finally {{ btn.disabled = false; }}
}}
async function rrRecheckAuth(e) {{
  e.preventDefault();
  try {{ await fetch('/admin/auth/recheck', {{method: 'POST'}}); }} catch (err) {{}}
  location.reload();
}}
(function() {{
  function makeResizer(handleId, paneEl, min, max) {{
    var handle = document.getElementById(handleId);
    if (!handle) return;
    handle.addEventListener('mousedown', function(e) {{
      e.preventDefault();
      var startX = e.clientX, startWidth = paneEl.getBoundingClientRect().width;
      function onMove(ev) {{
        var next = Math.max(min, Math.min(max, startWidth + (ev.clientX - startX)));
        paneEl.style.flexBasis = next + 'px';
      }}
      function onUp() {{
        window.removeEventListener('mousemove', onMove);
        window.removeEventListener('mouseup', onUp);
      }}
      window.addEventListener('mousemove', onMove);
      window.addEventListener('mouseup', onUp);
    }});
  }}
  makeResizer('rr-resize-rail', document.getElementById('rr-rail'), 150, 360);
  makeResizer('rr-resize-list', document.getElementById('rr-list-pane'), 300, 760);
}})();
</script>"""
    )

    return HTMLResponse(_page("Reader—Brian Weisberg", "Reader", body, role=_role(request), request=request))


# Note: /library/past-questions was retired in Phase 2 — folded into the
# "Search past questions" section on /tools/fpa-buddy (see fpa_buddy_page),
# filtered to only helpful-rated answers. No redirect — nothing bookmarked.
# The old flat /questions redirect stub is gone too, for the same reason.


@app.post("/questions/{question_id}/hide")
async def community_question_hide(request: Request, question_id: int):
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        row = lib.conn.execute("SELECT hidden_public FROM ask_questions WHERE id=?", (question_id,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        lib.set_ask_question_hidden(question_id, not bool(row["hidden_public"]))
    finally:
        lib.close()
    return RedirectResponse("/tools/fpa-buddy#past-questions", status_code=303)


@app.post("/questions/{question_id}/private")
async def own_question_toggle_private(request: Request, question_id: int):
    """Flip the privacy of the signed-in member's own conversation from a
    past-question row. Own rows only: anything else is a 403."""
    _require_member(request)
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        row = lib.get_ask_question(question_id)
        if row is None:
            raise HTTPException(status_code=404, detail="not found")
        if user_id is None or row["user_id"] != user_id or not row.get("conversation_id"):
            raise HTTPException(status_code=403, detail="not your question")
        lib.set_conversation_private(row["conversation_id"], user_id, not bool(row.get("is_private")))
    finally:
        lib.close()
    return RedirectResponse("/tools/fpa-buddy#past-questions", status_code=303)


