@app.get("/health")
def health():
    return {"ok": True}


@app.get("/api/search")
def api_search(request: Request, q: str = "", limit: int = 50, token: str | None = None):
    # Admin-only, matching /read's real access tier (Library content includes
    # articles behind Brian's own paid subscriptions — see _is_authed's
    # docstring). Previously _require_member (any signed-in user), a
    # likely-unintentional survivor of the Phase 1 restructure that moved
    # the Reader itself to admin-only without revisiting this API route—
    # see ARCHITECTURE.md's MCP-server Phase 4 note (now corrected to match).
    _require_api(request, token)
    lib = _lib()
    try:
        return {"query": q, "results": lib.search(q, limit=limit)}
    finally:
        lib.close()


# One look and one height for the small action buttons on the FP&A Buddy
# surfaces (Done, Resume). 44px is the Depth and Sources control height and the
# touch minimum; the existing buttons are not restyled.
_ASK_CTL_CSS = (
    ".ask-ctl{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0 16px;"
    "box-sizing:border-box;border:1px solid var(--navy);border-radius:10px;background:transparent;color:var(--navy);"
    "font:600 14px var(--font-body);cursor:pointer;text-decoration:none;white-space:nowrap;}"
    "@media(hover:hover){.ask-ctl:hover{background:var(--accent-light);}}"
    ".ask-ctl:focus-visible{outline:2px solid var(--navy);outline-offset:2px;}"
    # Compact variant: 28px visible, with a 44px touch target from a pseudo-element
    # that adds no layout height (inset from the 1px border, so -9px gives 44px). -w gives the row buttons one shared width
    # (sized to the widest label, "Remove from view", with room to spare).
    ".ask-ctl-sm{min-height:28px;padding:0 12px;font-size:13px;position:relative;}"
    ".ask-ctl-sm::after{content:\"\";position:absolute;left:0;right:0;top:-9px;bottom:-9px;}"
    # Width is a floor, not a fixed value: a label that fits renders at exactly 128px, a wider
    # one (fallback font) grows instead of spilling out of the pill.
    ".ask-ctl-w{min-width:128px;padding-left:10px;padding-right:10px;white-space:nowrap;}"
    ".ask-ctl[aria-pressed=true]{background:var(--navy);color:#fff;}"
)


# One table, one builder: every status on a Buddy question (a rating, Private,
# Hidden) is drawn by _ask_status_chip and nothing else. glyph, word, aria-label.
_ASK_STATUS_CHIPS = {
    "helpful": ("&#10003;", "Helpful", "Rated helpful"),
    "not_helpful": ("&#10005;", "Not helpful", "Rated not helpful"),
    "mixed": ("&#177;", "Mixed", "Rated mixed"),
    "private": ("&#128274;", "Private", "Private"),
    "hidden": ("&#8856;", "Hidden", "Hidden by an admin"),
    "failed": ("&#9888;", "Failed", "Failed turn, no answer was produced"),
}


# Status chip styles, shared by every page that draws a chip (the Buddy page and
# /ask/history). Plain string, single braces; injected with {_ASK_CHIP_CSS}.
_ASK_CHIP_CSS = (
    "/* Status chips (BRAND.md, Status chips): non-interactive, 18px, no border. One neutral fill; Hidden is admin-only deep-seafoam text with no fill. */\n"
    ".ask-chip{display:inline-flex;align-items:center;gap:3px;box-sizing:border-box;height:18px;padding:0 8px;border-radius:999px;background:var(--line);color:var(--ink-soft);font-size:12px;line-height:1;white-space:nowrap;}\n"
    ".ask-chip-hidden{background:none;padding:0;color:var(--seafoam-deep);}\n"
    ".ask-chip-failed{background:none;padding:0;color:var(--alert);}\n"
)


def _ask_status_chip(kind: str) -> str:
    """The ONE place a Buddy question status is drawn: a non-interactive chip,
    glyph plus word (BRAND.md, Status chips). Plain code points only. Hidden is
    admin-only, so it carries no fill (deep seafoam text); callers decide who
    sees it."""
    glyph, word, label = _ASK_STATUS_CHIPS[kind]
    return (f'<span class="ask-chip ask-chip-{kind}" role="img" aria-label="{label}" title="{label}">'
            f'<span aria-hidden="true">{glyph}</span> {word}</span>')


def _ask_rating_kind(helpful_count, negative_count) -> str | None:
    hc, nc = int(helpful_count or 0), int(negative_count or 0)
    if hc and not nc:
        return "helpful"
    if hc and nc:
        return "mixed"
    if nc:
        return "not_helpful"
    return None


def _ask_status_chips_html(helpful_count=0, negative_count=0, *, private=False,
                           hidden=False, viewer_is_admin=False, failed=False) -> str:
    """The chips for one question, in the one order every surface uses:
    Failed and Hidden (admin only), Private, rating. Unrated, public, visible
    shows nothing."""
    kinds = []
    if failed and viewer_is_admin:
        kinds.append("failed")
    if hidden and viewer_is_admin:
        kinds.append("hidden")
    if private:
        kinds.append("private")
    rk = _ask_rating_kind(helpful_count, negative_count)
    if rk:
        kinds.append(rk)
    return "".join(_ask_status_chip(k) for k in kinds)


# The Private chip as a JS string literal, for the Recent rows the page builds
# client-side. Built by the one chip function, never by hand in JS.
_ASK_PRIVATE_CHIP_JS = json.dumps(_ask_status_chip("private")).replace("</", "<\\/")


def _ask_byline(row: dict, viewer_user_id: int | None, viewer_is_admin: bool) -> str | None:
    """Who a past-question row is credited to, for one viewer. Three cases,
    in this order: (1) the viewer asked it, "You" (checked first, so an admin
    sees "You" on their own questions); (2) someone else asked it and the
    viewer is an admin, the stored full name; (3) a member viewing someone
    else's question gets None (the asker is never named to other users).
    "Own" is `user_id` equality, never a name comparison. The legacy
    break-glass admin login has no user id, so no row is ever "own" there and
    it falls to case 2."""
    if viewer_user_id is not None and row.get("user_id") == viewer_user_id:
        return "You"
    if viewer_is_admin:
        return row.get("asker_name") or row.get("asker_username") or "A user"
    return None


@app.get("/tools/fpa-buddy", response_class=HTMLResponse)
def fpa_buddy_page(request: Request, q: str = "", pq: str = "", helpful: str = ""):
    # Member-gated: signed-in members and admin. Anonymous visitors go to login.
    if not _is_member(request):
        return _login_redirect(request)
    authed = _is_authed(request)   # admin flag (e.g. for any admin-only affordances)

    from linklib.agent import COST_ESTIMATES, EFFORT_SETTINGS

    # This month's usage-to-date vs. the user's effective dollar cap (their
    # override, else the global default). None for token-only access or the
    # break-glass admin login with no matching `users` row — those aren't
    # capped, so there's nothing to show.
    usage_lib = _lib()
    try:
        usage_user_id = _current_user_id(usage_lib, request)
        usage_today = None
        if usage_user_id is not None:
            usage_today = {
                "spent": round(usage_lib.ask_cost_this_month(usage_user_id), 2),
                "cap": round(usage_lib.get_effective_ask_cap(usage_user_id), 2),
            }
        # Past Questions (Phase 2 — folded in from the old standalone
        # /library/past-questions page): only questions with at least one
        # ask_feedback.rating='helpful' row, so a member searching here only
        # ever finds answers someone already vouched for.
        helpful_only = helpful == "1"
        pq_rows = usage_lib.list_public_ask_questions(query=pq, limit=200, helpful_only=helpful_only,
                                                      viewer_id=usage_user_id, see_private=authed)
        # One Exa call per turn when the web source is on and Exa (not the native
        # tool) is the provider; nothing else a turn does calls Exa. Admin-only.
        from linklib.agent import _web_provider
        from linklib.pricing import compute_exa_cost
        exa_unit = compute_exa_cost("search") if (authed and _web_provider(usage_lib) == "exa") else 0.0
    finally:
        usage_lib.close()

    def _pq_row(r: dict) -> str:
        # Byline: one shared function (_ask_byline), three cases in order.
        date = _esc((r.get("created_at") or "")[:10])
        who = _ask_byline(r, usage_user_id, authed)
        admin_controls = ""
        if authed:
            admin_controls = f"""<div style="display:flex;gap:8px;margin-top:10px;padding-top:10px;border-top:1px solid var(--line);">
      <form method="post" action="/questions/{r["id"]}/hide" style="margin:0;"><button type="submit" class="admin-only ask-ctl-sm ask-ctl-w">{"Unhide" if r.get("hidden_public") else "Hide"}</button></form>
    </div>"""
        # Meta: status chips first (Hidden for admins, Private, rating, from the
        # one chip function), then the byline and date as plain nowrap segments.
        # The chip set is the same on every surface; unrated, public, visible
        # shows nothing.
        chips = _ask_status_chips_html(r.get("helpful_count"), r.get("negative_count"),
                                       private=bool(r.get("is_private")),
                                       hidden=bool(r.get("hidden_public")), viewer_is_admin=authed,
                                       failed=bool(r.get("failed")))
        segs = [chips] if chips else []
        if who is not None:
            segs.append(f'<span class="ask-pq-seg">{_esc(who)}</span>')
        segs.append(f'<span class="ask-pq-seg ask-pq-date">{date}</span>')
        meta_html = f'<span class="ask-pq-ml">{"".join(segs)}</span>'
        q_txt = _esc(r.get("question") or "")
        a_html, src_html = _render_cited_answer(r.get("answer") or "",
                                                r.get("citations_json") or "[]")
        if r.get("failed"):
            # Only an admin ever gets a failed row. No answer exists; show the
            # raw error text instead (admin only).
            a_html = f'<p style="margin:0;color:var(--alert);">{_esc(r.get("error") or "No answer was produced.")}</p>'
            src_html = ""
        # Resume is for the reader's own conversations only; another member's
        # row gets nothing. The server still decides (403 for someone else's).
        resume_html = ""
        if usage_user_id is not None and r.get("user_id") == usage_user_id and r.get("conversation_id"):
            priv_label = "Allow sharing" if r.get("is_private") else "Make private"
            resume_html = (f'<div class="ask-pq-foot">'
                           f'<form method="post" action="/questions/{r["id"]}/private" style="margin:0;">'
                           f'<button type="submit" class="ask-ctl ask-ctl-sm ask-ctl-w">{priv_label}</button></form>'
                           f'<button type="button" class="ask-ctl ask-ctl-sm ask-ctl-w" '
                           f'data-cid="{_esc(r["conversation_id"])}" onclick="resumeConvoById(this.dataset.cid)">Resume</button></div>')
        # A native <details>, closed on every load: the row is the question,
        # byline and a chevron; the answer, sources and admin buttons are the
        # disclosure body. Same fold element the Search past questions section uses.
        return f"""<details class="ask-pq-row">
  <summary class="ask-pq-sum"><span class="ask-pq-rc" aria-hidden="true">&#9656;</span><span class="ask-pq-q">{q_txt}</span><span class="ask-pq-meta">{meta_html}</span></summary>
  <div class="ask-pq-body">
    <div class="ask-hist-answer" style="margin:0;">{a_html}</div>
    {src_html}
    {resume_html}
    {admin_controls}
  </div>
</details>"""

    if pq_rows:
        pq_empty = ""
    elif pq:
        pq_empty = "No past questions match your search."
    elif helpful_only:
        pq_empty = "No questions have been rated helpful yet."
    else:
        pq_empty = "No past questions yet."
    pq_rows_html = "".join(_pq_row(r) for r in pq_rows) or \
        ('<div style="background:var(--surface);border:1px solid var(--line);border-radius:12px;'
         'padding:24px;text-align:center;color:var(--muted);">' + pq_empty + '</div>')
    pq_heading = "Helpful questions only" if helpful_only else "All questions"
    # Search keeps the filter it was run under; the toggle flips it. Both are
    # submit buttons named "helpful", so one GET form carries either value.
    pq_keep = "1" if helpful_only else ""
    pq_flip = "" if helpful_only else "1"

    # A <details> so it can fold to one line while a conversation is on screen
    # (the page toggles `open` itself when a thread appears or clears). In the
    # empty state it is always open and its summary is inert, so that state
    # reads exactly as it did when this was a plain section.
    past_questions_section = f"""<details id="past-questions" class="ask-section ask-pq" open style="margin-top:0;margin-bottom:28px;">
  <summary class="ask-section-label"><span class="ask-pq-caret" aria-hidden="true">&#9656;</span>Search past questions</summary>
  <p style="color:var(--muted);margin:-4px 0 14px;font-size:14px;line-height:1.5;">Search before running your query.</p>
  <form method="get" action="/tools/fpa-buddy" style="display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center;">
    <input type="search" name="pq" value="{_esc(pq)}" placeholder="Search past questions&hellip;"
      style="flex:1 1 200px;padding:10px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:16px;background:#fff;">
    <button type="submit" name="helpful" value="{pq_keep}" class="ask-ctl ask-ctl-sm ask-ctl-w">Search</button>
    <button type="submit" name="helpful" value="{pq_flip}" class="ask-ctl ask-ctl-sm ask-ctl-w" aria-pressed="{"true" if helpful_only else "false"}">Helpful only</button>
  </form>
  <h2 class="ask-pq-heading">{pq_heading}</h2>
  {pq_rows_html}
</details>"""

    # Quick / Standard / Deep is the only choice shown — no separate model
    # picker. Each tier maps internally (linklib.agent.EFFORT_SETTINGS) to a
    # model plus archive/web-search count and token budget; the model itself
    # is an implementation detail, never surfaced to the end user.
    #
    # The per-tier detail (archive count, web-search count, token estimate) used
    # to render as persistent subtext under each tier's name, inside a tall
    # card. It's now a hover tooltip on a compact button instead: the same
    # information, available on demand, without three cards' worth of vertical
    # space for what is a one-of-three choice.
    effort_details = [
        ("quick",    "Quick",    "4 archive sources &middot; 2 web results &middot; ~700 tokens out"),
        ("standard", "Standard", "8 archive sources &middot; 4 web results &middot; ~1,500 tokens out"),
        ("deep",     "Deep",     "16 archive sources &middot; 6 web results &middot; ~2,500 tokens out"),
    ]
    RECOMMENDED_TIER = "standard"
    # Logged-in (Brian) gets the balanced default; anonymous users default to
    # the most efficient tier (a cost guard, not a recommendation).
    default_effort = "standard" if authed else "quick"

    # Sources — the same seafoam-fill/navy-text tag component used elsewhere on
    # the site (BRAND.md §5), toggled on/off by tap instead of a checkbox list.
    source_defs = [
        ("library", "Curated archive", True),
        ("feed", "Current feed", True),
        ("open_web", "Open web", False),
    ]
    _CHECK_SVG = ('<svg viewBox="0 0 10 10" width="10" height="10" aria-hidden="true">'
                  '<path d="M1 5L4 8L9 2" stroke="#001B4F" stroke-width="1.6" fill="none" '
                  'stroke-linecap="round" stroke-linejoin="round"/></svg>')

    def source_tag(key, label, active):
        cls = "ask-tag active" if active else "ask-tag"
        return (f'<button type="button" class="{cls}" data-source="{key}" '
                f'aria-pressed="{"true" if active else "false"}" onclick="toggleSource(this)">'
                f'{_CHECK_SVG}<span class="ask-tag-name">{label}</span></button>')

    source_tags = "".join(source_tag(k, l, a) for k, l, a in source_defs)

    # Depth reuses the Sources tag component verbatim so the two columns carry
    # the same visual weight — the only difference is behavior: Sources is a
    # multi-select toggle, Depth is single-select (radio), enforced in
    # selectTier() and marked up as a real radiogroup for assistive tech.
    def tier_tag(val, label, detail, selected):
        cls = "ask-tag active" if selected else "ask-tag"
        hint = detail + (" &middot; Recommended" if val == RECOMMENDED_TIER else "")
        return (f'<button type="button" class="{cls}" data-tier="{val}" role="radio" '
                f'aria-checked="{"true" if selected else "false"}" title="{hint}" '
                f'onclick="selectTier(this)">'
                f'{_CHECK_SVG}<span class="ask-tag-name">{label}</span><span class="ask-tag-cost"></span></button>')

    tier_tags = "".join(tier_tag(v, l, d, v == default_effort) for v, l, d in effort_details)

    # Cost estimates are for Brian's eyes only — never exposed to anonymous
    # users. When not authed, the cost table is empty and the estimate line is
    # omitted from the page entirely. Keyed by tier only (not model) since the
    # model is no longer a user-visible axis.
    import json as _json
    tier_cost = {
        tier: COST_ESTIMATES.get(settings["model"], {}).get(tier)
        for tier, settings in EFFORT_SETTINGS.items()
    }
    cost_js = _json.dumps(tier_cost) if authed else "{}"
    exa_js = _json.dumps(exa_unit) if authed else "0"
    # Admin-only, one muted line at the bottom of the Depth dropdown, next to the
    # dollar amounts it explains (same look as the Sources note).
    cost_note = ('<p class="ask-dd-note ask-cost-note" style="color:var(--muted);">Dollar amounts are estimates.</p>'
                 if authed else "")

    usage_html = ""
    if usage_today is not None:
        usage_html = (
            f'<div id="ask-usage" style="font-size:13px;color:var(--muted);margin:0;">'
            f'<span id="ask-usage-text">${usage_today["spent"]:.2f} of ${usage_today["cap"]:.2f} used this month</span>'
            f' &middot; <a href="/ask/history" style="color:var(--accent);">Your usage and past questions &rarr;</a>'
            f'</div>'
        )

    pre_q = _esc(q)

    # The usage line is genuinely absent (not just visually blank) for
    # anonymous visitors and for any admin with no cap tracked — dropping
    # its grid row entirely in that case (rather than rendering an empty
    # div that still occupies a row-gap on both sides) is what actually
    # closes the intro-to-Question-box dead space; see the CSS comment
    # below for why a spaced-out `usage` row happens at all otherwise.
    usage_div = f'<div class="fpa-intro-area-usage">{usage_html}</div>' if usage_html else ""
    # The example is a hardcoded snapshot of a real conversation (webapp/buddy_example.py),
    # rendered through the same helper the history pages use, so it reads like a real answer.
    _example_answer_html, _example_sources_html = _render_cited_answer(
        _BUDDY_EXAMPLE.ANSWER, _BUDDY_EXAMPLE.CITATIONS_JSON)
    _intro_areas_desktop = (
        '"intro example" "usage example" "question example"'
        if usage_html else
        '"intro example" "question example"'
    )
    _intro_rows_desktop = "auto auto 1fr" if usage_html else "auto 1fr"
    # While a conversation is on screen the illustrative example is hidden and
    # the form is one full-width column (no empty right-hand track).
    _intro_areas_thread = (
        '"intro" "usage" "question"'
        if usage_html else
        '"intro" "question"'
    )
    _intro_areas_mobile = (
        '"intro" "example" "usage" "question"'
        if usage_html else
        '"intro" "example" "question"'
    )

    body = f"""<div class="page page-standard" id="fpa-page">
<p style="margin:0 0 12px;"><a href="/tools" style="font-size:13px;color:var(--muted);">&larr; Toolbox</a></p>

<div class="fpa-intro-layout">
  <div class="fpa-intro-area-intro">
    <span class="ask-eyebrow">CFO Navigator</span>
    <h1 style="margin-bottom:6px;">FP&amp;A Buddy</h1>
    <p style="color:var(--ink-soft);margin:0 0 12px;font-size:15.5px;line-height:1.6;">Ask a real FP&amp;A question and get an answer with its sources, not half a day of Googling. It pulls from a research archive I curate by hand, and it remembers the thread, so you can follow up.</p>
    <p class="ask-teaser"><a href="/tools/fpa-buddy/how-it-works">How it works &rarr;</a></p>
  </div>
  <div class="fpa-intro-area-example">
    <div class="ask-example">
      <div class="ask-example-label">A real question and answer, shown as asked.</div>
      <div class="ask-example-settings">Depth: Standard &middot; Sources: Curated archive, Current feed</div>
      <div class="ask-q-bubble">{_esc(_BUDDY_EXAMPLE.QUESTION)}</div>
      <div class="ask-answer ask-hist-answer" id="ask-ex-answer">{_example_answer_html}</div>
      <button type="button" class="btn btn-ghost ask-ex-toggle" id="ask-ex-toggle" aria-expanded="false" aria-controls="ask-ex-answer" hidden>Show full answer</button>
      {_example_sources_html}
    </div>
    <script>{_ASK_EXAMPLE_JS}</script>
  </div>
  {usage_div}
  <div class="fpa-intro-area-question">
    <div class="ask-card">
      <div class="fpa-intro-area-controls">
        <div class="ask-dd" id="ask-dd-top">
          <div class="ask-dd-row">
            <div class="ask-dd-col">
              <label class="ask-dd-lbl"><span class="ask-dd-h">Depth</span><button type="button" class="ask-dd-btn" data-dd="depth" aria-expanded="false" onclick="toggleDd(this)"><span class="ask-dd-k">Depth:</span><span class="ask-dd-v"></span><span class="ask-dd-caret" aria-hidden="true">&#9662;</span></button></label>
              <div class="ask-dd-panel" data-dd="depth" hidden>
                <div class="ask-tags" role="radiogroup" aria-label="Depth">
                  {tier_tags}
                </div>
                {cost_note}
              </div>
            </div>
            <div class="ask-dd-col">
              <label class="ask-dd-lbl"><span class="ask-dd-h">Sources</span><button type="button" class="ask-dd-btn" data-dd="sources" aria-expanded="false" onclick="toggleDd(this)"><span class="ask-dd-k">Sources:</span><span class="ask-dd-v"></span><span class="ask-dd-caret" aria-hidden="true">&#9662;</span></button></label>
              <div class="ask-dd-panel" data-dd="sources" hidden>
                <div class="ask-tags">
                  {source_tags}
                </div>
                <p class="ask-dd-note"><a href="/current-feed" style="color:var(--muted);">See what's in the current feed &rarr;</a></p>
              </div>
            </div>
          </div>
        </div>
      </div>
      <label for="ask-q" class="ask-q-label">Start a new conversation</label>
      <div class="ask-q-wrap">
        <textarea id="ask-q" rows="5" autofocus placeholder="e.g. What frameworks do CFOs use for headcount planning in uncertain environments?">{pre_q}</textarea>
        <button type="button" class="fu-send ask-send" id="ask-btn" onclick="doAsk()" aria-label="Ask" title="Ask"{'' if q.strip() else ' disabled'}><span class="fu-send-dot"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7"/></svg></span></button>
      </div>
      <div id="ask-sim" class="ask-sim" hidden aria-live="polite"></div>
      <label class="ask-priv-opt"><input type="checkbox" id="ask-private"><span>Keep this question private</span></label>
      <p class="ask-priv-note">Shared with other users without your name. Admins can see every question. Leave out company names and figures you want kept confidential. <a href="/privacy">Privacy policy</a></p>
    </div>
  </div>
</div>

{past_questions_section}

<div id="ask-recent" class="ask-section" style="display:none;"></div>

<div id="ask-thread"></div>
</div>

<style>
.ask-eyebrow{{display:block;font-size:11.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;}}
.ask-card{{background:#fff;border:1px solid var(--line);border-radius:16px;padding:18px 20px;margin-bottom:0;}}

.ask-teaser{{font-size:14px;color:var(--ink-soft);margin:0 0 4px;}}
.ask-teaser a{{color:var(--accent);font-weight:600;}}

/* Top section only, decoupled by grid-template-areas so desktop and mobile
   can place the same DOM children differently without JS or an explicit
   `order` property. Desktop: description, usage line, and the Question box
   stack down the left column — sharing its left edge with the illustrative
   example's own column start — while the example spans only those three
   rows on the right (so its bottom edge lines up with the Question box's
   rather than running the full height of the left column). Sources/Depth/
   Ask then drop back to full width below both, sharing the Question box's
   left edge without being squeezed into its ~600px column — full width was
   never the problem, only the mismatched left edge was. Mobile collapses to
   one column in the exact reading order this page used before the desktop
   fill was added — kept because it already reads well: description,
   example, usage, question, controls, action.

   `grid-template-rows:auto auto 1fr auto auto` (question is the one `1fr`
   row) fixes a real dead-space bug: when the example card is taller than
   intro+usage+question combined, plain `auto` rows don't confine that
   leftover to the last-spanned row the way the bottom-edge-alignment
   comment below originally assumed — confirmed live (the empty `usage`
   row, and intro's own row, were each padded out by ~30px they had no
   content to justify, opening a ~93px gap between the intro text and the
   Question box with no line of CSS ever asking for it) and confirmed
   again in an isolated minimal test page, ruling out interference from
   this page's other rules: even pinning intro/usage to `grid-template-
   rows:max-content` (the first fix tried) had zero effect — browsers
   still redistribute leftover space beyond a track's declared max-content
   growth limit once every spanned track has been maxed out and space
   still remains, per the Grid spec's own "distribute space beyond growth
   limits" fallback step. A `1fr` track is different: it's sized via a
   separate, later pass (flexible-track distribution) that only ever
   grows to absorb genuine leftover space, never competes for it against
   plain content-sized tracks — so making `question` the one `1fr` row
   (intro/usage stay plain `auto`, sized to their own content only) routes
   100% of the leftover there by construction, not as a side effect of a
   limit some other mechanism can still override. Reset to `none` on
   mobile, where the layout is a single column with no spanning item to
   redistribute space from — an explicit 5-row sizing declared for the
   desktop's 5 rows would otherwise misapply to mobile's differently-
   ordered 6 rows (`example` is its own
   row there, not a 3-row-spanning column).

   The `1fr` fix alone still leaves two structural `row-gap`s (one above
   the empty `usage` row, one below it) between the intro text and the
   Question box whenever there's no usage line to show — genuinely no
   longer unexplained dead space, but still more than the ~20-24px this
   form uses elsewhere. Rather than shrink the shared row-gap (which
   would also touch the question-to-controls and controls-to-action
   gaps) or fake it with a negative margin (`row-gap` reserves real space
   between tracks regardless of an item's own margin, so a margin trick
   wouldn't actually close it), `usage`'s grid area and its own `<div>`
   are both omitted entirely from Python when `usage_html` is empty
   (`_intro_areas_desktop`/`_intro_rows_desktop`/`_intro_areas_mobile`,
   computed once above) — a row that isn't there needs no row-gap around
   it, and it's a fact-driven omission (there's genuinely nothing to
   show), not a magic-number one. `row-gap` itself moved from 16px to
   20px — the exact Sources-to-Depth spacing round 4 already established
   as this page's own reference value for "the same spacing used
   elsewhere in the form" — so the remaining single gap (intro's own
   bottom to the Question box, once `usage` drops out) lands at exactly
   20px, and the question-to-controls/controls-to-action gaps below tick
   up from ~16.5px to the same 20px for a genuinely more consistent
   result, not a regression. */
.fpa-intro-layout{{display:grid;grid-template-columns:1fr 1fr;column-gap:40px;row-gap:20px;
  grid-template-areas:{_intro_areas_desktop};
  grid-template-rows:{_intro_rows_desktop};
  align-items:start;margin-bottom:28px;}}
/* Thread open (set by the page's script on #fpa-page): no example, one column. */
.fpa-thread-open .fpa-intro-area-example{{display:none;}}
.fpa-thread-open .fpa-intro-layout{{grid-template-columns:1fr;grid-template-rows:none;
  grid-template-areas:{_intro_areas_thread};}}
.ask-pq>summary{{list-style:none;display:flex;align-items:center;gap:8px;pointer-events:none;cursor:default;}}
.ask-pq>summary::-webkit-details-marker{{display:none;}}
.ask-pq>summary .ask-pq-caret{{display:none;font-size:12px;transition:transform .12s;}}
.ask-pq:not([open])>summary{{margin-bottom:0;}}
.fpa-thread-open .ask-pq>summary{{pointer-events:auto;cursor:pointer;}}
.fpa-thread-open .ask-pq>summary .ask-pq-caret{{display:inline-block;}}
.ask-pq[open]>summary .ask-pq-caret{{transform:rotate(90deg);}}
.fpa-intro-area-intro{{grid-area:intro;}}
.fpa-intro-area-example{{grid-area:example;align-self:stretch;}}
.fpa-intro-area-usage{{grid-area:usage;}}
.fpa-intro-area-question{{grid-area:question;align-self:stretch;}}
@media(max-width:900px){{.fpa-intro-layout{{grid-template-columns:1fr;row-gap:24px;grid-template-rows:none;
  grid-template-areas:{_intro_areas_mobile};}}}}

/* Depth and Sources sit inside the question card, above the text box. Each has a
   visible header above its control (a real wrapping <label>). Two columns from
   641px, one stacked column below. The follow-up bubble's clone keeps its old
   compact look: the headers are hidden there and the closed buttons carry their
   own "Depth:" / "Sources:" prefix instead. */
.fpa-intro-area-controls{{margin:0 0 14px;}}
.ask-dd-col{{flex:1 1 0;min-width:0;}}
.ask-dd-lbl{{display:flex;flex-direction:column;gap:6px;}}
.ask-dd-h{{font-size:11.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);}}
.ask-dd-k{{display:none;}}
.fu .ask-dd-h{{display:none;}}
.fu .ask-dd-k{{display:inline;}}
.ask-tag-cost{{margin-left:auto;font-weight:500;color:var(--muted);}}
.ask-q-wrap{{position:relative;flex:1;display:flex;}}
.ask-q-wrap textarea{{flex:1;width:100%;box-sizing:border-box;padding:11px 56px 11px 14px;border:1px solid var(--line);border-radius:10px;font:inherit;font-size:16px;background:var(--bg);resize:none;}}
.ask-send{{position:absolute;right:4px;bottom:4px;}}
/* Stacked on a phone: header, control, then its own panel, then the next header,
   so a panel always opens directly under the button that opened it. The row
   dissolves (display:contents) so labels and panels order as siblings. The
   follow-up bubble's clone keeps its side-by-side row. */
@media(max-width:640px){{
  .fpa-intro-area-controls .ask-dd-row{{flex-direction:column;align-items:stretch;gap:12px;}}
}}
}}

/* Bottom-edge alignment between the Question box and the illustrative
   example: `align-self:stretch` on both grid items (above) makes each
   fill its assigned row(s) exactly, and the two-part rule below makes the
   visible cards fill that stretched space rather than just their own
   content height — no hardcoded height anywhere. This works because the
   "example" grid area spans exactly the intro/usage/question rows (it
   never appears in the "controls controls"/"action action" rows below):
   when its natural content is taller than those three rows combined,
   `grid-template-rows`'s `1fr` track for `question` (intro/usage stay
   plain `auto`, above) absorbs 100% of that leftover height by
   construction — which is what pulls the Question box's row down to meet
   the example's real height, rather than a value picked by hand. */
.fpa-intro-area-question{{display:flex;}}
.fpa-intro-area-question .ask-card{{flex:1;display:flex;flex-direction:column;}}
.fpa-intro-area-question .ask-card .ask-q-wrap{{flex:1;}}
.fpa-intro-area-question .ask-card textarea{{min-height:96px;}}
.fpa-intro-area-example{{display:flex;}}
.fpa-intro-area-example .ask-example{{flex:1;display:flex;flex-direction:column;}}
.fpa-intro-area-example .ask-answer{{flex:1;}}

.ask-example{{border:1px dashed var(--line-strong);border-radius:14px;padding:18px 20px;margin:0 0 24px;background:var(--surface);}}
.ask-example.ask-ex-js:not(.open) .ask-answer{{max-height:300px;overflow:hidden;position:relative;}}
.ask-example.ask-ex-js:not(.open) .ask-answer:after{{content:"";position:absolute;left:0;right:0;bottom:0;height:64px;background:linear-gradient(rgba(255,255,255,0),var(--surface));pointer-events:none;}}
.ask-ex-toggle{{margin:10px 0 4px;align-self:flex-start;}}
.ask-ex-toggle[hidden]{{display:none;}}
.ask-example-settings{{font-size:12px;color:var(--muted);margin:0 0 10px;}}
.ask-example-label{{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);background:var(--surface-2);border-radius:999px;padding:3px 10px;margin-bottom:12px;}}

/* Scoped scale-down for the example inside the intro's right column only—
   .ask-q-bubble/.ask-answer are shared with the real, live-rendered
   question/answer thread below, so these overrides must not leak there. */
.fpa-intro-area-example .ask-example{{margin:0;padding:16px 18px;}}
.fpa-intro-area-example .ask-example-label{{font-size:10px;padding:2px 8px;margin-bottom:8px;}}
.fpa-intro-area-example .ask-q-bubble{{font-size:13px;padding:10px 14px;}}
.fpa-intro-area-example .ask-answer{{padding:14px 16px;font-size:13.5px;line-height:1.6;}}
.fpa-intro-area-example .ask-answer p{{margin:0 0 10px;}}
.fpa-intro-area-example .ask-src-list{{margin-top:10px;padding-top:10px;}}

.ask-section{{margin:20px 0;}}
.ask-section-label{{font-size:11.5px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.1em;margin-bottom:12px;}}

.ask-tags{{display:flex;flex-wrap:wrap;gap:8px;}}
.ask-tag{{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:6px;font:600 13px var(--font-body);
  border:1px solid var(--line-strong);background:var(--surface);color:var(--ink-soft);cursor:pointer;}}
.ask-tag svg{{opacity:0;flex-shrink:0;}}
.ask-tag.active{{background:var(--seafoam);border-color:var(--seafoam);color:var(--navy-deep);}}
.ask-tag.active svg{{opacity:1;}}

/* Depth and Sources: two dropdown buttons in one row; the open panel sits in
   page flow directly under that row at the row's full width, so it can never
   cover the question box or the Ask button and can't pass its container's
   edge. Panels hold the same .ask-tag buttons as before (single-select for
   Depth, multi-select for Sources), restyled as list rows. The follow-up
   bubble holds a clone of this whole block. */
.ask-dd-row{{display:flex;align-items:flex-start;gap:8px;}}
.ask-dd-btn{{flex:1 1 0;min-width:0;display:flex;align-items:center;gap:6px;min-height:44px;padding:0 12px;border:1px solid var(--line-strong);border-radius:10px;background:var(--surface);font:inherit;font-size:14px;color:var(--ink-soft);cursor:pointer;text-align:left;}}
.ask-dd-btn[aria-expanded="true"]{{border-color:var(--navy);}}
.ask-dd-k{{flex-shrink:0;}}
.ask-dd-v{{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:600;color:var(--navy);}}
.ask-dd-caret{{flex-shrink:0;color:var(--muted);}}
.ask-dd-panel{{margin-top:8px;border:1px solid var(--line);border-radius:10px;background:#fff;padding:6px;}}
.ask-dd-panel[hidden]{{display:none;}}
.ask-dd-panel .ask-tags{{flex-direction:column;flex-wrap:nowrap;gap:2px;}}
.ask-dd-panel .ask-tag{{width:100%;border-color:transparent;background:transparent;border-radius:8px;min-height:40px;padding:8px 10px;font-weight:500;color:var(--ink);}}
.ask-dd-panel .ask-tag.active{{background:var(--seafoam);border-color:var(--seafoam);color:var(--navy-deep);font-weight:600;}}
.ask-dd-note{{margin:6px 10px 4px;font-size:12.5px;}}
/* Each panel is as wide as the control that opened it and starts at that control's
   left edge (it sits inside the control's own column). The bubble's side-by-side
   controls get narrow on a phone, so there a panel never goes below 220px; the
   right-hand (Sources) panel then lines up with its control's right edge instead,
   so it can't pass the bubble. */
.fu .ask-dd-panel{{width:max(100%,220px);box-sizing:border-box;}}
.fu .ask-dd-col:last-child .ask-dd-panel{{margin-left:min(0px,calc(100% - 220px));}}

.ask-pq-row{{border:1px solid var(--line);border-radius:8px;background:var(--surface);margin-bottom:8px;}}
.ask-pq-row[open]{{border-color:var(--navy);}}
.ask-pq-sum{{display:flex;flex-wrap:wrap;align-items:flex-start;gap:4px 10px;padding:11px 14px;cursor:pointer;list-style:none;min-height:44px;box-sizing:border-box;}}
.ask-pq-sum::-webkit-details-marker{{display:none;}}
@media(hover:hover){{.ask-pq-sum:hover{{background:var(--accent-light);border-radius:8px;}}}}
.ask-pq-rc{{font-size:12px;color:var(--navy);transition:transform .12s;flex-shrink:0;}}
.ask-pq-row[open]>.ask-pq-sum .ask-pq-rc{{transform:rotate(90deg);}}
.ask-pq-q{{flex:1 1 0;min-width:0;font-weight:600;font-size:13.5px;color:var(--navy);
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;}}
.ask-pq-row[open] .ask-pq-q{{display:block;overflow:visible;}}
.ask-pq-meta{{flex:0 0 calc(100% - 22px);order:3;margin-left:22px;display:flex;align-items:baseline;gap:2px 10px;font-size:12px;color:var(--muted);}}
.ask-pq-ml{{display:flex;flex-wrap:wrap;gap:2px 10px;align-items:center;justify-content:flex-end;flex:1 1 auto;min-width:0;}}
.ask-pq-seg{{white-space:nowrap;}}
{_ASK_CHIP_CSS}
@media(min-width:700px){{.ask-pq-meta{{flex:0 1 auto;order:0;margin-left:auto;max-width:50%;}}.ask-pq-ml{{flex:0 1 auto;justify-content:flex-end;}}}}
.ask-pq-body{{padding:2px 16px 14px 32px;}}
.ask-pq-heading{{margin:0 0 8px;font:600 12px var(--font-body);letter-spacing:.08em;text-transform:uppercase;color:var(--muted);}}
.ask-recent-item{{display:flex;flex-direction:column;gap:6px;width:100%;text-align:left;box-sizing:border-box;
  font:inherit;padding:11px 14px;border-radius:8px;border:1px solid var(--line);background:var(--surface);cursor:pointer;
  margin-bottom:8px;transition:border-color .12s ease;}}
.ask-recent-foot{{display:flex;justify-content:space-between;align-items:center;gap:12px;}}
.ask-pq-foot,.fu-foot{{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:12px;}}
.fu-foot{{margin-top:8px;flex-wrap:wrap;}}
.fu-status{{flex:1 1 100%;}}
.fu-status:empty{{display:none;}}
.ask-done-note{{font-size:13.5px;color:var(--muted);margin:0 0 10px;}}
{_ASK_CTL_CSS}
@media(hover:hover){{.ask-recent-item:hover{{border-color:var(--navy);}}}}
.ask-recent-q{{font-weight:600;font-size:13.5px;color:var(--navy);overflow:hidden;text-overflow:ellipsis;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;}}
.ask-recent-meta{{font-size:12px;color:var(--muted);white-space:nowrap;flex-shrink:0;}}
.ask-recent-meta .ask-chip{{vertical-align:middle;}}


.ask-answer{{background:#fff;border:1px solid var(--line);border-radius:14px 14px 14px 2px;max-width:88%;padding:20px 24px;font-size:15px;line-height:1.7;}}
/* Follow-up bubble: lives under the latest reply, sticky to the viewport bottom
   while that reply is long, and absent until a conversation exists. Typing in it
   collapses the depth/sources row to one summary line (the phone keyboard
   leaves little height). Its chips are clones of the top controls, kept in step
   by syncChips(); the top controls stay the single source of truth. */
.fu{{position:sticky;bottom:8px;z-index:20;margin:16px 0 8px;max-width:88%;background:#fff;border:1px solid var(--line);border-radius:16px;padding:10px 12px;box-shadow:0 -4px 24px rgba(11,31,77,.14);}}
/* The limit message is not worth floating over the reply it follows. */
.fu.fu-limited{{position:static;box-shadow:none;}}
.ask-sim{{background:#fff;border:1px solid var(--line);border-radius:12px;padding:14px;margin-top:10px;}}
.ask-sim h3{{font-size:15px;margin:0 0 4px;color:var(--navy);}}
.ask-sim-sub{{font-size:13px;color:var(--muted);margin:0 0 10px;line-height:1.45;}}
.ask-sim-item{{border:1px solid var(--line);border-radius:10px;margin-bottom:8px;background:#fff;}}
.ask-sim-item>summary{{list-style:none;cursor:pointer;padding:10px 12px;display:flex;flex-wrap:wrap;gap:4px 10px;align-items:baseline;}}
.ask-sim-item>summary::-webkit-details-marker{{display:none;}}
.ask-sim-q{{flex:1 1 220px;min-width:0;font-weight:600;color:var(--navy);font-size:14.5px;line-height:1.4;overflow-wrap:anywhere;}}
.ask-sim-meta{{display:flex;flex-wrap:wrap;gap:4px 10px;font-size:12.5px;color:var(--muted);}}
.ask-sim-body{{padding:0 12px 12px;}}
.ask-sim-foot{{display:flex;gap:8px;margin-top:10px;}}
.ask-priv-opt{{display:flex;align-items:center;gap:10px;min-height:44px;font-size:14px;color:var(--ink);cursor:pointer;margin-top:6px;}}
.ask-priv-opt input{{width:20px;height:20px;flex:none;margin:0;}}
.ask-priv-note{{margin:0 0 0 30px;font-size:13px;line-height:1.5;color:var(--muted);}}
.ask-priv-note a{{color:var(--muted);}}
.ask-q-label{{display:block;font-size:13px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin:12px 0 8px;}}
.fu-label{{font-size:11px;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:0 0 6px;}}
.fu-limit{{font-size:13.5px;color:var(--muted);margin:0 0 10px;}}
.fu-row{{display:flex;gap:8px;align-items:flex-end;}}
.fu textarea{{flex:1 1 0;min-width:0;min-height:44px;height:44px;max-height:120px;resize:none;border:1px solid var(--line);border-radius:12px;padding:12px 14px;font:inherit;font-size:16px;line-height:1.35;background:var(--bg);box-sizing:border-box;}}
/* Send: a filled navy circle, white up arrow. 44px hit area, 36px visible. */
.fu-send{{flex:0 0 44px;width:44px;height:44px;padding:0;border:0;background:transparent;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;}}
.fu-send .fu-send-dot{{width:36px;height:36px;border-radius:50%;background:var(--navy);display:inline-flex;align-items:center;justify-content:center;}}
.fu-send svg{{width:18px;height:18px;stroke:#fff;fill:none;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round;}}
.fu-send:disabled{{cursor:not-allowed;}}
.fu-send:disabled .fu-send-dot{{background:var(--line);}}
.fu-send:focus-visible{{outline:2px solid var(--navy);outline-offset:2px;}}
.ask-turn-row{{display:flex;align-items:baseline;gap:10px;width:100%;text-align:left;font:inherit;padding:11px 14px;min-height:44px;box-sizing:border-box;border-radius:8px;border:1px solid var(--line);background:var(--surface);cursor:pointer;}}
@media(hover:hover){{.ask-turn-row:hover{{border-color:var(--navy);}}}}
.ask-turn-row .ask-pq-rc{{font-size:12px;color:var(--navy);}}
.ask-turn-row[aria-expanded="true"] .ask-pq-rc{{transform:rotate(90deg);}}
.ask-turn-rq{{font-weight:600;font-size:13.5px;color:var(--navy);min-width:0;flex:1;}}
.ask-turn.has-row>.ask-q-bubble{{display:none;}}
.ask-turn.has-row:not(.open)>.ask-answer{{display:none;}}
.ask-recent-item.recent-hl{{border-color:var(--navy);box-shadow:0 0 0 2px var(--accent-light);}}
.fu-meta{{display:flex;flex-direction:column;gap:8px;margin-top:8px;font-size:12px;color:var(--muted);}}
.fu-meta .ask-dd-btn{{min-height:40px;font-size:13px;}}
.fu-sum{{display:none;font-size:12.5px;color:var(--muted);margin-top:6px;min-height:44px;align-items:center;justify-content:space-between;gap:10px;box-sizing:border-box;}}
/* Compact while typing, driven by a class rather than :focus. Tapping the Ask
   follow-up button blurs the textarea; if blur re-expanded the controls, the
   bubble (sticky to the bottom) would grow upward and move the button out from
   under the finger before the tap completed. The class is set on focus and
   cleared only by a tap outside the bubble or on the summary line, so a tap
   inside the bubble never changes its height. */
.fu.fu-compact .fu-meta{{display:none;}}
.fu.fu-compact .fu-sum{{display:flex;}}
.fu-sum{{cursor:pointer;}}
@media(max-width:640px){{.fu{{max-width:100%;padding:8px 10px;}} .fu-meta{{font-size:11.5px;}}}}
.ask-answer p{{margin:0 0 14px;}}
.ask-answer h3,.ask-answer h4,.ask-answer h5,.ask-answer h6{{font-family:var(--font-head);color:var(--navy);font-weight:600;margin:18px 0 8px;letter-spacing:-0.01em;}}
.ask-answer h3:first-child,.ask-answer h4:first-child{{margin-top:0;}}
.ask-answer ul,.ask-answer ol{{margin:0 0 14px;padding-left:22px;}}
.ask-answer li{{margin-bottom:5px;}}
.ask-answer code{{background:var(--surface-2);border-radius:4px;padding:1px 6px;font-size:13px;font-family:ui-monospace,monospace;}}
.ask-answer a{{color:var(--accent);}}
.ask-answer sup.cite{{line-height:0;}}
.ask-answer sup.cite a{{color:var(--navy);font-size:11px;font-weight:600;text-decoration:none;padding:0 1px;}}
.ask-answer sup.cite a:hover{{color:var(--accent);}}
.ask-q-bubble{{background:var(--navy);color:#fff;border-radius:14px 14px 2px 14px;padding:12px 18px;font-size:14px;font-weight:500;margin:0 0 8px auto;max-width:80%;width:fit-content;}}
.ask-src-list{{margin:16px 0 0;padding-top:14px;border-top:1px solid var(--line);list-style:none;padding-left:0;display:flex;flex-wrap:wrap;gap:6px;}}
.ask-src-list li{{font-size:12px;min-width:0;max-width:100%;}}
.ask-src-list a, .ask-src-list span.ask-src-static{{display:inline-flex;align-items:flex-start;gap:5px;max-width:100%;background:var(--seafoam-wash);color:var(--navy);border-radius:6px;padding:4px 10px;font-weight:600;text-decoration:none;}}
@media(hover:hover){{.ask-src-list a:hover{{background:var(--seafoam);text-decoration:none;}}}}
.ask-src-own{{margin-left:4px;font-size:11px;color:var(--muted);font-weight:500;}}
.ask-src-open{{margin-left:4px;font-size:11px;font-weight:600;color:var(--ink-soft);background:var(--line);border-radius:999px;padding:1px 7px;white-space:nowrap;}}
.ask-src-caption{{margin:6px 0 0;font-size:11px;color:var(--muted);}}

.ask-loading{{display:flex;align-items:center;gap:10px;padding:2px 0;}}
.ask-loading .dots{{display:flex;gap:5px;}}
.ask-loading .dots span{{width:7px;height:7px;border-radius:50%;background:var(--muted);opacity:.3;animation:ask-dot-pulse 1.1s ease-in-out infinite;}}
.ask-loading .dots span:nth-child(2){{animation-delay:.15s;}}
.ask-loading .dots span:nth-child(3){{animation-delay:.3s;}}
@keyframes ask-dot-pulse{{0%,80%,100%{{opacity:.3;transform:scale(.85);}}40%{{opacity:1;transform:scale(1);}}}}
.ask-loading-label{{font-size:13px;color:var(--muted);}}

.ask-fb{{margin-top:14px;padding-top:12px;border-top:1px solid var(--line);display:flex;align-items:center;gap:8px;flex-wrap:wrap;}}
.ask-fb-btn{{display:inline-flex;align-items:center;gap:5px;padding:5px 12px;border-radius:999px;border:1px solid var(--line-strong);
  background:var(--surface);color:var(--muted);font:600 12px var(--font-body);cursor:pointer;}}
.ask-fb-btn.sel-pos{{background:var(--navy);border-color:var(--navy);color:#fff;}}
.ask-fb-btn.sel-neg{{background:var(--coral-wash);border-color:var(--coral-deep);color:var(--coral-deep);}}
.ask-fb-saved{{font-size:11.5px;color:var(--muted);opacity:0;transition:opacity .25s ease;}}
.ask-fb-comment{{display:none;flex-basis:100%;gap:8px;align-items:center;}}
.ask-fb-comment input{{flex:1;min-width:0;padding:7px 12px;border:1px solid var(--line);border-radius:8px;font:inherit;font-size:13px;background:var(--bg);}}
.ask-fb-send{{padding:7px 14px;border-radius:8px;border:1px solid var(--line-strong);background:var(--surface);font:600 12px var(--font-body);color:var(--ink-soft);cursor:pointer;}}
</style>

<script>
var COST = {cost_js};      // per-depth model estimate, admin only (empty otherwise)
var EXA_UNIT = {exa_js};   // one Exa search per turn when Web is on and Exa is the provider
var selectedTier = "{default_effort}";

// Single-select: clearing every tier before setting this one is what makes
// Depth radio behavior rather than the multi-select toggle Sources uses,
// even though both share the .ask-tag component.
function selectTier(el) {{
  selectedTier = el.getAttribute('data-tier');
  // Match by value, not by the clicked node: the follow-up bubble carries
  // clones of these chips, and either copy can be the one tapped.
  document.querySelectorAll('.ask-tag[data-tier]').forEach(function(t) {{
    var on = t.getAttribute('data-tier') === selectedTier;
    t.classList.toggle('active', on);
    t.setAttribute('aria-checked', on ? 'true' : 'false');
  }});
  updateEstimate();
  fuSummary();
  closeDds();
}}

function toggleSource(el) {{
  var key = el.getAttribute('data-source');
  var on = !el.classList.contains('active');
  document.querySelectorAll('.ask-tag[data-source="' + key + '"]').forEach(function(t) {{
    t.classList.toggle('active', on);
    t.setAttribute('aria-pressed', on ? 'true' : 'false');
  }});
  updateEstimate();
  fuSummary();
}}

// Estimate for a depth with the current sources: the model figure from the
// server's table, plus one Exa search when Web is on. Null when the reader
// is not an admin (the table is empty then).
function tierCost(tier) {{
  var c = COST[tier];
  if (c == null) return null;
  // One Exa search per turn when either web-capable source is on (Current feed
  // searches the trusted sites, Open web searches everything; both is still one).
  var webOn = !!document.querySelector('.fpa-intro-area-controls .ask-tag[data-source="feed"].active, .fpa-intro-area-controls .ask-tag[data-source="open_web"].active');
  return c + (webOn ? EXA_UNIT : 0);
}}
function costText(tier) {{
  var c = tierCost(tier);
  return c == null ? '' : '($' + c.toFixed(3) + ')';
}}
function updateEstimate() {{
  document.querySelectorAll('.ask-tag[data-tier]').forEach(function(t) {{
    var n = t.querySelector('.ask-tag-cost');
    if (n) n.textContent = costText(t.getAttribute('data-tier'));
  }});
  ddLabels();
}}

// The top controls are the single source of truth for depth and sources.
function activeSources() {{
  return Array.prototype.map.call(
    // Scoped to the top controls and to [data-source]: Depth's buttons share the
    // .ask-tag component and its .active state, and the follow-up bubble holds
    // clones of both groups, so an unscoped '.ask-tag.active' would sweep the
    // depth tier and the duplicates into the sources list.
    document.querySelectorAll('.fpa-intro-area-controls .ask-tag[data-source].active'),
    function(t) {{ return t.getAttribute('data-source'); }}
  );
}}
function chipText(sel) {{
  return Array.prototype.map.call(document.querySelectorAll(sel), function(t) {{
    var n = t.querySelector('.ask-tag-name');
    return (n || t).textContent.trim();
  }});
}}
function fuSummary() {{
  var srcs = chipText('.fpa-intro-area-controls .ask-tag[data-source].active').join(', ') || 'No sources';
  var tier = chipText('.fpa-intro-area-controls .ask-tag[data-tier].active')[0] || '';
  var cost = costText(selectedTier);
  var sum = document.querySelector('.fu-sum');
  if (sum) sum.innerHTML = '<span class="fu-sum-t"></span><span aria-hidden="true">\u25be</span>';
  if (sum) sum.firstChild.textContent = [(tier + ' ' + cost).trim(), srcs].filter(Boolean).join(' \u00b7 ');
  ddLabels();
}}

// Dropdown buttons: the current value shows on the closed button, so state is never hidden.
function ddLabels() {{
  var tier = chipText('.fpa-intro-area-controls .ask-tag[data-tier].active')[0] || '';
  var srcs = chipText('.fpa-intro-area-controls .ask-tag[data-source].active');
  var sv = srcs.length === 0 ? 'None' : srcs.length + ' of ' + document.querySelectorAll('.fpa-intro-area-controls .ask-tag[data-source]').length;
  document.querySelectorAll('.ask-dd-btn[data-dd="depth"] .ask-dd-v').forEach(function(n) {{ n.textContent = (tier + ' ' + costText(selectedTier)).trim(); }});
  document.querySelectorAll('.ask-dd-btn[data-dd="sources"] .ask-dd-v').forEach(function(n) {{ n.textContent = sv; }});
}}
function closeDds() {{
  document.querySelectorAll('.ask-dd-btn').forEach(function(b) {{ b.setAttribute('aria-expanded', 'false'); }});
  document.querySelectorAll('.ask-dd-panel').forEach(function(p) {{ p.hidden = true; }});
}}
function toggleDd(btn) {{
  var open = btn.getAttribute('aria-expanded') !== 'true';
  closeDds();
  if (!open) return;
  var dd = btn.closest('.ask-dd');
  btn.setAttribute('aria-expanded', 'true');
  var panel = dd.querySelector('.ask-dd-panel[data-dd="' + btn.getAttribute('data-dd') + '"]');
  if (panel) panel.hidden = false;
}}
document.addEventListener('click', function(e) {{
  if (!e.target.closest('.ask-dd')) closeDds();
}});
// A tap outside the follow-up bubble brings its controls back after typing.
document.addEventListener('pointerdown', function(e) {{
  var fu = document.getElementById('fu');
  if (fu && !e.target.closest('#fu')) fu.classList.remove('fu-compact');
}});
document.addEventListener('keydown', function(e) {{
  if (e.key === 'Escape') closeDds();
}});

// The top send button: disabled while the box is empty or a question is running.
var topBusy = false;
function topSync() {{
  var b = document.getElementById('ask-btn'), q = document.getElementById('ask-q');
  if (b && q) b.disabled = topBusy || !q.value.trim();
}}
document.addEventListener('DOMContentLoaded', function() {{
  var q = document.getElementById('ask-q');
  if (q) q.addEventListener('input', function() {{ topSync(); if (simShownFor && q.value.trim() !== simShownFor) simHide(); }});
  topSync();
}});

var asked = false;
var convoGen = 0;       // bumped by Done and a new thread; an answer from an older generation is not drawn
var convoPrivate = false;   // the open conversation's privacy (set from the server)
var PRIVATE_CHIP_HTML = {_ASK_PRIVATE_CHIP_JS};   // built by the one chip function, never by hand in JS
var convoId = null;    // the server-side conversation to continue; set from the
                       // first response (or a resumed conversation). The server
                       // rebuilds history from its own records — no turn text
                       // is ever sent back from the client.
// Citations for the turn currently being rendered: [{{n, title, url, type}}].
// Set from each response just before mdToHtml runs, so markers are per-turn
// scoped — each turn's [n] links resolve against that turn's own list.
var CITES = [];

function updateUsage(usage) {{
  if (!usage) return;
  var el = document.getElementById('ask-usage-text');
  if (el) el.textContent = '$' + usage.spent.toFixed(2) + ' of $' + usage.cap.toFixed(2) + ' used this month';
}}

function escapeHtml(s) {{
  return (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}}

// Small hand-rolled markdown renderer — covers what Claude actually produces in
// an answer (headers, bold/italic, inline code, links, bullet/numbered lists,
// paragraphs). Not a general-purpose markdown engine; deliberately no external
// library, matching the rest of the site's zero-dependency inline-JS pattern.
function mdInline(s) {{
  s = escapeHtml(s);
  // Model-text links are never turned into anchors: only a resolved [n] marker
  // (below) links out, to a URL from the turn's own citation snapshot.
  s = s.replace(/`([^`]+)`/g, '<code>$1</code>');
  s = s.replace(/\\*\\*([^*]+)\\*\\*/g, '<strong>$1</strong>');
  s = s.replace(/__([^_]+)__/g, '<strong>$1</strong>');
  s = s.replace(/(^|[^*])\\*([^*\\n]+)\\*(?!\\*)/g, '$1<em>$2</em>');
  s = s.replace(/(^|[^_])_([^_\\n]+)_(?!_)/g, '$1<em>$2</em>');
  // Last, so the injected HTML is never re-processed: bare [n] citation
  // markers become superscript links. Only numbers within the current
  // turn's citation list are linkified — a literal [2026] in prose stays text.
  s = s.replace(/\\[(\\d{{1,2}})\\](?!\\()/g, function(m, num) {{
    var i = parseInt(num, 10);
    if (CITES && i >= 1 && i <= CITES.length) {{
      return '<sup class="cite"><a href="' + encodeURI(CITES[i-1].url) + '" target="_blank" rel="noopener" title="' + escapeHtml(CITES[i-1].title) + '">[' + i + ']</a></sup>';
    }}
    return m;
  }});
  return s;
}}
function mdToHtml(raw) {{
  var lines = (raw || '').split('\\n');
  var html = [], para = [], listType = null;
  function closeList() {{ if (listType) {{ html.push('</' + listType + '>'); listType = null; }} }}
  function flushPara() {{ if (para.length) {{ html.push('<p>' + para.join('<br>') + '</p>'); para = []; }} }}
  lines.forEach(function(line) {{
    var t = line.trim();
    var h = t.match(/^(#{{1,4}})\\s+(.*)$/);
    var ol = t.match(/^\\d+\\.\\s+(.*)$/);
    var ul = t.match(/^[-*]\\s+(.*)$/);
    var hr = /^(?:-{{3,}}|\\*{{3,}}|_{{3,}})$/.test(t);
    if (hr) {{
      flushPara(); closeList();
      html.push('<hr>');
    }} else if (h) {{
      flushPara(); closeList();
      var lvl = Math.min(h[1].length + 2, 6);
      html.push('<h' + lvl + '>' + mdInline(h[2]) + '</h' + lvl + '>');
    }} else if (ol) {{
      flushPara();
      if (listType !== 'ol') {{ closeList(); html.push('<ol>'); listType = 'ol'; }}
      html.push('<li>' + mdInline(ol[1]) + '</li>');
    }} else if (ul) {{
      flushPara();
      if (listType !== 'ul') {{ closeList(); html.push('<ul>'); listType = 'ul'; }}
      html.push('<li>' + mdInline(ul[1]) + '</li>');
    }} else if (t === '') {{
      flushPara(); closeList();
    }} else {{
      closeList();
      para.push(mdInline(t));
    }}
  }});
  flushPara(); closeList();
  return html.join('');
}}
// Below-answer list: only the sources the answer actually cited, numbered to
// match the inline [n] markers. Zero citations -> no list (silently allowed).
// A "Web search powered by Exa" caption follows the list, but only when this
// turn's web tier was actually handled by Exa (c.provider === 'exa')—
// gating on citation type alone isn't enough since Phase 7: the native
// web_search_20250305 fallback also produces type "web" citations when Exa
// is toggled off or EXA_API_KEY is missing, and those get no caption at all
// (a normal citation, just no "Powered by Exa" line).
// Published-content ingestion (2026-09): a citation carrying own_content
// (Brian's own mirrored/matched writing — see
// linklib.original_content_sync) gets a small "(own writing)" label — a
// citation-list label only, never an inline prose mention (flagged as a
// real voice-integrity risk during design and deliberately left out; see
// CLAUDE.md's Published-Content Ingestion entry).
function srcListHtml(d) {{
  var icons = {{library: '&#128218;', feed: '&#128240;', web: '&#127760;'}};
  var cites = d.citations || [];
  var items = cites.map(function(c) {{
    var ownTag = c.own_content ? ' <span class="ask-src-own">(own writing)</span>' : '';
    // Open web (2026-10): only an explicit trusted === false is tagged; a legacy
    // citation has no key and every legacy web source was a trusted one.
    if (c.type === 'web' && c.trusted === false) ownTag += ' <span class="ask-src-open">Open web</span>';
    // The emoji rides inside the pill so a long title can never drop below it.
    return '<li><a href="' + encodeURI(c.url) + '" target="_blank" rel="noopener">' + (icons[c.type] ? '<span aria-hidden="true">' + icons[c.type] + '</span>' : '') + '<span>[' + c.n + '] ' + escapeHtml(c.title) + '</span></a>' + ownTag + '</li>';
  }});
  // Suggest-content nudge: always rendered, even with zero citations — that's
  // the case where Buddy came up empty-handed, exactly the moment worth
  // pointing someone at /library/submit. Reuses the existing muted
  // .ask-src-caption treatment rather than a new component.
  var suggestLine = '<div class="ask-src-caption">Know a source that should be here? '
    + '<a href="/library/submit">Suggest it for the archive &rarr;</a></div>';
  if (!items.length) return suggestLine;
  var exaCaption = cites.some(function(c) {{ return c.type === 'web' && c.provider === 'exa'; }})
    ? '<div class="ask-src-caption">Web search powered by Exa</div>' : '';
  return '<ul class="ask-src-list">' + items.join('') + '</ul>' + exaCaption + suggestLine;
}}
// Per-answer feedback: one tap records; tapping another option changes the
// rating (the server upserts one row per turn per user). A negative rating
// reveals an optional one-line "what was off?" field. Only rendered when the
// turn was recorded server-side (d.turn_id present).
var FB_OPTIONS = [
  ['helpful', '&#128077; Helpful'],
  ['inaccurate', '&#9888;&#65039; Inaccurate'],
  ['not_helpful', '&#128078; Not helpful']
];
function fbRowHtml(turnId) {{
  var btns = FB_OPTIONS.map(function(o) {{
    return '<button type="button" class="ask-fb-btn" data-rating="' + o[0] + '" onclick="rateTurn(this)">' + o[1] + '</button>';
  }}).join('');
  return '<div class="ask-fb" data-turn-id="' + turnId + '">' + btns +
         '<span class="ask-fb-saved">Saved</span>' +
         '<div class="ask-fb-comment"><input type="text" maxlength="500" placeholder="What was off? (optional)">' +
         '<button type="button" class="ask-fb-send" onclick="sendFbComment(this)">Save</button></div></div>';
}}
function rateTurn(el) {{
  var row = el.closest('.ask-fb');
  var rating = el.getAttribute('data-rating');
  row.querySelectorAll('.ask-fb-btn').forEach(function(b) {{ b.classList.remove('sel-pos', 'sel-neg'); }});
  el.classList.add(rating === 'helpful' ? 'sel-pos' : 'sel-neg');
  var commentBox = row.querySelector('.ask-fb-comment');
  commentBox.style.display = rating === 'helpful' ? 'none' : 'flex';
  if (rating === 'helpful') commentBox.querySelector('input').value = '';
  postFeedback(row);
}}
async function postFeedback(row) {{
  var sel = row.querySelector('.ask-fb-btn.sel-pos, .ask-fb-btn.sel-neg');
  if (!sel) return;
  try {{
    var resp = await fetch('/ask/feedback', {{
      method: 'POST',
      headers: {{'Content-Type': 'application/json'}},
      body: JSON.stringify({{
        question_id: parseInt(row.getAttribute('data-turn-id'), 10),
        rating: sel.getAttribute('data-rating'),
        comment: row.querySelector('.ask-fb-comment input').value.trim()
      }})
    }});
    if (resp.ok) {{
      var saved = row.querySelector('.ask-fb-saved');
      saved.style.opacity = '1';
      setTimeout(function() {{ saved.style.opacity = '0'; }}, 1200);
    }}
  }} catch(e) {{}}
}}
function sendFbComment(el) {{ postFeedback(el.closest('.ask-fb')); }}
document.addEventListener('keydown', function(e) {{
  if (e.key === 'Enter' && e.target && e.target.matches && e.target.matches('.ask-fb-comment input')) {{
    e.preventDefault();
    sendFbComment(e.target);
  }}
}});
// The conversation id lives in the URL (?c=...) so a reload reopens the same
// conversation through the resume path. Nothing else is stored client-side.
function setConvoUrl(id) {{
  try {{
    var u = new URL(location.href);
    if (id) u.searchParams.set('c', id); else u.searchParams.delete('c');
    u.searchParams.delete('resume');
    history.replaceState(null, '', u.pathname + u.search + u.hash);
  }} catch(e) {{}}
}}
function resetConvo() {{
  convoGen++; asked = false; convoId = null; convoPrivate = false; setConvoUrl(null);
  document.getElementById('ask-thread').innerHTML = '';
  var rec = document.getElementById('ask-recent');
  if (rec.innerHTML) rec.style.display = 'block';
  var q = document.getElementById('ask-q'); topSync();
  q.focus();
  q.scrollIntoView({{behavior:'smooth', block:'center'}});
}}

// Earlier turns fold to one-line rows (chevron, tap to open). Nothing is
// deleted; the newest turn stays open. A turn gets its row once.
function collapseTurn(turn) {{
  if (!turn || turn.id === 'fu' || turn.classList.contains('has-row')) return;
  var b = turn.querySelector('.ask-q-bubble');
  if (!b) return;
  turn.classList.add('ask-turn', 'has-row');
  var row = document.createElement('button');
  row.type = 'button'; row.className = 'ask-turn-row'; row.setAttribute('aria-expanded', 'false');
  row.innerHTML = '<span class="ask-pq-rc" aria-hidden="true">&#9656;</span><span class="ask-turn-rq"></span>';
  row.querySelector('.ask-turn-rq').textContent = b.textContent;
  row.addEventListener('click', function() {{
    var o = turn.classList.toggle('open');
    row.setAttribute('aria-expanded', o ? 'true' : 'false');
  }});
  turn.insertBefore(row, turn.firstChild);
}}
function collapseEarlierTurns() {{
  var kids = Array.prototype.filter.call(document.getElementById('ask-thread').children, function(k) {{ return k.id !== 'fu'; }});
  for (var i = 0; i < kids.length - 1; i++) collapseTurn(kids[i]);
}}
function lastTurnEl() {{
  var kids = document.getElementById('ask-thread').children;
  for (var i = kids.length - 1; i >= 0; i--) if (kids[i].id !== 'fu') return kids[i];
  return null;
}}
// Follow-up bubble: rebuilt under the latest turn after every render, and
// removed whenever there is no conversation. state: 'ready' | 'busy' | 'limit' | 'none'.
// Nothing here is persisted or sent: the server rebuilds history itself.
function fuRender(state) {{
  var old = document.getElementById('fu');
  if (old) old.remove();
  // No conversation yet means no bubble, except to show a cap on the first turn.
  if (state === 'none' || (!asked && state !== 'limit')) return;
  var thread = document.getElementById('ask-thread');
  var limited = state === 'limit', busy = state === 'busy';
  var f = document.createElement('div');
  f.id = 'fu'; f.className = limited ? 'fu fu-limited' : 'fu';
  f.innerHTML = '<div class="fu-label">Follow-up</div>' +
    (limited ? '<p class="fu-limit">You&rsquo;ve reached the limit for this conversation. ' +
               '<a href="#" onclick="resetConvo();return false;" style="color:var(--navy);font-weight:600;">Start a new conversation</a>.</p>' : '') +
    '<div class="fu-row"><textarea id="fu-q" rows="1" placeholder="Ask a follow-up…"' + (limited ? ' disabled' : '') + '></textarea>' +
    '<button type="button" class="fu-send" id="fu-btn" onclick="doAsk(true)" aria-label="Ask follow-up" title="Ask follow-up"' + ((limited || busy) ? ' disabled' : '') + '>' +
    '<span class="fu-send-dot"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 19V5M5 12l7-7 7 7"/></svg></span></button></div>';
  if (!limited) {{
    var meta = document.createElement('div');
    meta.className = 'fu-meta';
    var top = document.getElementById('ask-dd-top');
    if (top) {{
      // A clone of the top block: same buttons and panels, panels in the
      // bubble's own flow at bubble width. The top block stays the source of truth.
      var dd = top.cloneNode(true);
      dd.removeAttribute('id');
      dd.querySelectorAll('.ask-dd-btn').forEach(function(x) {{ x.setAttribute('aria-expanded', 'false'); }});
      dd.querySelectorAll('.ask-dd-panel').forEach(function(x) {{ x.hidden = true; }});
      meta.appendChild(dd);
    }}
    f.appendChild(meta);
    var sum = document.createElement('div');
    sum.className = 'fu-sum';
    f.appendChild(sum);
    var fq = f.querySelector('#fu-q');
    fq.addEventListener('focus', function() {{ f.classList.add('fu-compact'); closeDds(); }});
    var fb = f.querySelector('#fu-btn');
    function fuSync() {{
      fq.style.height = '44px'; fq.style.height = Math.min(fq.scrollHeight, 120) + 'px';
      if (!busy) fb.disabled = !fq.value.trim();
    }}
    fq.addEventListener('input', fuSync);
    if (!busy) fb.disabled = true;
    sum.addEventListener('click', function() {{ f.classList.remove('fu-compact'); }});
  }}
  // Footer: Done, lower right, in every state (ready, busy, limit).
  var foot = document.createElement('div');
  foot.className = 'fu-foot';
  // Make private / Allow sharing sits left of Done once the conversation has an id.
  foot.innerHTML = (convoId && state !== 'busy'
      ? '<span id="fu-status" class="fu-status">' + (convoPrivate ? PRIVATE_CHIP_HTML : '') + '</span>' +
        '<button type="button" class="ask-ctl ask-ctl-sm ask-ctl-w" id="fu-priv" onclick="togglePrivate()">' +
        (convoPrivate ? 'Allow sharing' : 'Make private') + '</button>' : '') +
    '<button type="button" class="ask-ctl ask-ctl-sm ask-ctl-w" id="fu-done" onclick="doneThread()">Done</button>';
  f.appendChild(foot);
  thread.appendChild(f);
  updateEstimate(); fuSummary();
}}
// Flip the open conversation between private and shared. The server decides
// (own conversations only); the page follows its answer.
async function togglePrivate() {{
  var cid = convoId, btn = document.getElementById('fu-priv');
  if (!cid) return;
  var want = !convoPrivate;
  try {{
    var resp = await fetch('/ask/conversations/' + encodeURIComponent(cid) + '/private', {{
      method: 'POST', headers: {{'Content-Type': 'application/json'}},
      body: JSON.stringify({{ private: want }}) }});
    if (!resp.ok) return;
    convoPrivate = want;
    if (btn) btn.textContent = want ? 'Allow sharing' : 'Make private';
    var st = document.getElementById('fu-status'); if (st) st.innerHTML = want ? PRIVATE_CHIP_HTML : '';
    var items = document.querySelectorAll('#ask-recent .ask-recent-item');
    for (var i = 0; i < items.length; i++)
      if (items[i].getAttribute('data-cid') === cid) items[i].outerHTML = '';
    recentUpsert(cid, !!document.querySelector('#fu.fu-limited'));
  }} catch(e) {{}}
}}
// Done: put the screen back to the clean start. The conversation stays in
// Recent conversations (highlighted for a moment). If a question is still
// loading, it is allowed to finish: the answer is not drawn, it lands in Recent.
function doneThread() {{
  var loading = !!document.querySelector('#ask-thread .ask-loading');
  var cid = convoId;
  convoGen++; asked = false; convoId = null; convoPrivate = false; setConvoUrl(null);
  document.getElementById('ask-thread').innerHTML = '';
  topBusy = false; topSync();
  var rec = document.getElementById('ask-recent');
  if (loading) {{
    if (!rec.querySelector('.ask-section-label'))
      rec.innerHTML = '<div class="ask-section-label">Recent conversations</div>';
    var n = document.createElement('p');
    n.className = 'ask-done-note'; n.id = 'ask-done-note';
    n.textContent = 'Your answer will appear in Recent.';
    rec.querySelector('.ask-section-label').insertAdjacentElement('afterend', n);
  }}
  if (rec.innerHTML) rec.style.display = 'block';
  if (cid) {{
    var items = rec.querySelectorAll('.ask-recent-item');
    for (var i = 0; i < items.length; i++) if (items[i].getAttribute('data-cid') === cid) {{
      (function(el) {{ el.classList.add('recent-hl'); setTimeout(function() {{ el.classList.remove('recent-hl'); }}, 2500); }})(items[i]);
    }}
  }}
  window.scrollTo({{top: 0, behavior: 'smooth'}});
}}

// --- Resume: recent conversations -------------------------------------------
// On load, offer the last few conversations to pick back up. Offered, never
// forced — a fresh question works exactly as before, and the list simply
// hides once a conversation (new or resumed) is on screen.
function relTime(iso) {{
  var then = new Date(iso);
  if (isNaN(then)) return '';
  var mins = Math.max(0, Math.round((Date.now() - then.getTime()) / 60000));
  if (mins < 60) return mins <= 1 ? 'just now' : mins + 'm ago';
  var hrs = Math.round(mins / 60);
  if (hrs < 24) return hrs + 'h ago';
  var days = Math.round(hrs / 24);
  return days === 1 ? 'yesterday' : days + 'd ago';
}}
function recentItemHtml(c) {{
  // The row is a div so a real Resume button can sit inside it; tapping the
  // row does the same thing, the button is the visible, keyboard-reachable one.
  return '<div class="ask-recent-item" data-cid="' + escapeHtml(c.conversation_id) + '" onclick="resumeConvo(this)">' +
         '<span class="ask-recent-q">' + escapeHtml(c.first_question) + '</span>' +
         '<div class="ask-recent-foot"><span class="ask-recent-meta">' + (c.private ? PRIVATE_CHIP_HTML + ' ' : '') + relTime(c.last_at) + ' &middot; ' +
         c.turns + (c.turns === 1 ? ' turn' : ' turns') + (c.capped ? ' &middot; at limit' : '') + '</span>' +
         '<button type="button" class="ask-ctl ask-ctl-sm ask-ctl-w" onclick="event.stopPropagation();resumeConvo(this.closest(\\'.ask-recent-item\\'))">Resume</button></div></div>';
}}
var RECENT_MAX = 5;   // the server's own cap on /ask/conversations
async function loadRecent() {{
  try {{
    var resp = await fetch('/ask/conversations');
    if (!resp.ok) return;
    var d = await resp.json();
    var list = d.conversations || [];
    if (!list.length) return;
    var box = document.getElementById('ask-recent');
    box.innerHTML = '<div class="ask-section-label">Recent conversations</div>' + list.map(recentItemHtml).join('');
    box.style.display = asked ? 'none' : 'block';
    highlightRecent();
  }} catch(e) {{}}
}}
// After an answer, put its conversation at the top of Recent conversations
// from what the page already holds (the /ask response gave the id and the
// limit state; the thread on screen gives the first question and the turn
// count), instead of asking the server again. Visibility is untouched: the
// list stays hidden while a thread is open and Start a new conversation shows it.
function recentUpsert(cid, atLimit) {{
  if (!cid) return;
  var bubbles = document.querySelectorAll('#ask-thread .ask-q-bubble');
  if (!bubbles.length) return;
  var box = document.getElementById('ask-recent');
  if (!box.querySelector('.ask-section-label'))
    box.innerHTML = '<div class="ask-section-label">Recent conversations</div>';
  var items = box.querySelectorAll('.ask-recent-item');
  for (var i = 0; i < items.length; i++)
    if (items[i].getAttribute('data-cid') === cid) items[i].remove();
  var holder = document.createElement('div');
  holder.innerHTML = recentItemHtml({{
    conversation_id: cid, first_question: bubbles[0].textContent,
    turns: bubbles.length, last_at: new Date().toISOString(), capped: !!atLimit,
    private: convoPrivate}});
  box.querySelector('.ask-section-label').insertAdjacentElement('afterend', holder.firstChild);
  var all = box.querySelectorAll('.ask-recent-item');
  for (var j = RECENT_MAX; j < all.length; j++) all[j].remove();
}}
// Pre-select the feedback controls with the turn's stored rating so a
// resumed transcript looks exactly like it did live — and re-rating still
// works (the server upserts one row per turn per user).
function applyFbState(row, fb) {{
  if (!row || !fb) return;
  var btn = row.querySelector('.ask-fb-btn[data-rating="' + fb.rating + '"]');
  if (!btn) return;
  btn.classList.add(fb.rating === 'helpful' ? 'sel-pos' : 'sel-neg');
  if (fb.rating !== 'helpful') {{
    var box = row.querySelector('.ask-fb-comment');
    box.style.display = 'flex';
    box.querySelector('input').value = fb.comment || '';
  }}
}}
function resumeConvo(el) {{ return resumeConvoById(el.getAttribute('data-cid')); }}
async function resumeConvoById(cid) {{
  try {{
    var resp = await fetch('/ask/conversations/' + encodeURIComponent(cid));
    // Someone else's (403) or unknown (404) id: the server decides, the page
    // falls back to the empty state and drops the parameter.
    if (!resp.ok) {{ setConvoUrl(null); return; }}
    var d = await resp.json();
    var thread = document.getElementById('ask-thread');
    thread.innerHTML = '';
    (d.turns || []).forEach(function(t) {{
      // Same per-turn CITES scoping as the live path: each turn's [n]
      // markers resolve against that turn's own persisted citation snapshot.
      CITES = t.citations || [];
      var turn = document.createElement('div');
      turn.style.marginTop = '18px';
      turn.innerHTML = '<div class="ask-q-bubble">' + escapeHtml(t.question) + '</div>' +
                       '<div class="ask-answer">' + mdToHtml(t.answer) + srcListHtml(t) + '</div>';
      var answerEl = turn.querySelector('.ask-answer');
      if (t.turn_id) {{
        answerEl.insertAdjacentHTML('beforeend', fbRowHtml(t.turn_id));
        applyFbState(answerEl.querySelector('.ask-fb'), t.feedback);
      }}
      thread.appendChild(turn);
    }});
    collapseEarlierTurns();
    convoId = d.conversation_id;
    convoPrivate = !!d.private;
    asked = true; setConvoUrl(convoId);
    document.getElementById('ask-recent').style.display = 'none';
    fuRender(d.capped ? 'limit' : 'ready');
    var lastTurn = lastTurnEl();
    if (lastTurn) lastTurn.scrollIntoView({{behavior:'smooth', block:'start'}});
  }} catch(e) {{}}
}}

// Similar questions: before a NEW question runs, a free text check (no model
// call) may show earlier questions that already answer it. "Ask anyway" is
// always there. A second submit cancels a pending check; if the panel is already
// showing for exactly this text, a submit asks. Any failure just asks.
var simCtl = null, simShownFor = '';
function simHide() {{
  var p = document.getElementById('ask-sim'); if (p) {{ p.hidden = true; p.innerHTML = ''; }}
  simShownFor = '';
}}
function simItemHtml(x) {{
  var tags = [];
  if (x.chips_html) tags.push(x.chips_html);
  tags.push('<span>' + escapeHtml(x.date) + '</span>');
  var resume = x.resume_id ? '<div class="ask-sim-foot"><button type="button" class="ask-ctl ask-ctl-sm ask-ctl-w" data-cid="' +
    escapeHtml(x.resume_id) + '" onclick="simHide();resumeConvoById(this.dataset.cid)">Resume</button></div>' : '';
  return '<details class="ask-sim-item"><summary><span class="ask-sim-q">' + escapeHtml(x.question) +
    '</span><span class="ask-sim-meta">' + tags.join('') + '</span></summary><div class="ask-sim-body">' +
    '<div class="ask-hist-answer" style="margin:0;">' + x.answer_html + '</div>' + resume + '</div></details>';
}}
async function simCheck(q) {{
  if (simCtl) simCtl.abort();
  simCtl = new AbortController();
  var mine = simCtl;
  try {{
    var r = await fetch('/ask/similar', {{method:'POST', headers:{{'Content-Type':'application/json'}},
      body: JSON.stringify({{question: q}}), signal: mine.signal}});
    if (!r.ok) return false;
    var d = await r.json();
    if (mine !== simCtl || !d.suggestions || !d.suggestions.length) return false;
    var p = document.getElementById('ask-sim');
    p.innerHTML = '<h3>These questions may already answer yours</h3>' +
      '<p class="ask-sim-sub">Check one before this runs. It uses your depth and sources if you ask anyway.</p>' +
      d.suggestions.map(simItemHtml).join('') +
      '<button type="button" class="btn" id="ask-anyway" onclick="doAsk(false,true)">Ask anyway</button>';
    p.hidden = false; simShownFor = q;
    return true;
  }} catch(e) {{ return false; }}
}}

// followUp=false: the top box, always a NEW question (a fresh conversation).
// followUp=true: the bubble under the latest reply, continuing convoId.
async function doAsk(followUp, skipSimilar) {{
  var qEl = document.getElementById(followUp ? 'fu-q' : 'ask-q');
  if (!qEl) return;
  var q = qEl.value.trim();
  if (!q) {{ qEl.focus(); return; }}

  var effort = selectedTier || 'standard';
  var sources = activeSources();
  if (!sources.length) {{ alert('Select at least one source.'); return; }}

  if (!followUp) {{
    if (!skipSimilar && simShownFor !== q) {{
      var showed = await simCheck(q);
      if (showed) return;
    }}
    if (simCtl) simCtl.abort();
    simHide();
  }}
  var thread = document.getElementById('ask-thread');
  if (!followUp) {{
    // A new question never inherits a conversation: clear the screen and the id
    // before anything is sent (the old one stays in Recent conversations).
    asked = false; convoId = null; setConvoUrl(null);
    thread.innerHTML = '';
  }}
  var topBtn = document.getElementById('ask-btn');
  var myGen = convoGen;
  function stale() {{ return myGen !== convoGen; }}
  var oldNote = document.getElementById('ask-done-note'); if (oldNote) oldNote.remove();
  var turn = document.createElement('div');
  turn.style.marginTop = '18px';
  turn.style.scrollMarginTop = '12px';
  turn.innerHTML = '<div class="ask-q-bubble">' + escapeHtml(q) + '</div>' +
                   '<div class="ask-answer"><div class="ask-loading"><span class="dots"><span></span><span></span><span></span></span>' +
                   '<span class="ask-loading-label">Querying sources&hellip;</span></div></div>';
  var oldBubble = document.getElementById('fu');
  if (oldBubble) oldBubble.remove();
  thread.appendChild(turn);
  if (followUp) collapseEarlierTurns();
  document.getElementById('ask-recent').style.display = 'none';
  var answerEl = turn.querySelector('.ask-answer');

  topBusy = true; topBtn.disabled = true;
  qEl.value = '';
  fuRender('busy');
  turn.scrollIntoView({{behavior:'smooth', block:'nearest'}});

  function done(state) {{
    if (stale()) return;          // Done was tapped while this ran: nothing to redraw
    topBusy = false; topSync();
    fuRender(state);
  }}
  // Done was tapped while this question ran. The server has recorded it; show
  // it in Recent instead of on the screen the reader already cleared.
  function dropLate(recorded) {{
    var n = document.getElementById('ask-done-note');
    if (!recorded) {{ if (n) n.remove(); return; }}
    loadRecent();
  }}
  try {{
    var resp = await fetch('/ask', {{
      method: 'POST',
      headers: {{'Content-Type': 'application/json'}},
      body: JSON.stringify({{ question: q, effort: effort, sources: sources, conversation_id: convoId,
        private: (!followUp && !convoId) ? !!(document.getElementById('ask-private') || {{}}).checked : undefined }})
    }});
    // An edge error page (Cloudflare, Railway) is HTML, so the body may not parse.
    var d = await resp.json().catch(function() {{ return {{}}; }});
    if (stale()) {{ if (d.usage) updateUsage(d.usage); dropLate(resp.ok && !d.capped); return; }}
    if (!resp.ok) {{
      // A 5xx with no JSON detail is the same failure to the reader.
      var edgeFail = resp.status >= 500 && !d.detail;
      answerEl.innerHTML = '<span style="color:var(--alert);">' + escapeHtml(edgeFail ? {json.dumps(_ASK_FAILED_TURN_MESSAGE)} : (d.detail || 'Error')) + '</span>';
      if (d.usage) updateUsage(d.usage);
      // The question goes back in the box so a retry is one tap.
      if (d.failed || edgeFail) {{ qEl.value = q; qEl.dispatchEvent(new Event('input')); }}
      done(asked ? 'ready' : 'none');
      return;
    }}

    CITES = d.citations || [];
    answerEl.innerHTML = mdToHtml(d.answer) + srcListHtml(d);
    if (d.turn_id) answerEl.insertAdjacentHTML('beforeend', fbRowHtml(d.turn_id));
    updateUsage(d.usage);

    if (d.capped) {{
      // Over the dollar cap: this turn was not recorded, so the thread so far is
      // still a valid conversation to leave as it is.
      asked = asked || !!d.conversation_id;
      done('limit');
      return;
    }}

    convoId = d.conversation_id || convoId;
    if (typeof d.is_private === 'boolean') convoPrivate = d.is_private;
    asked = true; setConvoUrl(convoId);
    recentUpsert(convoId, d.followups_left === 0);
    done(d.followups_left === 0 ? 'limit' : 'ready');
    turn.scrollIntoView({{behavior:'smooth', block:'start'}});
  }} catch(e) {{
    if (stale()) {{ dropLate(false); return; }}
    console.error('FP&A Buddy ask failed', e);
    answerEl.innerHTML = '<span style="color:var(--alert);">Something went wrong. Try again.</span>';
    qEl.value = q; qEl.dispatchEvent(new Event('input'));
    done(asked ? 'ready' : 'none');
  }}
}}

document.addEventListener('keydown', function(e) {{
  if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') doAsk(!!(e.target && e.target.id === 'fu-q'));
}});

// Thread open: while anything is in #ask-thread the page drops the
// illustrative example and folds "Search past questions" to one line. One
// observer on the thread covers every way a thread appears or clears (ask,
// resume, reload, Start a new conversation), so no send path has to remember it.
(function() {{
  var page = document.getElementById('fpa-page');
  var thread = document.getElementById('ask-thread');
  var pq = document.getElementById('past-questions');
  var open = false;
  // A search the reader just ran (or a link to the section) stays visible.
  var keepPq = /[?&]pq=/.test(location.search) || location.hash === '#past-questions';
  function sync() {{
    var now = thread.children.length > 0;
    if (now === open) return;
    open = now;
    page.classList.toggle('fpa-thread-open', open);
    if (!pq) return;
    if (open) {{ if (!keepPq) pq.open = false; keepPq = false; }}
    else pq.open = true;
  }}
  new MutationObserver(sync).observe(thread, {{childList: true}});
  if (pq) {{
    // In the empty state the section is not collapsible, even from the keyboard.
    pq.addEventListener('toggle', function() {{ if (!open && !pq.open) pq.open = true; }});
    // The search is a plain GET: carry the open conversation through it so the
    // reload reopens the thread instead of dropping it.
    var pqForm = pq.querySelector('form');
    if (pqForm) pqForm.addEventListener('submit', function() {{
      if (!convoId) return;
      var h = document.createElement('input');
      h.type = 'hidden'; h.name = 'c'; h.value = convoId;
      pqForm.appendChild(h);
    }});
  }}
  sync();
}})();

updateEstimate();
loadRecent();
ddLabels();
// /ask/history links here with ?resume=<id>: open that thread once. The
// parameter is stripped first, so a reload goes back to the collapsed state.
(function() {{
  var rp = new URLSearchParams(location.search).get('resume');
  if (rp) {{ setConvoUrl(null); resumeConvoById(rp); }}
}})();
// A reload expands nothing. A conversation named in the URL (?c=) comes back as
// its collapsed row in Recent conversations, highlighted and scrolled into view.
function highlightRecent() {{
  var c = new URLSearchParams(location.search).get('c');
  if (!c) return;
  var items = document.querySelectorAll('#ask-recent .ask-recent-item');
  for (var i = 0; i < items.length; i++) {{
    if (items[i].getAttribute('data-cid') === c) {{
      items[i].classList.add('recent-hl');
      items[i].scrollIntoView({{block:'center'}});
      return;
    }}
  }}
}}
</script>"""

    return HTMLResponse(_page("FP&A Buddy—Brian Weisberg", "CFO Toolbox", body, role=_role(request), request=request))


@app.post("/ask/similar")
async def ask_similar(request: Request):
    """Free text check before a new question runs: up to three earlier first-turn
    questions that may already answer it. No model call, no cost. Visibility is
    the same shared rule the past-questions list uses (Library.ask_visibility_clause):
    never another user's private or hidden question; an admin sees all, labelled."""
    _require_member(request)
    from linklib.similar_questions import rank_similar
    payload = await request.json()
    question = (payload.get("question") or "").strip()[:2000]
    if not question:
        return {"suggestions": []}
    authed = _is_authed(request)
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        cands = lib.similar_ask_candidates(user_id, authed)
    finally:
        lib.close()
    out = []
    for r in rank_similar(question, cands):
        a_html, src_html = _render_cited_answer(r.get("answer") or "", r.get("citations_json") or "[]")
        own = user_id is not None and r.get("user_id") == user_id and bool(r.get("conversation_id"))
        out.append({
            "id": r["id"],
            "question": r.get("question") or "",
            "date": (r.get("created_at") or "")[:10],
            "chips_html": _ask_status_chips_html(r.get("helpful_count"), r.get("negative_count"),
                                                 private=bool(r.get("is_private")),
                                                 hidden=bool(r.get("hidden_public")), viewer_is_admin=authed),
            "private": bool(r.get("is_private")),
            "hidden": bool(r.get("hidden_public")) and authed,
            "answer_html": a_html + src_html,
            "resume_id": r["conversation_id"] if own else "",
        })
    return {"suggestions": out}


@app.post("/ask")
async def ask(request: Request):
    _require_member(request)
    payload = await request.json()
    question = (payload.get("question") or "").strip()
    if not question:
        raise HTTPException(status_code=400, detail="question required")

    model = (payload.get("model") or "")
    effort = (payload.get("effort") or "standard")
    conversation_id = (payload.get("conversation_id") or "").strip()
    is_private = bool(payload.get("private"))   # first turn only; a follow-up inherits
    # Clients no longer send conversation history — on a follow-up the server
    # rebuilds it from the conversation's recorded ask_questions rows below,
    # so fabricated history is impossible. A stale pre-deploy tab may still
    # include a `history` field in the payload; it's ignored (untrusted)
    # rather than rejected so those tabs keep working through the transition.

    raw_sources = payload.get("sources") or ["library", "feed"]
    if isinstance(raw_sources, str):
        raw_sources = [s.strip() for s in raw_sources.split(",")]
    use_library = "library" in raw_sources
    # "web" is the pre-2026-10 chip key, which meant the trusted-domain search.
    # A stale tab that still sends it gets Current feed (trusted), never an
    # unrestricted search; only the explicit "open_web" key turns that on.
    use_feed    = "feed" in raw_sources or "web" in raw_sources
    use_web     = "open_web" in raw_sources

    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        # Orchestration (cap check, conversation-history rebuild, the
        # answer_question() call, and ask_questions recording) is shared
        # with the ask_fpa_buddy MCP tool — see webapp/ask_orchestrator.py.
        # Ownership mirrors the feedback endpoint — 404 for a conversation
        # that doesn't exist, 403 for someone else's.
        try:
            return run_ask(
                lib, user_id, question,
                model=model,
                effort=effort,
                use_library=use_library,
                use_feed=use_feed,
                use_web=use_web,
                conversation_id=conversation_id,
                opml_path=OPML_PATH,
                is_private=is_private,
            )
        except _AskUnknownConversationError:
            raise HTTPException(status_code=404, detail="unknown conversation")
        except _AskForbiddenConversationError:
            raise HTTPException(status_code=403, detail="not your conversation")
        except _AskTurnFailed as e:
            # A failed turn is a 502 with a plain message and the updated
            # spend, never answer text. The raw error stays server-side.
            return JSONResponse({"detail": e.message, "failed": True, "usage": e.usage},
                                status_code=502)
    finally:
        lib.close()


@app.post("/ask/feedback")
async def ask_feedback(request: Request):
    """Record a member's rating of one FP&A Buddy answer (helpful /
    inaccurate / not_helpful, optional short comment). Same auth model as
    POST /ask. One row per turn per user — re-rating updates in place. You
    can only rate turns from your own conversations."""
    _require_member(request)
    payload = await request.json()
    question_id = payload.get("question_id")
    rating = (payload.get("rating") or "").strip()
    comment = (payload.get("comment") or "").strip()[:500]
    if not isinstance(question_id, int):
        raise HTTPException(status_code=400, detail="question_id required")
    if rating not in Library.ASK_FEEDBACK_RATINGS:
        raise HTTPException(status_code=400, detail="unknown rating")

    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        if user_id is None:
            # Token-only / break-glass access has no users row to attribute
            # feedback to — and no recorded turns to rate (POST /ask skips
            # recording for the same reason), so this is consistent, not a gap.
            raise HTTPException(status_code=400, detail="no account to record feedback for")
        turn = lib.get_ask_question(question_id)
        if turn is None:
            raise HTTPException(status_code=404, detail="unknown turn")
        if turn["user_id"] != user_id:
            raise HTTPException(status_code=403, detail="not your conversation")
        lib.record_ask_feedback(question_id, user_id, rating, comment)
        return {"ok": True}
    finally:
        lib.close()


@app.get("/ask/conversations")
def ask_conversations(request: Request):
    """The signed-in user's recent FP&A Buddy conversations — the /ask page's
    resume list (last 5, first question as the label). Same auth model as
    POST /ask; token-only / break-glass access has no recorded turns to
    resume, so it gets an empty list rather than an error."""
    _require_member(request)
    from linklib.agent import MAX_FOLLOWUPS
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        if user_id is None:
            return {"conversations": []}
        return {"conversations": [
            {
                "conversation_id": c["conversation_id"],
                "first_question": c["first_question"] or "",
                "turns": c["turns"],
                "last_at": c["last_at"],
                "capped": c["turns"] >= 1 + MAX_FOLLOWUPS,
                "private": bool(c.get("is_private")),
            }
            for c in lib.list_recent_conversations(user_id, limit=5)
        ]}
    finally:
        lib.close()


@app.get("/ask/conversations/{conversation_id}")
def ask_conversation_transcript(conversation_id: str, request: Request):
    """Full transcript of one of the signed-in user's conversations, for the
    /ask resume flow: per-turn question, answer, citation snapshot (parsed
    from citations_json so the client re-renders [n] markers as links), and
    the user's existing feedback on each turn. 404 for a conversation that
    doesn't exist, 403 for someone else's — the same ownership contract as
    POST /ask and POST /ask/feedback."""
    _require_member(request)
    from linklib.agent import MAX_FOLLOWUPS
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        turns = lib.list_conversation_turns(conversation_id, feedback_user_id=user_id)
        if not turns:
            raise HTTPException(status_code=404, detail="unknown conversation")
        if user_id is None or turns[0]["user_id"] != user_id:
            raise HTTPException(status_code=403, detail="not your conversation")

        def _turn(t: dict) -> dict:
            try:
                cites = json.loads(t.get("citations_json") or "[]")
            except Exception:
                cites = []   # a mangled snapshot degrades to plain text, never a 500
            feedback = None
            if t.get("fb_rating"):
                feedback = {"rating": t["fb_rating"], "comment": t.get("fb_comment") or ""}
            return {
                "turn_id": t["id"],
                "question": t["question"],
                "answer": t["answer"],
                "citations": cites,
                "created_at": t["created_at"],
                "effort": t.get("effort") or "",
                "feedback": feedback,
            }

        followups_left = max(0, 1 + MAX_FOLLOWUPS - len(turns))
        return {
            "conversation_id": conversation_id,
            "private": bool(turns[0].get("is_private")),
            "capped": followups_left == 0,
            "followups_left": followups_left,
            "turns": [_turn(t) for t in turns],
        }
    finally:
        lib.close()


@app.post("/ask/conversations/{conversation_id}/private")
async def ask_conversation_set_private(conversation_id: str, request: Request):
    """Set one of the signed-in user's conversations private or shared again.
    404 for an unknown conversation, 403 for someone else's (same contract as
    the transcript route)."""
    _require_member(request)
    payload = await request.json()
    private = bool(payload.get("private"))
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        turns = lib.list_conversation_turns(conversation_id)
        if not turns:
            raise HTTPException(status_code=404, detail="unknown conversation")
        if user_id is None or turns[0]["user_id"] != user_id:
            raise HTTPException(status_code=403, detail="not your conversation")
        lib.set_conversation_private(conversation_id, user_id, private)
        return {"ok": True, "private": private}
    finally:
        lib.close()


_ASK_HISTORY_PAGE_SIZE = 25


@app.get("/ask/history", response_class=HTMLResponse)
def ask_history(request: Request, page: int = 1):
    """The signed-in user's own FP&A Buddy questions — same shape as the admin
    report (Section G.1) but scoped to just this user, so a member can see
    what they've asked and how their usage-to-date adds up."""
    if not _is_member(request):
        return _login_redirect(request)
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        if user_id is None:
            rows, rating_counts, spent, cap = [], {}, 0.0, lib.get_default_ask_cap()
        else:
            rows = lib.list_ask_questions(user_id=user_id, limit=200)
            rating_counts = lib.ask_rating_counts([r["id"] for r in rows])
            spent = lib.ask_cost_this_month(user_id)
            cap = lib.get_effective_ask_cap(user_id)
        all_time = sum(r["cost_usd"] for r in rows)
    finally:
        lib.close()

    def _resume_link(turns_or_row) -> str:
        # Own history only (this page is scoped to the signed-in user). The
        # fpa-buddy page opens the thread once and strips the parameter.
        r = turns_or_row[0] if isinstance(turns_or_row, list) else turns_or_row
        cid = r.get("conversation_id")
        if not cid:
            return ""
        return (f'<div style="display:flex;justify-content:flex-end;margin:6px 0 12px;">'
                f'<a class="ask-ctl ask-ctl-sm ask-ctl-w" href="/tools/fpa-buddy?resume={_esc(cid)}">Resume</a></div>')

    def _hist_chips(r: dict, *, private: bool | None = None, counts=None) -> str:
        # The same status chips as every other Buddy surface (one function).
        # Hidden is an admin action on the public list, so the owner never sees it here.
        h, n = counts if counts is not None else rating_counts.get(r["id"], (0, 0))
        chips = _ask_status_chips_html(h, n, private=bool(r.get("is_private")) if private is None else private)
        return f'<span style="display:inline-flex;flex-wrap:wrap;gap:6px;margin-right:8px;vertical-align:middle;">{chips}</span>' if chips else ""

    def _single_card(r: dict) -> str:
        # A one-turn conversation — same card the flat list always showed.
        q = _esc(r.get("question") or "")
        a_html, src_html = _render_cited_answer(r.get("answer") or "",
                                                r.get("citations_json") or "[]")
        return f"""<div style="background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin-bottom:12px;">
  <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;">
    <div style="flex:1 1 280px;min-width:0;font-weight:600;color:var(--navy);font-size:14.5px;">{q}</div>
    <div style="font-size:12px;color:var(--muted);white-space:nowrap;">{_esc((r["created_at"] or "")[:10])} &middot; ${r["cost_usd"]:.3f}</div>
  </div>
  <div style="font-size:12px;color:var(--muted);margin:6px 0 8px;">{_hist_chips(r)}{_ask_settings_badge(r)}</div>
  <div class="ask-hist-answer">{a_html}</div>
  {src_html}
  {_resume_link(r)}
</div>"""

    def _turn_block(r: dict) -> str:
        # One turn inside an expanded conversation — same content and
        # citation rendering as the flat card.
        q = _esc(r.get("question") or "")
        a_html, src_html = _render_cited_answer(r.get("answer") or "",
                                                r.get("citations_json") or "[]")
        return f"""<div style="padding:14px 0 4px;border-top:1px solid var(--line);">
  <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;">
    <div style="flex:1 1 280px;min-width:0;font-weight:600;color:var(--navy);font-size:14px;">{q}</div>
    <div style="font-size:12px;color:var(--muted);white-space:nowrap;">{_esc((r["created_at"] or "")[:10])} &middot; ${r["cost_usd"]:.3f}</div>
  </div>
  <div style="font-size:12px;color:var(--muted);margin:6px 0 8px;">{_hist_chips(r, private=False)}{_ask_settings_badge(r)}</div>
  <div class="ask-hist-answer" style="margin-bottom:12px;">{a_html}</div>
  {src_html}
</div>"""

    def _card(turns: list[dict]) -> str:
        if len(turns) == 1:
            return _single_card(turns[0])
        first = turns[0]
        total = sum(t["cost_usd"] for t in turns)
        n = len(turns) - 1
        label = f"{n} follow-up" + ("" if n == 1 else "s")
        q = _esc(first.get("question") or "")
        # Native <details>: tap-to-expand with zero JS, works on any screen.
        return f"""<details class="convo" style="background:var(--surface);border:1px solid var(--line);border-radius:12px;margin-bottom:12px;">
  <summary style="padding:16px 18px;cursor:pointer;">
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;flex-wrap:wrap;">
      <div style="font-weight:600;color:var(--navy);font-size:14.5px;flex:1 1 180px;">{q}</div>
      <div style="font-size:12px;color:var(--muted);white-space:nowrap;">{_esc((first["created_at"] or "")[:10])} &middot; ${total:.3f} total</div>
    </div>
    <div style="margin-top:8px;">{_hist_chips(first, counts=(sum(rating_counts.get(t["id"], (0, 0))[0] for t in turns), sum(rating_counts.get(t["id"], (0, 0))[1] for t in turns)))}</div>
    <span class="convo-chip"><span class="disclosure-caret">&#9654;</span>&nbsp;{label}</span>
  </summary>
  <div style="padding:0 18px 6px;">
    {"".join(_turn_block(t) for t in turns)}
    {_resume_link(turns)}
  </div>
</details>"""

    # Plain pagination, newest first (2026-10): answers now render in full, so
    # 200 long answers made a multi-megabyte page. Every answer on a page is
    # still shown whole; "Older" only moves to the next set of conversations.
    convos = _group_conversations(rows)
    pages = max(1, -(-len(convos) // _ASK_HISTORY_PAGE_SIZE))
    page = min(max(page, 1), pages)
    start = (page - 1) * _ASK_HISTORY_PAGE_SIZE
    shown = convos[start:start + _ASK_HISTORY_PAGE_SIZE]
    _nav_links = []
    if page > 1:
        _nav_links.append(f'<a href="/ask/history?page={page - 1}">&larr; Newer</a>')
    if page < pages:
        _nav_links.append(f'<a href="/ask/history?page={page + 1}" style="margin-left:auto;">Older &rarr;</a>')
    pager_html = (f'<p style="display:flex;gap:12px;font-size:14px;margin:18px 0 0;">{"".join(_nav_links)}</p>'
                  if _nav_links else "")

    rows_html = "".join(_card(c) for c in shown) or \
        ('<div style="background:var(--surface);border:1px solid var(--line);border-radius:12px;'
         'padding:32px;text-align:center;color:var(--muted);">You haven&rsquo;t asked FP&amp;A Buddy anything yet. '
         '<a href="/tools/fpa-buddy">Ask a question &rarr;</a></div>')

    body = f"""<div class="page page-standard">
<div class="tool-prose">
<p style="margin:0 0 4px;"><a href="/tools/fpa-buddy" style="font-size:13px;color:var(--muted);">&larr; FP&amp;A Buddy</a></p>
<h1>Your FP&amp;A Buddy history</h1>
<p style="color:var(--muted);margin:4px 0 22px;">Every question you&rsquo;ve asked, with the answer and what it cost. Others can&rsquo;t see this page or your usage&mdash;it&rsquo;s yours alone. Unless you mark a question private, it may also appear in the <a href="/tools/fpa-buddy#past-questions">past questions list</a> for other users to browse, without your name. See the <a href="/privacy">privacy policy</a>.</p>
<div style="background:var(--navy-wash);border:1px solid var(--line);border-radius:12px;padding:14px 18px;margin-bottom:22px;font-size:14px;">
  <strong>${spent:.2f}</strong> of <strong>${cap:.2f}</strong> used this month &middot; <span style="color:var(--muted);">${all_time:.2f} all time</span>
</div>
{rows_html}
{pager_html}
</div>
<style>
{_ASK_CTL_CSS}
{_ASK_CHIP_CSS}
.convo-chip{{display:inline-flex;align-items:center;margin-top:10px;font-size:12px;font-weight:600;color:var(--navy);background:var(--seafoam);border-radius:999px;padding:4px 12px;}}
.convo-chip .disclosure-caret{{font-size:11px;}}
</style>
</div>"""
    return HTMLResponse(_page("Your FP&A Buddy history—Brian Weisberg", "CFO Toolbox", body, role=_role(request), request=request))


@app.post("/save")
async def save(request: Request, background_tasks: BackgroundTasks, token: str | None = None):
    _check_token(token or request.headers.get("X-Save-Token"))
    payload = {}
    try:
        payload = await request.json()
    except Exception:
        form = await request.form()
        payload = dict(form)
    url = (payload.get("url") or "").strip()
    if not url:
        raise HTTPException(status_code=400, detail="url required")
    tags = payload.get("tags") or []
    if isinstance(tags, str):
        tags = [t.strip() for t in tags.split(",") if t.strip()]
    lib = _lib()
    try:
        row = ingest_url(lib, url, tags=tags, notes=payload.get("note", ""))
        background_tasks.add_task(backup.maybe_backup, DB_PATH)
        return JSONResponse({"ok": True, "id": row["id"], "title": row.get("title"), "tags": row.get("tags", [])})
    finally:
        lib.close()


@app.post("/save-later")
async def save_later(request: Request, token: str | None = None):
    """Token-gated capture into Read Later — the second bookmarklet/Shortcut
    pair's endpoint, mirroring /save's auth exactly (same _check_token, same
    JSON-or-form payload parsing) but writing into the per-user Read Later
    list instead of the shared Archive.

    Read Later (linklib/db.py's `read_later` table) is scoped by user_id, and
    a token-only request has no session to read one from (_current_user_id
    returns None for token-only access, by design — see its docstring). This
    resolves the target list the same way the table's own one-time migration
    already did for its pre-multi-user rows: the earliest admin account
    (Library.default_admin_user_id), since that's Brian's own account and
    this capture path exists for him alone.

    Content caching (2026-08 Reader cleanliness pass): this now does a real
    fetch, same as /save's ingest_url — a bare metadata insert with no fetch
    at all meant every open of an unread item re-fetched live with nothing
    ever cached, and (the actual bug report) meant sponsor/ad/cookie-banner
    content that the shared extraction layer now scrubs never got scrubbed
    for Read Later at save time either. `linklib.extract.fetch_page` +
    `extract_reader_html` are reused directly — no separate scrubbing
    mechanism, the fix lives entirely in extract.py and applies here for
    free. Deliberately best-effort: a fetch failure (dead link, bot-block,
    timeout — any reason) never blocks or rejects the save, same precedent
    as `ingest_url`'s own durability-audit guard — the row still saves with
    empty content, and `_resolve_reader_content` falls through to its
    existing live-fetch-on-open behavior exactly as it did before this PR,
    so a failed save-time fetch is never a regression from today. `title` is
    still optional — the bookmarklet sends `document.title`, but a Shortcut
    may not, and a fresh fetch can now fill in a missing one from the page's
    own <title>/og:title, the same fallback ingest_url already uses via
    fetch_page's title extraction — the (no title) fallback in the Reader's
    Read Later view is now reached only when both the caller AND the fetch
    itself have nothing.

    This does add real latency to the request (a live HTTP fetch on an
    interactive POST) — an accepted, deliberate tradeoff over the previous
    instant-but-unprocessed save, per the Reader/Library backlog
    investigation's own scope decision."""
    _check_token(token or request.headers.get("X-Save-Token"))
    payload = {}
    try:
        payload = await request.json()
    except Exception:
        form = await request.form()
        payload = dict(form)
    url = (payload.get("url") or "").strip()
    if not url:
        raise HTTPException(status_code=400, detail="url required")
    title = (payload.get("title") or "").strip()
    source = (payload.get("source") or "").strip()

    content, content_html = "", ""
    try:
        from linklib.extract import fetch_page, extract_reader_html
        page = fetch_page(url)
        if not title:
            title = page.title or title
        if page.raw_html:
            content_html = extract_reader_html(page.raw_html, url)
        content = page.content or ""
    except Exception:
        pass  # best-effort — see docstring; never blocks the save

    lib = _lib()
    try:
        user_id = lib.default_admin_user_id()
        if user_id is None:
            raise HTTPException(status_code=503, detail="no admin account configured")
        lib.add_read_later(user_id=user_id, url=url, title=title, source=source,
                           content=content, content_html=content_html)
        return JSONResponse({"ok": True})
    finally:
        lib.close()


@app.post("/read-later/refresh")
async def read_later_refresh(request: Request):
    """Manual per-item "Refresh" action for a Read Later row — re-fetches the
    URL and replaces its cached content, on demand only (no automatic
    staleness detection). Session-gated like the rest of the Reader
    (`_is_authed`), unlike /save-later's token-only auth — this is a button
    inside the already-authenticated /read UI, not a cross-origin
    bookmarklet call, so it can and should use the ordinary session cookie
    the same way /api/read-article and /library/{id}/tags already do.

    Never blocks on a failed fetch: `Library.update_read_later_content`'s own
    non-destructive guard means an unsuccessful refresh leaves whatever was
    already cached untouched rather than blanking it, and this route surfaces
    that as `{"ok": false}` (not a 5xx) so the reader pane can show a plain
    "couldn't refresh" status without treating it as a hard error."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    try:
        body = await request.json()
    except Exception:
        body = {}
    url = (body.get("url") or "").strip()
    if not url:
        raise HTTPException(status_code=400, detail="url required")
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        if user_id is None:
            raise HTTPException(status_code=401, detail="unauthorized")
        if lib.get_read_later_by_url(user_id, url) is None:
            raise HTTPException(status_code=404, detail="not in Read Later")
    finally:
        lib.close()

    content, content_html = "", ""
    try:
        from linklib.extract import fetch_page, extract_reader_html
        page = fetch_page(url)
        if page.raw_html:
            content_html = extract_reader_html(page.raw_html, url)
        content = page.content or ""
    except Exception:
        pass

    lib = _lib()
    try:
        ok = lib.update_read_later_content(user_id, url, content, content_html)
        return JSONResponse({"ok": ok})
    finally:
        lib.close()


