@app.post("/admin/reader/backfill-content/manual-review/import/commit")
async def admin_backfill_content_manual_review_import_commit(request: Request):
    """Applies the corrections the preview step showed, one
    Library.apply_article_url_correction call per row (which itself writes
    the url_correction_log trace and verifies the write actually landed).
    Re-validates the article id/url pairing against the current DB state
    rather than trusting the hidden fields blindly, same discipline as
    /admin/overhead-spend/csv/commit — one bad row is skipped and counted,
    not allowed to abort the batch.

    Each row is applied and committed independently (apply_article_url_
    correction commits per row, not once for the whole batch), so a row
    that fails after earlier rows already succeeded must not blow up the
    whole request — earlier commits are already real and permanent by the
    time a later row fails. articles.url is UNIQUE, so a corrected_url that
    already belongs to a different article (a real, if uncommon, collision
    — e.g. two rows independently correcting toward the same already-saved
    piece) raises sqlite3.IntegrityError; caught here and reported per-row,
    same as every other per-row failure mode, instead of taking down the
    whole batch with a bare 500 (the original bug — see the commit that
    added this comment). The bare `except Exception` below is a safety net
    underneath that specific case, not the primary handler for it — it
    exists so a future, unrelated DB error can't reproduce the same
    silent-bare-500 experience."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    import sqlite3
    form = await request.form()
    article_ids = form.getlist("article_id")
    corrected_urls = form.getlist("corrected_url")

    if not article_ids:
        return RedirectResponse(
            f"/admin/reader/backfill-content?error={quote('No corrections to apply—upload a CSV first.')}",
            status_code=303)

    lib = _lib()
    applied = 0
    failures: list[str] = []
    try:
        for i, raw_id in enumerate(article_ids):
            try:
                article_id = int(raw_id)
            except ValueError:
                failures.append(f"row {i + 1}: invalid article id")
                continue
            new_url = corrected_urls[i] if i < len(corrected_urls) else ""
            if not new_url:
                failures.append(f"row {i + 1}: missing corrected_url")
                continue
            try:
                ok = lib.apply_article_url_correction(article_id, new_url, source="csv-import")
            except sqlite3.IntegrityError:
                owner = lib.conn.execute(
                    "SELECT id FROM articles WHERE url=?", (new_url,)).fetchone()
                owner_id = owner["id"] if owner else "?"
                failures.append(
                    f"row {i + 1}: corrected_url already belongs to article #{owner_id}")
                continue
            except Exception as e:
                print(f"[manual-review-import] row {i + 1} (article #{article_id}) failed: {e}")
                failures.append(f"row {i + 1}: failed—see logs")
                continue
            if ok:
                applied += 1
            else:
                failures.append(f"row {i + 1}: article #{article_id} not found")
    finally:
        lib.close()

    msg = f'Applied {applied} correction{"s" if applied != 1 else ""}.'
    if failures:
        shown = "; ".join(failures[:5]) + (" …" if len(failures) > 5 else "")
        msg += f' {len(failures)} row(s) failed: {shown}'
    return RedirectResponse(f"/admin/reader/backfill-content?msg={quote(msg)}", status_code=303)


# ---------------------------------------------------------------------------
# Article purge (durability follow-up, 2026-08) — same export/preview/commit
# CSV round trip as the manual-review corrections above, applied to a
# different, narrower candidate set (see Library.articles_eligible_for_purge).
# Deliberately destructive: nothing here is a soft delete or an "accepted"
# override like the manual-review escape hatch — a confirmed row is
# permanently gone. See linklib.purge_csv's module docstring for the
# confirm-marker vocabulary and the MAX_PURGE_PER_RUN cap.
# ---------------------------------------------------------------------------

@app.get("/admin/reader/backfill-content/purge/export.csv")
def admin_backfill_content_purge_export(request: Request):
    """CSV of every current purge candidate, article_id-keyed, with a blank
    confirm_purge column for the admin to fill in (yes/y/1/x to mark a row
    for deletion) and re-upload via the Preview import form."""
    if not _is_authed(request):
        return _login_redirect(request)
    import csv
    import io

    lib = _lib()
    try:
        rows = lib.articles_eligible_for_purge(limit=100000)
    finally:
        lib.close()

    def _csv_safe(val) -> str:
        # Same formula-injection guard as the manual-review export above.
        s = str(val)
        return "'" + s if s and s[0] in ("=", "+", "-", "@", "\t", "\r") else s

    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(["article_id", "title", "current_url", "word_count", "reason", "confirm_purge"])
    for r in rows:
        writer.writerow([
            r["id"], _csv_safe(r.get("title") or ""), r.get("url") or "",
            r.get("word_count", 0), r.get("content_check_reason") or "",
            "",  # confirm_purge — blank for the admin to fill in
        ])
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    return Response(
        content=buf.getvalue(), media_type="text/csv",
        headers={"Content-Disposition": f'attachment; filename="purge-candidates-{stamp}.csv"'},
    )


