# Internal, Brian-facing notifications — freeform subject/body built inline
# at each call site (not a fixed template), so there's nothing to make
# admin-editable. Listed on /admin/emails purely for the index table, so the
# page is a complete map of every outbound email in the system. Each is
# tagged (subject prefix + X-CFO-Notification-Type header, set in
# send_notification_email) so a mail-client rule can auto-file it by type.
_INTERNAL_EMAIL_ROWS = [
    {"title": "Tool submission notice", "recipient": "You", "trigger": "A user submits a tool on /tools/submit",
     "notification_type": "tool_submission"},
    {"title": "Community submission notice", "recipient": "You", "trigger": "A user submits a community on /tools/communities/submit",
     "notification_type": "community_submission"},
    {"title": "Library submission notice", "recipient": "You", "trigger": "A user suggests an archive piece on /library/submit",
     "notification_type": "library_submission"},
    {"title": "Contact form notice", "recipient": "You", "trigger": "Someone submits /contact",
     "notification_type": "contact"},
    {"title": "Password reset notice", "recipient": "You",
     "trigger": "A user with no email on file requests a password reset",
     "notification_type": "password_reset_no_email"},
]


@app.get("/admin/emails", response_class=HTMLResponse)
def admin_emails_page(request: Request):
    """Every admin-editable outbound email template — subject, body, and
    sign-off, plus a built-in default reference for each — editable here so
    a wording change doesn't need a code deploy. Persisted to the same
    `settings` table as /admin/copy/*; each field falls back to its
    hardcoded default in linklib/email_utils.py when no override has been
    saved. See _email_template_registry() for the list of what's covered."""
    if not _is_authed(request):
        return _login_redirect(request)

    registry = _email_template_registry()

    lib = _lib()
    try:
        for row in registry:
            row["saved_body"] = lib.get_setting(f"{row['prefix']}_body_template")
            row["subject"] = lib.get_setting(f"{row['prefix']}_subject_template") or row["subject_default"]
            row["body"] = row["saved_body"] or row["body_default"]
            row["signoff"] = lib.get_setting(f"{row['prefix']}_signoff") or row["signoff_default"]
    finally:
        lib.close()

    prose = ("width:100%;padding:10px 14px;border:1px solid var(--line);border-radius:10px;"
             "font:14px/1.6 var(--font-body);background:var(--bg);resize:vertical;")

    def _js_str(s: str) -> str:
        return json.dumps(s).replace("</", "<\\/")

    def _placeholder_hint(keys: list[str]) -> str:
        return " &middot; ".join(f"<code>{{{k}}}</code>" for k in keys)

    def _index_table() -> str:
        from linklib.email_utils import NOTIFICATION_TYPE_LABELS
        rows = "".join(
            f'<tr><td style="padding:8px 12px;border-bottom:1px solid var(--line);">'
            f'<a href="#{row["id"]}">{row["title"]}</a></td>'
            f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--ink-soft);">{row["recipient"]}</td>'
            f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--ink-soft);">{row["trigger"]}</td>'
            f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--muted);">&mdash;</td>'
            f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--accent);font-weight:600;">Editable</td></tr>'
            for row in registry
        )
        rows += "".join(
            f'<tr><td style="padding:8px 12px;border-bottom:1px solid var(--line);">{row["title"]}</td>'
            f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--ink-soft);">{row["recipient"]}</td>'
            f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--ink-soft);">{row["trigger"]}</td>'
            f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);"><code>[{NOTIFICATION_TYPE_LABELS[row["notification_type"]]}]</code> in subject</td>'
            f'<td style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--muted);">Internal notice only</td></tr>'
            for row in _INTERNAL_EMAIL_ROWS
        )
        return f"""\
<div class="table-frame" style="overflow-x:auto;overflow-y:hidden;margin:0 0 26px;">
<table style="width:100%;min-width:{_TABLE_FLOOR_MEDIUM}px;border-collapse:collapse;font-size:13px;background:var(--surface);border:1px solid var(--line);border-radius:12px;">
<thead><tr style="text-align:left;">
<th style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--muted);font-weight:600;width:{_COL_WIDTH_NAME}px;">Email</th>
<th style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--muted);font-weight:600;">Recipient</th>
<th style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--muted);font-weight:600;">Sent when</th>
<th style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--muted);font-weight:600;">Filter on</th>
<th style="padding:8px 12px;border-bottom:1px solid var(--line);color:var(--muted);font-weight:600;width:{_COL_WIDTH_STATUS}px;">Editable?</th>
</tr></thead>
<tbody>{rows}</tbody>
</table>
<p style="font-size:12px;color:var(--muted);margin:8px 12px 0;">The three internal notices are also tagged with an <code>X-CFO-Notification-Type</code> header (e.g. <code>tool_submission</code>), for mail clients that can filter on custom headers. Gmail's filter UI can't&mdash;use the subject tag there instead.</p>
</div>"""

    def _section(row: dict) -> str:
        section_id = row["id"]
        has_override = bool(row["saved_body"])
        status_line = (
            "Currently sending your saved override below."
            if has_override else
            "Currently sending the built-in default below&mdash;nothing's been saved for this email yet."
        )
        return f"""\
<div id="{section_id}" style="background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:22px 24px;margin:0 0 18px;scroll-margin-top:16px;">
<div style="font:600 12px var(--font-body);letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:8px;">{row["title"]}</div>
<p style="font-size:13px;color:var(--muted);margin:0 0 6px;">{row["blurb"]}</p>
<p style="font-size:12px;color:var(--muted);margin:0 0 6px;">Placeholders: {_placeholder_hint(row["placeholders"])}</p>
<p id="{section_id}-override-status" style="font-size:12px;color:{'var(--accent)' if has_override else 'var(--muted)'};margin:0 0 14px;font-weight:600;">{status_line}</p>
<label style="font-size:12px;color:var(--muted);display:block;margin-bottom:4px;">Subject</label>
<input id="{section_id}-subject" type="text" value="{_esc(row["subject"])}" style="{prose}margin-bottom:14px;">
<label style="font-size:12px;color:var(--muted);display:block;margin-bottom:4px;">Body</label>
<textarea id="{section_id}-body" rows="10" style="{prose}margin-bottom:14px;">{_esc(row["body"])}</textarea>
<label style="font-size:12px;color:var(--muted);display:block;margin-bottom:4px;">Sign-off</label>
<textarea id="{section_id}-signoff" rows="3" style="{prose}">{_esc(row["signoff"])}</textarea>
<div style="display:flex;gap:10px;margin-top:12px;align-items:center;">
<button id="{section_id}-save-btn" onclick="saveEmailSection('{section_id}')" class="btn" style="font-size:14px;padding:9px 22px;">Save</button>
<span id="{section_id}-status" style="font-size:13px;color:var(--muted);"></span></div>

<details style="margin-top:18px;background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:12px 16px;">
<summary style="cursor:pointer;font-size:13px;font-weight:600;color:var(--navy);display:flex;align-items:baseline;gap:5px;"><span class="disclosure-caret" style="font-size:11px;">&#9654;</span>Built-in default (read-only reference)</summary>
<div style="margin-top:12px;font-size:13px;color:var(--ink-soft);">
<p style="margin:0 0 4px;"><strong>Subject:</strong></p>
<pre style="white-space:pre-wrap;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:10px 12px;margin:0 0 12px;font:13px/1.5 var(--font-body);">{_esc(row["subject_default"])}</pre>
<p style="margin:0 0 4px;"><strong>Body:</strong></p>
<pre style="white-space:pre-wrap;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:10px 12px;margin:0 0 12px;font:13px/1.5 var(--font-body);">{_esc(row["body_default"])}</pre>
<p style="margin:0 0 4px;"><strong>Sign-off:</strong></p>
<pre style="white-space:pre-wrap;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:10px 12px;margin:0 0 12px;font:13px/1.5 var(--font-body);">{_esc(row["signoff_default"])}</pre>
<button type="button" class="btn btn-ghost" style="font-size:13px;padding:7px 16px;" onclick="fillEmailDefault('{section_id}')">Copy default into the fields above</button>
<span style="font-size:12px;color:var(--muted);margin-left:8px;">Still requires Save below to take effect.</span>
</div>
</details>
</div>"""

    sections_html = "\n\n".join(_section(row) for row in registry)
    defaults_json = json.dumps({
        row["id"]: {"subject": row["subject_default"], "body": row["body_default"], "signoff": row["signoff_default"]}
        for row in registry
    }).replace("</", "<\\/")

    body = f"""<div class="page page-standard">
<p style="margin:0 0 4px;"><a href="/admin" style="font-size:13px;color:var(--muted);">&larr; Admin</a></p>
<h1>Email templates</h1>
<p style="color:var(--muted);margin:4px 0 12px;">Edit the subject, body, and sign-off for outbound emails. Changes save straight to the live site.</p>
<div style="background:var(--navy-wash);border:1px solid var(--line);border-radius:12px;padding:14px 18px;margin:0 0 20px;font-size:13px;color:var(--ink-soft);line-height:1.6;">
<p style="margin:0 0 10px;"><strong style="color:var(--navy);">How this works:</strong> each email has a built-in default. You can save your own version below&mdash;whichever is saved is what actually sends.</p>
<ul style="margin:0 0 10px;padding-left:20px;">
<li>Unsaved edits don't count&mdash;only your last Save takes effect.</li>
<li>No auto-reset&mdash;if the built-in default changes later, your saved override keeps winning until you update it yourself.</li>
</ul>
<p style="margin:0;font-size:12px;color:var(--muted);">Each section's &ldquo;Built-in default&rdquo; box always shows the current default, so you can compare or copy it over.</p>
</div>

{_index_table()}

{sections_html}

<script>
var EMAIL_DEFAULTS = {defaults_json};
function fillEmailDefault(id) {{
  var d = EMAIL_DEFAULTS[id];
  document.getElementById(id + '-subject').value = d.subject;
  document.getElementById(id + '-body').value = d.body;
  document.getElementById(id + '-signoff').value = d.signoff;
  var status = document.getElementById(id + '-status');
  status.textContent = 'Default copied in—click Save to use it.'; status.style.color = 'var(--navy)';
}}
async function saveEmailSection(id) {{
  var subject = document.getElementById(id + '-subject').value.trim();
  var bodyText = document.getElementById(id + '-body').value.trim();
  var signoff = document.getElementById(id + '-signoff').value.trim();
  var btn = document.getElementById(id + '-save-btn'), status = document.getElementById(id + '-status');
  if (!subject || !bodyText || !signoff) {{ status.textContent = "Can't save an empty field."; status.style.color = '#b91c1c'; return; }}
  btn.disabled = true; btn.textContent = 'Saving…';
  try {{
    var r = await fetch('/admin/emails/' + id, {{method:'POST', headers:{{'Content-Type':'application/json'}},
      body: JSON.stringify({{subject: subject, body: bodyText, signoff: signoff}})}});
    if (!r.ok) {{
      var err = await r.json().catch(function() {{ return {{}}; }});
      throw new Error(err.detail || 'Save failed');
    }}
    status.textContent = 'Saved.'; status.style.color = '#065f46';
    var overrideStatus = document.getElementById(id + '-override-status');
    overrideStatus.textContent = 'Currently sending your saved override below.';
    overrideStatus.style.color = 'var(--accent)';
    setTimeout(function() {{ status.textContent = ''; }}, 3000);
  }} catch(e) {{
    status.textContent = e.message || 'Save failed—try again.'; status.style.color = '#b91c1c';
  }} finally {{ btn.disabled = false; btn.textContent = 'Save'; }}
}}
</script>"""
    return HTMLResponse(_page("Email templates—Admin", "Admin", body, authed=True))


@app.post("/admin/emails/{section_id}")
async def admin_emails_save(section_id: str, request: Request):
    """Shared validate-then-save for any /admin/emails section (see
    _email_template_registry()). Raises HTTPException(400) with a
    human-readable detail if subject or body use an unknown placeholder or
    have invalid .format() syntax — catches a typo at save time instead of
    the next real send."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    row = next((r for r in _email_template_registry() if r["id"] == section_id), None)
    if row is None:
        raise HTTPException(status_code=404, detail="Unknown email template")

    from linklib.email_utils import validate_template

    payload = await request.json()
    subject = (payload.get("subject") or "").strip()
    body_text = (payload.get("body") or "").strip()
    signoff = (payload.get("signoff") or "").strip()
    if not (subject and body_text and signoff):
        raise HTTPException(status_code=400, detail="Subject, body, and sign-off are all required.")
    for label, text in (("Subject", subject), ("Body", body_text)):
        error = validate_template(text, row["placeholders"])
        if error:
            raise HTTPException(status_code=400, detail=f"{label}: {error}")
    lib = _lib()
    try:
        lib.set_setting(f"{row['prefix']}_subject_template", subject)
        lib.set_setting(f"{row['prefix']}_body_template", body_text)
        lib.set_setting(f"{row['prefix']}_signoff", signoff)
    finally:
        lib.close()
    return JSONResponse({"ok": True})


@app.post("/admin/library-backup/upload-db", response_class=HTMLResponse)
async def upload_db(request: Request, file: UploadFile = File(...), token: str | None = None):
    _require_api(request, token)
    import sqlite3
    import tempfile

    dest = os.path.abspath(DB_PATH)
    dest_dir = os.path.dirname(dest) or "."
    fd, tmp = tempfile.mkstemp(dir=dest_dir, suffix=".upload")
    try:
        with os.fdopen(fd, "wb") as out:
            while True:
                chunk = await file.read(1 << 20)
                if not chunk:
                    break
                out.write(chunk)
        # Validate it's a real library DB before swapping anything in.
        try:
            check = sqlite3.connect(tmp)
            n = check.execute("SELECT COUNT(*) FROM articles").fetchone()[0]
            check.close()
        except Exception as e:
            raise HTTPException(status_code=400,
                                detail=f"That doesn't look like a valid database: {e}")
        # Atomic swap, then clear any stale WAL sidecars from the old file.
        os.replace(tmp, dest)
        tmp = None
        for sidecar in ("-wal", "-shm"):
            try:
                os.remove(dest + sidecar)
            except FileNotFoundError:
                pass
    finally:
        if tmp and os.path.exists(tmp):
            os.remove(tmp)

    return RedirectResponse(f"/admin/library-backup?uploaded={n}", status_code=303)


@app.get("/admin/library-backup/download-db")
def download_db(request: Request):
    """Download a consistent snapshot of the live database (manual backup)."""
    if not _is_authed(request):
        return _login_redirect(request)
    from starlette.background import BackgroundTask

    tmp = backup.snapshot_to_file(DB_PATH)
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    return FileResponse(
        tmp,
        media_type="application/octet-stream",
        filename=f"library-{stamp}.db",
        background=BackgroundTask(lambda: os.path.exists(tmp) and os.remove(tmp)),
    )


@app.post("/admin/backup-now", response_class=HTMLResponse)
def backup_now_route(request: Request, token: str | None = None):
    """Force an immediate off-site backup, bypassing the debounce.
    Also the target of the daily Railway Cron Service (RUNBOOK.md §7—
    migrated off a GitHub Actions schedule, 2026-08, after a GitHub billing
    outage silently stopped that schedule firing) — the status code below
    is not decorative: it's how the cron service (and any future
    monitoring) tells success from failure, since a browser click used to
    get 200 either way and only the rendered message differed."""
    _require_api(request, token)
    try:
        result = backup.backup_now(DB_PATH)
        msg = (f"Uploaded <strong>{result['name']}</strong> ({result['bytes']:,} bytes, "
               f"{result['row_count']:,} articles) to Google Drive.")
        status_code = 200
    except Exception as e:
        # backup.backup_now() logs every failure to backup_log before it
        # ever raises — including "not configured" — so this branch only
        # has to pick the right message/status code, not do any logging
        # of its own (see linklib/backup.py's backup_now() docstring).
        if not backup.is_configured():
            msg = ("Backup not configured. Set <code>GOOGLE_OAUTH_CLIENT_ID</code>, "
                   "<code>GOOGLE_OAUTH_CLIENT_SECRET</code>, and "
                   "<code>GOOGLE_OAUTH_REFRESH_TOKEN</code> to enable Google Drive backups.")
            status_code = 503
        else:
            msg = f"Backup failed: {e}"
            status_code = 502
    body = f"""<div class="page page-standard"><h1>Backup</h1><p>{msg}</p>
  <p style="margin-top:1rem;"><a href="/read?view=saved">Back to Archive →</a></p></div>"""
    return HTMLResponse(_page("Backup", "", body, authed=True), status_code=status_code)


@app.get("/bookmarklet", response_class=PlainTextResponse)
def bookmarklet(request: Request):
    """A one-click saver bookmarklet. SAVE_TOKEN is read fresh from the
    module-level global on every request — it's already re-populated from
    LINKLIB_SAVE_TOKEN at process start, so a token rotation is already
    reflected here as soon as the app restarts with the new env var (see
    CLAUDE.md: "if you rotate LINKLIB_SAVE_TOKEN, re-grab the bookmarklet"—
    what that note is guarding against is a stale COPY sitting in someone's
    bookmarks bar, not this page serving a stale value).

    2026-08 wrap-up sprint item 2 fix: the fetch-options object here used to
    have one unbalanced closing brace (`body:JSON.stringify({url:u,tags:t})}}`
    closed the options object twice, before `.then` ever ran) — a syntax
    error, so every copy of this snippet was a silent no-op: it never threw
    anywhere visible, it just never executed. Fixed, and a `.catch` was added
    to the fetch chain so a network/CORS failure (see the _save_cors
    middleware above — /save now actually answers a cross-origin POST, which
    it previously couldn't) alerts visibly too — this bookmarklet should
    never fail completely silently again."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    token_param = f"?token={SAVE_TOKEN}" if SAVE_TOKEN else ""
    js = (
        "javascript:(function(){"
        "var t=prompt('Tags (comma-separated, optional):');"
        "if(t===null)return;"
        "var u=location.href;"
        f"fetch('{PUBLIC_BASE}/save{token_param}',{{method:'POST',headers:{{'Content-Type':'application/json'}},"
        "body:JSON.stringify({url:u,tags:t})}).then(function(r){alert(r.ok?'Saved to archive':'Error saving');})"
        ".catch(function(e){alert('Error saving: '+e);});"
        "})();"
    )
    return js


@app.get("/read-later-bookmarklet", response_class=PlainTextResponse)
def read_later_bookmarklet(request: Request):
    """The Read Later counterpart to /bookmarklet — same page, same
    token-refreshed-per-request/login-gate/CORS story (see /bookmarklet's own
    docstring and the _save_cors middleware above), posting to /save-later
    instead of /save. No tags prompt: Read Later has no tags concept
    (add_read_later takes no tags parameter), so this is a genuine one-click
    save with no prompt() interrupting it — unlike the Archive bookmarklet,
    which always asks for optional tags first. `document.title` rides along
    so the Reader's Read Later view has something to show immediately rather
    than falling back to "(no title)"."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    token_param = f"?token={SAVE_TOKEN}" if SAVE_TOKEN else ""
    js = (
        "javascript:(function(){"
        "var u=location.href;"
        "var ti=document.title;"
        f"fetch('{PUBLIC_BASE}/save-later{token_param}',{{method:'POST',headers:{{'Content-Type':'application/json'}},"
        "body:JSON.stringify({url:u,title:ti})}).then(function(r){alert(r.ok?'Saved to Read Later':'Error saving');})"
        ".catch(function(e){alert('Error saving: '+e);});"
        "})();"
    )
    return js


@app.post("/feed/save")
async def feed_save(request: Request, background_tasks: BackgroundTasks):
    """Server-side save proxy — authed via login cookie, no token in client HTML.
    Admin-only: this writes straight into the shared Archive."""
    _require_api(request)
    form = await request.form()
    url = (form.get("url") or "").strip()
    if not url:
        raise HTTPException(status_code=400, detail="url required")
    tags_raw = form.get("tags") or ""
    tags = [t.strip() for t in tags_raw.split(",") if t.strip()] if tags_raw else []
    lib = _lib()
    try:
        row = ingest_url(lib, url, tags=tags)
        _log_archive_audit(lib, request, "add", row.get("id"), detail=url)
        background_tasks.add_task(backup.maybe_backup, DB_PATH)
        # The saved article's id comes back so the Reader can flip straight into
        # its "saved" state (inline tag editor, no "+ Save" button) without a
        # reload or a second lookup — POST /library/{id}/tags needs the id.
        return JSONResponse({"ok": True, "id": row.get("id"), "tags": sorted(set(tags))})
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        lib.close()


@app.post("/feed/read-later")
async def feed_toggle_read_later(request: Request):
    """Add or remove a feed item from the signed-in user's own read-later
    list. Member-tier (any signed-in user, not just admin) — this is a
    personal bookmark, fully scoped to user_id, never shared with or visible
    to any other user."""
    _require_member(request)
    form = await request.form()
    url = (form.get("url") or "").strip()
    if not url:
        raise HTTPException(status_code=400, detail="url required")
    action = (form.get("action") or "add").strip()
    lib = _lib()
    try:
        user_id = _current_user_id(lib, request)
        if user_id is None:
            raise HTTPException(status_code=401, detail="unauthorized")
        if action == "remove":
            lib.remove_read_later(user_id, url)
        else:
            lib.add_read_later(
                user_id=user_id,
                url=url,
                title=(form.get("title") or "").strip(),
                source=(form.get("source") or "").strip(),
                summary=(form.get("summary") or "").strip(),
                published_at=(form.get("published_at") or None),
            )
        return JSONResponse({"ok": True, "action": action})
    finally:
        lib.close()


@app.post("/feed/filters")
async def feed_update_filters(request: Request):
    """Persist custom topic keyword filters (stored in settings table)."""
    _require_api(request)
    import json as _json
    payload = await request.json()
    filters = [str(f).strip() for f in payload.get("filters", []) if str(f).strip()]
    lib = _lib()
    try:
        lib.set_setting("feed_filter_tags", _json.dumps(filters))
        return JSONResponse({"ok": True, "filters": filters})
    finally:
        lib.close()


@app.post("/library/{article_id}/tags")
async def library_update_tags(request: Request, article_id: int):
    """Update tags on a saved article. Accepts JSON or form body."""
    _require_api(request)
    content_type = request.headers.get("content-type", "")
    if "application/json" in content_type:
        payload = await request.json()
        tags_raw = payload.get("tags", [])
        if isinstance(tags_raw, str):
            tags = [t.strip() for t in tags_raw.split(",") if t.strip()]
        else:
            tags = [str(t).strip() for t in tags_raw if str(t).strip()]
    else:
        form = await request.form()
        tags_str = form.get("tags") or ""
        tags = [t.strip() for t in tags_str.split(",") if t.strip()]
    lib = _lib()
    try:
        lib.update_tags(article_id, tags)
        _log_archive_audit(lib, request, "edit", article_id, detail=f"tags={sorted(set(tags))}")
        return JSONResponse({"ok": True, "tags": sorted(set(tags))})
    finally:
        lib.close()


@app.post("/library/{article_id}/delete")
def library_delete(request: Request, article_id: int):
    """Permanently delete a saved article."""
    if not _is_authed(request):
        raise HTTPException(status_code=401, detail="unauthorized")
    lib = _lib()
    try:
        lib.delete_article(article_id)
        _log_archive_audit(lib, request, "delete", article_id)
    finally:
        lib.close()
    return RedirectResponse("/read?view=saved", status_code=303)


@app.get("/static/{filename}")
def static_file(filename: str):
    # basename strips any path components so "../" can't escape the static dir
    safe = os.path.basename(filename)
    path = os.path.join(_STATIC_DIR, safe)
    if not os.path.isfile(path):
        raise HTTPException(status_code=404)
    ext = filename.rsplit(".", 1)[-1].lower()
    media = {"jpg": "image/jpeg", "jpeg": "image/jpeg", "png": "image/png",
             "gif": "image/gif", "svg": "image/svg+xml", "webp": "image/webp",
             "ico": "image/x-icon", "mp3": "audio/mpeg"}.get(ext, "application/octet-stream")
    return FileResponse(path, media_type=media)


@app.get("/static/og/{filename}")
def static_og_file(filename: str):
    """Serves committed social-share-card PNGs from _OG_DIR — a separate
    route/directory pair (same precedent as tools_software_screenshot,
    tools_software_logo, etc. below) because /static/{filename}'s own
    single-segment path param can't match a nested "/og/..." URL at all.
    Same basename-only traversal guard as /static/{filename}."""
    safe = os.path.basename(filename)
    path = os.path.join(_OG_DIR, safe)
    if not os.path.isfile(path):
        raise HTTPException(status_code=404)
    return FileResponse(path, media_type="image/png")


